export const F = [{"id": 1, "cat": "time", "sub": "Current Period", "diff": "basic", "title": "[KPI] MTD", "q": "What is the cumulative total from the 1st of this month to today?", "dax": "[KPI] MTD =\nCALCULATE (\n    [Total Sales],\n    DATESMTD ( M_Date[Date] )\n)", "insight": "<strong>Foundation time measure.</strong> Requires M_Date to be marked as a Date Table in Model View.", "tags": ["DATESMTD", "MTD", "CALCULATE"]}, {"id": 2, "cat": "time", "sub": "Current Period", "diff": "basic", "title": "[KPI] QTD", "q": "What is the cumulative total from the start of this quarter?", "dax": "[KPI] QTD =\nCALCULATE (\n    [Total Sales],\n    DATESQTD ( M_Date[Date] )\n)", "insight": "<strong>Q1 starts Jan 1 by default.</strong> For fiscal quarter, use CALCULATE with a custom DATESBETWEEN instead.", "tags": ["DATESQTD", "QTD", "CALCULATE"]}, {"id": 3, "cat": "time", "sub": "Current Period", "diff": "basic", "title": "[KPI] YTD", "q": "What is the cumulative total from Jan 1 to the selected date?", "dax": "[KPI] YTD =\nTOTALYTD (\n    [Total Sales],\n    M_Date[Date]\n)", "insight": "<strong>Fiscal year end:</strong> Add a 3rd argument — TOTALYTD([Total Sales], M_Date[Date], \"3/31\") for March fiscal year-end.", "tags": ["TOTALYTD", "YTD"]}, {"id": 4, "cat": "time", "sub": "Current Period", "diff": "intermediate", "title": "[KPI] WTD", "q": "What is the total from Monday of this week to today?", "dax": "[KPI] WTD =\nCALCULATE (\n    [Total Sales],\n    FILTER (\n        ALL ( M_Date ),\n        M_Date[WeekNumber] = MAX ( M_Date[WeekNumber] )\n            && M_Date[Year] = MAX ( M_Date[Year] )\n            && M_Date[Date] <= MAX ( M_Date[Date] )\n    )\n)", "insight": "<strong>Requires WeekNumber and Year columns</strong> in M_Date. Add them in Power Query for cleaner DAX.", "tags": ["WTD", "CALCULATE", "FILTER", "ALL"]}, {"id": 5, "cat": "time", "sub": "Current Period", "diff": "intermediate", "title": "[KPI] FYTD", "q": "What is cumulative revenue from the start of the fiscal year (e.g. Apr 1)?", "dax": "[KPI] FYTD =\nTOTALYTD (\n    [Total Sales],\n    M_Date[Date],\n    \"3/31\"\n)", "insight": "<strong>Change \"3/31\"</strong> to match your fiscal year-end. \"6/30\" = July start, \"9/30\" = October start.", "tags": ["TOTALYTD", "FYTD", "Fiscal Year"]}, {"id": 6, "cat": "time", "sub": "Same Period Last Year", "diff": "intermediate", "title": "[KPI] MTD Last Year", "q": "What was the MTD revenue in the same month last year?", "dax": "[KPI] MTD LY =\nCALCULATE (\n    [Revenue MTD],\n    SAMEPERIODLASTYEAR ( M_Date[Date] )\n)", "insight": "<strong>Stacks on your MTD measure.</strong> The SAMEPERIODLASTYEAR shifts the MTD filter context back 12 months automatically.", "tags": ["SAMEPERIODLASTYEAR", "MTD LY", "CALCULATE"]}, {"id": 7, "cat": "time", "sub": "Same Period Last Year", "diff": "intermediate", "title": "[KPI] QTD Last Year", "q": "What was the QTD revenue in the same quarter last year?", "dax": "[KPI] QTD LY =\nCALCULATE (\n    [Revenue QTD],\n    SAMEPERIODLASTYEAR ( M_Date[Date] )\n)", "insight": "<strong>Perfect for quarter boards.</strong> Shows what we achieved at this exact point in Q-1 vs current quarter.", "tags": ["SAMEPERIODLASTYEAR", "QTD LY", "CALCULATE"]}, {"id": 8, "cat": "time", "sub": "Same Period Last Year", "diff": "intermediate", "title": "[KPI] YTD Last Year", "q": "What was the YTD revenue through the same date last year?", "dax": "[KPI] YTD LY =\nCALCULATE (\n    [Revenue YTD],\n    SAMEPERIODLASTYEAR ( M_Date[Date] )\n)", "insight": "<strong>Enables true YTD growth %.</strong> Without this, comparing full-year LY to partial-year current gives a misleading picture.", "tags": ["SAMEPERIODLASTYEAR", "YTD LY", "CALCULATE"]}, {"id": 9, "cat": "time", "sub": "Same Period Last Year", "diff": "intermediate", "title": "[KPI] Same Month Last Year", "q": "What was the total revenue in the exact same month last year?", "dax": "[KPI] Same Month LY =\nCALCULATE (\n    [Total Sales],\n    SAMEPERIODLASTYEAR ( M_Date[Date] )\n)", "insight": "<strong>Granular monthly comparison.</strong> Use this in line charts to show current vs prior year month by month.", "tags": ["SAMEPERIODLASTYEAR", "CALCULATE", "Monthly"]}, {"id": 10, "cat": "time", "sub": "Same Period Last Year", "diff": "intermediate", "title": "[KPI] Same Quarter Last Year", "q": "What was the total revenue in the same quarter last year?", "dax": "[KPI] Same Quarter LY =\nCALCULATE (\n    [Total Sales],\n    DATEADD ( M_Date[Date], -1, YEAR )\n)", "insight": "<strong>Use DATEADD with -1 YEAR</strong> to shift any filter back exactly 12 months, regardless of quarter boundaries.", "tags": ["DATEADD", "CALCULATE", "Quarterly"]}, {"id": 11, "cat": "time", "sub": "Same Period Last Year", "diff": "intermediate", "title": "[KPI] Same Week Last Year", "q": "What was the revenue in the same week number last year?", "dax": "[KPI] Same Week LY =\nCALCULATE (\n    [Total Sales],\n    FILTER (\n        ALL ( M_Date ),\n        M_Date[WeekNumber] = MAX ( M_Date[WeekNumber] )\n            && M_Date[Year] = MAX ( M_Date[Year] ) - 1\n    )\n)", "insight": "<strong>Week-over-week YoY comparison</strong> is critical for retail and FMCG where seasonality is week-specific.", "tags": ["FILTER", "ALL", "WeekNumber", "CALCULATE"]}, {"id": 12, "cat": "time", "sub": "Prior Periods", "diff": "basic", "title": "[KPI] Last Month", "q": "What was the total revenue in the previous calendar month?", "dax": "[KPI] Last Month =\nCALCULATE (\n    [Total Sales],\n    PREVIOUSMONTH ( M_Date[Date] )\n)", "insight": "<strong>Use in KPI cards</strong> to show \"Last Month: £X\" as context alongside the current month value.", "tags": ["PREVIOUSMONTH", "CALCULATE", "Prior Period"]}, {"id": 13, "cat": "time", "sub": "Prior Periods", "diff": "basic", "title": "[KPI] Last Quarter", "q": "What was the total revenue in the previous calendar quarter?", "dax": "[KPI] Last Quarter =\nCALCULATE (\n    [Total Sales],\n    PREVIOUSQUARTER ( M_Date[Date] )\n)", "insight": "<strong>Board report staple.</strong> Combine with QTD for a \"Q current vs Q last\" comparison card.", "tags": ["PREVIOUSQUARTER", "CALCULATE", "Prior Period"]}, {"id": 14, "cat": "time", "sub": "Prior Periods", "diff": "basic", "title": "[KPI] Last Year (Full)", "q": "What was the total revenue across the full prior calendar year?", "dax": "[KPI] Last Year =\nCALCULATE (\n    [Total Sales],\n    PREVIOUSYEAR ( M_Date[Date] )\n)", "insight": "<strong>Full year comparison,</strong> not YTD-matched. Use [Revenue YTD LY] for a fair year-to-date comparison.", "tags": ["PREVIOUSYEAR", "CALCULATE", "Prior Period"]}, {"id": 15, "cat": "time", "sub": "Prior Periods", "diff": "intermediate", "title": "[KPI] Last Month Last Year", "q": "What was revenue in the same month, but from two years ago?", "dax": "[KPI] Last Month LY =\nCALCULATE (\n    [Revenue Last Month],\n    SAMEPERIODLASTYEAR ( M_Date[Date] )\n)", "insight": "<strong>Two-period look-back.</strong> Useful for multi-year trend slides — current, prior month, and prior year same month.", "tags": ["SAMEPERIODLASTYEAR", "PREVIOUSMONTH", "CALCULATE"]}, {"id": 16, "cat": "time", "sub": "Prior Periods", "diff": "intermediate", "title": "[KPI] Last Quarter Last Year", "q": "What was revenue in the same quarter, last year?", "dax": "[KPI] Last Quarter LY =\nCALCULATE (\n    [Total Sales],\n    DATEADD (\n        PREVIOUSQUARTER ( M_Date[Date] ),\n        -1, YEAR\n    )\n)", "insight": "<strong>QoQ YoY analysis.</strong> Comparing Q3-2024 vs Q3-2023 — not just Q3-2024 vs Q2-2024.", "tags": ["DATEADD", "PREVIOUSQUARTER", "CALCULATE"]}, {"id": 17, "cat": "time", "sub": "Prior Periods", "diff": "intermediate", "title": "[KPI] 2 Years Ago (Same Period)", "q": "What was revenue in the same period two years ago?", "dax": "[KPI] 2Y Ago =\nCALCULATE (\n    [Total Sales],\n    DATEADD ( M_Date[Date], -2, YEAR )\n)", "insight": "<strong>3-year trend analysis.</strong> Place this alongside current year and last year for an executive trend visual.", "tags": ["DATEADD", "CALCULATE", "Multi-Year"]}, {"id": 18, "cat": "time", "sub": "Growth %", "diff": "intermediate", "title": "[KPI] MoM Growth %", "q": "What is the % change vs the previous month?", "dax": "[KPI] MoM Growth % =\nVAR _curr = [Total Sales]\nVAR _prev = [Revenue Last Month]\nRETURN\n    DIVIDE ( _curr - _prev, _prev )", "insight": "<strong>Format as percentage.</strong> Use conditional formatting — green above 0, red below. Always use VAR for clarity.", "tags": ["VAR", "DIVIDE", "MoM", "Growth"]}, {"id": 19, "cat": "time", "sub": "Growth %", "diff": "intermediate", "title": "[KPI] QoQ Growth %", "q": "What is the % change vs the previous quarter?", "dax": "[KPI] QoQ Growth % =\nVAR _curr = [Total Sales]\nVAR _prev = [Revenue Last Quarter]\nRETURN\n    DIVIDE ( _curr - _prev, _prev )", "insight": "<strong>QoQ is preferred over YoY</strong> for fast-moving industries where 12 months is too long to wait for feedback.", "tags": ["VAR", "DIVIDE", "QoQ", "Growth"]}, {"id": 20, "cat": "time", "sub": "Growth %", "diff": "intermediate", "title": "[KPI] YoY Growth %", "q": "What is the % change vs the same period last year?", "dax": "[KPI] YoY Growth % =\nVAR _curr = [Total Sales]\nVAR _prev = [Revenue Same Month LY]\nRETURN\n    DIVIDE ( _curr - _prev, _prev )", "insight": "<strong>Most-used growth metric in executive dashboards.</strong> Eliminates seasonal distortion that MoM comparisons suffer from.", "tags": ["VAR", "DIVIDE", "YoY", "Growth"]}, {"id": 21, "cat": "time", "sub": "Growth %", "diff": "intermediate", "title": "[KPI] MTD vs MTD LY %", "q": "Is this month tracking ahead or behind same point last year?", "dax": "[KPI] MTD vs MTD LY % =\nDIVIDE (\n    [Revenue MTD] - [Revenue MTD LY],\n    [Revenue MTD LY]\n)", "insight": "<strong>Critical mid-month KPI.</strong> Sales managers use this daily to know if the current month is winning or needs intervention.", "tags": ["DIVIDE", "MTD", "YoY", "Growth"]}, {"id": 22, "cat": "time", "sub": "Growth %", "diff": "intermediate", "title": "[KPI] QTD vs QTD LY %", "q": "Is this quarter tracking above or below the same point last year?", "dax": "[KPI] QTD vs QTD LY % =\nDIVIDE (\n    [Revenue QTD] - [Revenue QTD LY],\n    [Revenue QTD LY]\n)", "insight": "<strong>Board-level quarterly health check.</strong> Colour-code green/red using KPI visuals for instant status reading.", "tags": ["DIVIDE", "QTD", "YoY", "Growth"]}, {"id": 23, "cat": "time", "sub": "Growth %", "diff": "intermediate", "title": "[KPI] YTD vs YTD LY %", "q": "How much has YTD revenue grown compared to the same point last year?", "dax": "[KPI] YTD vs YTD LY % =\nDIVIDE (\n    [Revenue YTD] - [Revenue YTD LY],\n    [Revenue YTD LY]\n)", "insight": "<strong>The headline annual growth number</strong> every CFO wants on page 1 of the board pack.", "tags": ["DIVIDE", "YTD", "YoY", "Growth"]}, {"id": 24, "cat": "time", "sub": "Growth %", "diff": "intermediate", "title": "[KPI] YoY Absolute Variance", "q": "How many £/$ more or less vs the same period last year?", "dax": "[KPI] YoY Variance =\n[Total Sales] - [Revenue Same Month LY]", "insight": "<strong>Always show both %  and absolute.</strong> A 100% growth sounds impressive but could be £10 → £20. Context matters.", "tags": ["Variance", "YoY", "Absolute"]}, {"id": 25, "cat": "time", "sub": "Growth %", "diff": "intermediate", "title": "[KPI] WoW Growth %", "q": "What is the % change versus last week?", "dax": "[KPI] WoW Growth % =\nVAR _thisWeek = [Total Sales]\nVAR _lastWeek =\n    CALCULATE (\n        [Total Sales],\n        DATEADD ( M_Date[Date], -7, DAY )\n    )\nRETURN\n    DIVIDE ( _thisWeek - _lastWeek, _lastWeek )", "insight": "<strong>Retail and e-commerce staple.</strong> Weekly growth is more actionable than monthly for fast-cycle businesses.", "tags": ["VAR", "DATEADD", "WoW", "Growth"]}, {"id": 26, "cat": "time", "sub": "Rolling Windows", "diff": "intermediate", "title": "[KPI] Rolling 3M", "q": "What is the total revenue for the last 3 months from the selected date?", "dax": "[KPI] Rolling 3M =\nCALCULATE (\n    [Total Sales],\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -3, MONTH\n    )\n)", "insight": "<strong>Smooths short-term volatility.</strong> A single bad month is less alarming when viewed as part of a 3-month window.", "tags": ["DATESINPERIOD", "LASTDATE", "Rolling", "3M"]}, {"id": 27, "cat": "time", "sub": "Rolling Windows", "diff": "intermediate", "title": "[KPI] Rolling 6M", "q": "What is the revenue total over the last 6 months?", "dax": "[KPI] Rolling 6M =\nCALCULATE (\n    [Total Sales],\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -6, MONTH\n    )\n)", "insight": "<strong>Half-year rolling window</strong> is standard for operational review cycles and is less laggy than a 12M window.", "tags": ["DATESINPERIOD", "LASTDATE", "Rolling", "6M"]}, {"id": 28, "cat": "time", "sub": "Rolling Windows", "diff": "intermediate", "title": "[KPI] Rolling 12M (L12M)", "q": "What is the total revenue over the last 12 months from any date?", "dax": "[KPI] Rolling 12M =\nCALCULATE (\n    [Total Sales],\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -12, MONTH\n    )\n)", "insight": "<strong>L12M removes seasonality</strong> without being limited to Jan-Dec. The best KPI for trend lines on dashboards.", "tags": ["DATESINPERIOD", "LASTDATE", "Rolling", "12M", "L12M"]}, {"id": 29, "cat": "time", "sub": "Rolling Windows", "diff": "intermediate", "title": "[KPI] Rolling 30D", "q": "What is the revenue in the last 30 days from today?", "dax": "[KPI] Rolling 30D =\nCALCULATE (\n    [Total Sales],\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -30, DAY\n    )\n)", "insight": "<strong>True 30-day window</strong> — more accurate than \"last month\" which varies between 28-31 days.", "tags": ["DATESINPERIOD", "Rolling", "30D"]}, {"id": 30, "cat": "time", "sub": "Rolling Windows", "diff": "intermediate", "title": "[KPI] Rolling 90D", "q": "What is the revenue over the last 90 days?", "dax": "[KPI] Rolling 90D =\nCALCULATE (\n    [Total Sales],\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -90, DAY\n    )\n)", "insight": "<strong>90-day windows</strong> are widely used in healthcare (patient outcomes), finance (credit assessment) and SaaS (cohort health).", "tags": ["DATESINPERIOD", "Rolling", "90D"]}, {"id": 31, "cat": "time", "sub": "Rolling Windows", "diff": "advanced", "title": "[KPI] L12M vs Prior L12M Growth %", "q": "Is the trailing 12-month trend improving vs the prior 12 months?", "dax": "[KPI] L12M vs Prior L12M % =\nVAR _curr =\n    CALCULATE (\n        [Total Sales],\n        DATESINPERIOD ( M_Date[Date], LASTDATE ( M_Date[Date] ), -12, MONTH )\n    )\nVAR _prev =\n    CALCULATE (\n        [Total Sales],\n        DATESINPERIOD ( M_Date[Date], LASTDATE ( M_Date[Date] ), -24, MONTH ),\n        DATESINPERIOD ( M_Date[Date], LASTDATE ( M_Date[Date] ), -12, MONTH )\n    )\nRETURN\n    DIVIDE ( _curr - _prev, _prev )", "insight": "<strong>Advanced trend signal.</strong> Compares L12M vs the 12 months before that — a momentum indicator used in financial analysis.", "tags": ["VAR", "DATESINPERIOD", "Rolling", "L12M", "Growth"]}, {"id": 32, "cat": "time", "sub": "Averages", "diff": "basic", "title": "[KPI] Daily Average", "q": "What is the average revenue earned per day in the selected period?", "dax": "[KPI] Daily Avg =\nDIVIDE (\n    [Total Sales],\n    COUNTROWS ( M_Date )\n)", "insight": "<strong>Normalises for period length.</strong> Comparing a 31-day month to a 28-day month is unfair — daily average levels the playing field.", "tags": ["DIVIDE", "COUNTROWS", "Daily Average"]}, {"id": 33, "cat": "time", "sub": "Averages", "diff": "intermediate", "title": "[KPI] Monthly Average", "q": "What is the average revenue per calendar month in a year?", "dax": "[KPI] Monthly Avg =\nAVERAGEX (\n    VALUES ( M_Date[MonthKey] ),\n    [Total Sales]\n)", "insight": "<strong>Requires a MonthKey column</strong> in M_Date (e.g. YYYYMM format). Useful for showing a smoothed baseline in trend charts.", "tags": ["AVERAGEX", "VALUES", "Monthly Average"]}, {"id": 34, "cat": "time", "sub": "Averages", "diff": "intermediate", "title": "[KPI] 3M Rolling Average", "q": "What is the smoothed monthly average over the last 3 months?", "dax": "[KPI] [KPI] 3M Rolling Avg =\nAVERAGEX (\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -3, MONTH\n    ),\n    [Total Sales]\n)", "insight": "<strong>Moving average</strong> is the single most effective way to smooth seasonal noise on line charts.", "tags": ["AVERAGEX", "DATESINPERIOD", "Rolling Average", "3M"]}, {"id": 35, "cat": "time", "sub": "Averages", "diff": "intermediate", "title": "[KPI] 6M Rolling Average", "q": "What is the average monthly revenue over the last 6 months?", "dax": "[KPI] [KPI] 6M Rolling Avg =\nAVERAGEX (\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -6, MONTH\n    ),\n    [Total Sales]\n)", "insight": "<strong>6M avg shows medium-term trend.</strong> Place as a reference line on a bar chart so spikes and dips are visible in context.", "tags": ["AVERAGEX", "DATESINPERIOD", "Rolling Average", "6M"]}, {"id": 36, "cat": "time", "sub": "Averages", "diff": "intermediate", "title": "[KPI] 12M Rolling Average", "q": "What is the average monthly revenue over the last 12 months?", "dax": "[KPI] [KPI] 12M Rolling Avg =\nAVERAGEX (\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -12, MONTH\n    ),\n    [Total Sales]\n)", "insight": "<strong>Annual rolling average</strong> eliminates full-year seasonal cycles. A rising 12M average signals genuine growth.", "tags": ["AVERAGEX", "DATESINPERIOD", "Rolling Average", "12M"]}, {"id": 37, "cat": "time", "sub": "Averages", "diff": "intermediate", "title": "[KPI] Daily Average LY", "q": "Was revenue per day higher or lower than the same period last year?", "dax": "[KPI] Daily Avg LY =\nCALCULATE (\n    [Daily Avg Revenue],\n    SAMEPERIODLASTYEAR ( M_Date[Date] )\n)", "insight": "<strong>Accounts for calendar variation</strong> — e.g. Feb 2024 has 29 days vs 28 in 2023. Daily avg gives a fair comparison.", "tags": ["SAMEPERIODLASTYEAR", "Daily Average", "CALCULATE"]}, {"id": 38, "cat": "time", "sub": "Running Totals", "diff": "intermediate", "title": "[KPI] Running Total (All Time)", "q": "What is the cumulative revenue from the very first record to the selected date?", "dax": "[KPI] Running Total =\nCALCULATE (\n    [Total Sales],\n    FILTER (\n        ALL ( M_Date[Date] ),\n        M_Date[Date] <= MAX ( M_Date[Date] )\n    )\n)", "insight": "<strong>All-time cumulative.</strong> Perfect for showing total customer spend, lifetime sales, or bank balance over time.", "tags": ["CALCULATE", "FILTER", "ALL", "Running Total"]}, {"id": 39, "cat": "time", "sub": "Running Totals", "diff": "intermediate", "title": "[KPI] YTD Running Total", "q": "Show cumulative total that resets to zero at the start of each year?", "dax": "YTD [KPI] Running Total =\nCALCULATE (\n    [Total Sales],\n    DATESYTD ( M_Date[Date] )\n)", "insight": "<strong>Classic year-progress chart.</strong> Each year starts fresh at zero — shows how current year is tracking vs prior years side by side.", "tags": ["DATESYTD", "CALCULATE", "Running Total", "YTD"]}, {"id": 40, "cat": "time", "sub": "Running Totals", "diff": "intermediate", "title": "[KPI] Running Total L12M", "q": "What is the 12-month rolling cumulative at any point on the timeline?", "dax": "[KPI] Running Total L12M =\nCALCULATE (\n    [Revenue Rolling 12M],\n    FILTER (\n        ALL ( M_Date[Date] ),\n        M_Date[Date] <= MAX ( M_Date[Date] )\n    )\n)", "insight": "<strong>Builds a rolling annual revenue curve.</strong> Unlike fixed-year YTD, this never resets and shows true momentum.", "tags": ["CALCULATE", "FILTER", "Rolling", "L12M", "Running Total"]}, {"id": 41, "cat": "time", "sub": "Forecast & Projections", "diff": "advanced", "title": "[KPI] Month Forecast (Run Rate)", "q": "If current month pace continues, what will month-end revenue be?", "dax": "[KPI] Month Forecast Run Rate =\nVAR _today      = TODAY ()\nVAR _dayOfMonth = DAY ( _today )\nVAR _daysInMth  = DAY ( EOMONTH ( _today, 0 ) )\nRETURN\n    DIVIDE ( [Revenue MTD], _dayOfMonth ) * _daysInMth", "insight": "<strong>Simple but powerful.</strong> Shows on Day 15 whether the month is on pace. Combine with target for a \"forecast vs target\" card.", "tags": ["VAR", "TODAY", "EOMONTH", "DAY", "Forecast"]}, {"id": 42, "cat": "time", "sub": "Forecast & Projections", "diff": "advanced", "title": "[KPI] Annual Run Rate", "q": "If YTD pace continues, what will the full year revenue be?", "dax": "[KPI] Annual Run Rate =\nVAR _ytdRevenue  = [Revenue YTD]\nVAR _daysElapsed =\n    DATEDIFF (\n        DATE ( YEAR ( TODAY () ), 1, 1 ),\n        TODAY (),\n        DAY\n    )\nRETURN\n    DIVIDE ( _ytdRevenue * 365, _daysElapsed )", "insight": "<strong>Executive KPI.</strong> Compared against annual target it immediately shows if year-end looks achievable.", "tags": ["VAR", "DATEDIFF", "TODAY", "Forecast", "Annual"]}, {"id": 43, "cat": "time", "sub": "Forecast & Projections", "diff": "advanced", "title": "[KPI] Remaining Target MTD", "q": "How much revenue still needs to be achieved to hit the monthly target?", "dax": "[KPI] Remaining Target MTD =\nVAR _target = SUM ( F_Targets[MonthlyTarget] )\nVAR _actual = [Revenue MTD]\nRETURN\n    MAX ( _target - _actual, 0 )", "insight": "<strong>Urgency metric for sales teams.</strong> Displayed in a KPI card — \"£42K still to go this month\" is actionable.", "tags": ["VAR", "MAX", "MTD", "Target", "Forecast"]}, {"id": 44, "cat": "time", "sub": "Forecast & Projections", "diff": "advanced", "title": "Days Remaining in Month", "q": "How many days are left in the current month?", "dax": "Days Remaining in Month =\nVAR _today      = TODAY ()\nVAR _monthEnd   = EOMONTH ( _today, 0 )\nRETURN\n    DATEDIFF ( _today, _monthEnd, DAY )", "insight": "<strong>Context measure.</strong> Use alongside \"Remaining Target\" to calculate required daily rate: [Remaining Target] ÷ [Days Remaining in Month].", "tags": ["VAR", "TODAY", "EOMONTH", "DATEDIFF", "Days"]}, {"id": 45, "cat": "time", "sub": "Forecast & Projections", "diff": "advanced", "title": "[KPI] Required Daily Rate", "q": "How much revenue per day is needed to hit the monthly target from today?", "dax": "[KPI] Required Daily Rate =\nDIVIDE (\n    [Remaining Target MTD],\n    [Days Remaining in Month]\n)", "insight": "<strong>Highly actionable KPI.</strong> Sales leaders use this in daily stand-ups to tell reps exactly what pace is required.", "tags": ["DIVIDE", "Forecast", "Daily Rate", "Target"]}, {"id": 46, "cat": "time", "sub": "Period Comparisons", "diff": "advanced", "title": "[KPI] N Months Ago (Parallel Period)", "q": "What was the revenue exactly N months ago from the current selection?", "dax": "[KPI] 3 Months Ago =\nCALCULATE (\n    [Total Sales],\n    PARALLELPERIOD ( M_Date[Date], -3, MONTH )\n)", "insight": "<strong>PARALLELPERIOD</strong> is more flexible than PREVIOUSMONTH — change -3 to any number. Use -6 for semi-annual, -12 for annual.", "tags": ["PARALLELPERIOD", "CALCULATE", "Period Comparison"]}, {"id": 47, "cat": "time", "sub": "Period Comparisons", "diff": "advanced", "title": "[KPI] First Day of Month", "q": "What is the revenue on just the first day of the selected month?", "dax": "[KPI] First Day of Month =\nCALCULATE (\n    [Total Sales],\n    FILTER (\n        M_Date,\n        M_Date[Date] = STARTOFMONTH ( M_Date[Date] )\n    )\n)", "insight": "<strong>Useful for subscription businesses</strong> that recognise revenue on the first of each month. Also good for daily trend analysis.", "tags": ["STARTOFMONTH", "FILTER", "CALCULATE", "Period"]}, {"id": 48, "cat": "time", "sub": "Period Comparisons", "diff": "intermediate", "title": "Last Date with Sales", "q": "What is the most recent date that had any revenue?", "dax": "Last Sale Date =\nLASTNONBLANK ( M_Date[Date], [Total Sales] )", "insight": "<strong>Data freshness indicator.</strong> Place in a card visual to show \"Data current as of: [date]\" on every dashboard.", "tags": ["LASTNONBLANK", "Last Date"]}, {"id": 49, "cat": "time", "sub": "Period Comparisons", "diff": "intermediate", "title": "Number of Selling Days in Period", "q": "How many days with at least one transaction are in the selected period?", "dax": "Selling Days =\nCOUNTROWS (\n    FILTER (\n        M_Date,\n        NOT ISBLANK ( [Total Sales] )\n    )\n)", "insight": "<strong>Normalise by selling days</strong> not calendar days — a period with 2 bank holidays is not the same as a full trading period.", "tags": ["COUNTROWS", "FILTER", "ISBLANK", "Selling Days"]}, {"id": 50, "cat": "time", "sub": "Weekday vs Weekend", "diff": "intermediate", "title": "[KPI] Weekdays", "q": "What is the total revenue on working days (Mon–Fri) only?", "dax": "[KPI] Weekdays =\nCALCULATE (\n    [Total Sales],\n    FILTER (\n        M_Date,\n        M_Date[DayOfWeek] >= 2\n            && M_Date[DayOfWeek] <= 6\n    )\n)", "insight": "<strong>Requires DayOfWeek column</strong> in M_Date (1=Sun,7=Sat in DAX default). Segment B2B vs B2C patterns by day type.", "tags": ["CALCULATE", "FILTER", "Weekday", "DayOfWeek"]}, {"id": 51, "cat": "time", "sub": "Weekday vs Weekend", "diff": "intermediate", "title": "[KPI] Weekends", "q": "How much revenue is generated on Saturdays and Sundays?", "dax": "[KPI] Weekend =\nCALCULATE (\n    [Total Sales],\n    FILTER (\n        M_Date,\n        M_Date[DayOfWeek] = 1\n            || M_Date[DayOfWeek] = 7\n    )\n)", "insight": "<strong>Retail & hospitality essential.</strong> If weekend revenue drops, it signals a footfall or operations issue on peak trading days.", "tags": ["CALCULATE", "FILTER", "Weekend", "DayOfWeek"]}, {"id": 52, "cat": "time", "sub": "Weekday vs Weekend", "diff": "intermediate", "title": "[KPI] Weekend %", "q": "What share of total revenue comes from weekends?", "dax": "[KPI] Weekend % =\nDIVIDE (\n    [Revenue Weekend],\n    [Total Sales]\n)", "insight": "<strong>Benchmark by industry.</strong> Retail: ~35–45% weekends. B2B SaaS: <10%. Hospitality: 50%+. Spot anomalies instantly.", "tags": ["DIVIDE", "Weekend", "% of Total"]}, {"id": 53, "cat": "time", "sub": "Weekday vs Weekend", "diff": "intermediate", "title": "[KPI] Avg Daily — Weekdays", "q": "What is the average revenue earned on a working day?", "dax": "Avg Daily [KPI] Weekdays =\nDIVIDE (\n    [Revenue Weekdays],\n    CALCULATE (\n        COUNTROWS ( M_Date ),\n        M_Date[DayOfWeek] >= 2,\n        M_Date[DayOfWeek] <= 6\n    )\n)", "insight": "<strong>Operational planning metric.</strong> Divide staffing cost by this to get cost-per-revenue-£ on working days.", "tags": ["DIVIDE", "COUNTROWS", "CALCULATE", "Weekday", "Daily Average"]}, {"id": 54, "cat": "time", "sub": "Weekday vs Weekend", "diff": "intermediate", "title": "[KPI] Avg Daily — Weekends", "q": "What is the average revenue earned on a weekend day?", "dax": "[KPI] Avg Daily Weekends =\nDIVIDE (\n    [Revenue Weekend],\n    CALCULATE (\n        COUNTROWS ( M_Date ),\n        M_Date[DayOfWeek] = 1\n            || M_Date[DayOfWeek] = 7\n    )\n)", "insight": "<strong>Compare against weekday average</strong> to quantify the weekend premium (or penalty). Plan staffing ratios accordingly.", "tags": ["DIVIDE", "COUNTROWS", "CALCULATE", "Weekend", "Daily Average"]}, {"id": 55, "cat": "time", "sub": "Weekday vs Weekend", "diff": "advanced", "title": "[KPI] Public Holidays", "q": "How much revenue is generated on public/bank holidays?", "dax": "[KPI] Public Holidays =\nCALCULATE (\n    [Total Sales],\n    M_Date[IsPublicHoliday] = TRUE ()\n)", "insight": "<strong>Requires IsPublicHoliday boolean column</strong> in M_Date. Populate it in Power Query from a public holiday reference table.", "tags": ["CALCULATE", "IsPublicHoliday", "Holiday"]}, {"id": 56, "cat": "time", "sub": "Weekday vs Weekend", "diff": "advanced", "title": "[KPI] By Day of Week", "q": "How much revenue is earned on Mondays? (Adaptable to any day)", "dax": "[KPI] on Mondays =\nCALCULATE (\n    [Total Sales],\n    M_Date[DayOfWeek] = 2\n)", "insight": "<strong>Change the number</strong> for any day: 1=Sun, 2=Mon, 3=Tue, 4=Wed, 5=Thu, 6=Fri, 7=Sat. Useful for spotting weekly dips.", "tags": ["CALCULATE", "DayOfWeek", "Day Pattern"]}, {"id": 57, "cat": "time", "sub": "Dynamic & Advanced", "diff": "advanced", "title": "Period-to-Date vs Same Period Last Year (Dynamic)", "q": "Dynamically compare current PTD (MTD or QTD) vs prior year?", "dax": "PTD vs PTD LY % =\nVAR _curr =\n    CALCULATE (\n        [Total Sales],\n        DATESMTD ( M_Date[Date] )\n    )\nVAR _ly =\n    CALCULATE (\n        [Total Sales],\n        DATESMTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    DIVIDE ( _curr - _ly, _ly )", "insight": "<strong>Reacts to whatever month is in context.</strong> One measure, works for every month in a matrix — no hard-coding needed.", "tags": ["VAR", "DATESMTD", "SAMEPERIODLASTYEAR", "Dynamic"]}, {"id": 58, "cat": "time", "sub": "Dynamic & Advanced", "diff": "advanced", "title": "Benchmark: Best Month Ever", "q": "What was the highest revenue month in the full dataset?", "dax": "Best Month Ever =\nMAXX (\n    SUMMARIZE (\n        Sales,\n        M_Date[Year],\n        M_Date[MonthNumber]\n    ),\n    [Total Sales]\n)", "insight": "<strong>Motivational KPI.</strong> Show on dashboards alongside MTD — \"You\\'re at 87% of the best month on record\" drives performance.", "tags": ["MAXX", "SUMMARIZE", "Benchmark", "Best Month"]}, {"id": 59, "cat": "time", "sub": "Dynamic & Advanced", "diff": "advanced", "title": "[KPI] Peak Day", "q": "What was the highest single-day revenue in the selected period?", "dax": "[KPI] Peak Day =\nMAXX (\n    VALUES ( M_Date[Date] ),\n    CALCULATE ( [Total Sales] )\n)", "insight": "<strong>Operational insight.</strong> Knowing your peak day helps plan capacity, staffing levels and marketing campaign timing.", "tags": ["MAXX", "VALUES", "CALCULATE", "Peak Day"]}, {"id": 60, "cat": "time", "sub": "Dynamic & Advanced", "diff": "advanced", "title": "Days Since Last Sale", "q": "How many days have passed since the most recent transaction?", "dax": "Days Since Last Sale =\nDATEDIFF (\n    [Last Sale Date],\n    TODAY (),\n    DAY\n)", "insight": "<strong>Customer health indicator.</strong> Per-customer this identifies dormant accounts. Across all sales, flags data pipeline issues.", "tags": ["DATEDIFF", "TODAY", "LASTNONBLANK", "Days"]}, {"id": 61, "cat": "time", "sub": "Dynamic & Advanced", "diff": "advanced", "title": "Percentage of Year Elapsed", "q": "What fraction of the current year has passed?", "dax": "Year % Elapsed =\nDIVIDE (\n    DATEDIFF (\n        DATE ( YEAR ( TODAY () ), 1, 1 ),\n        TODAY (),\n        DAY\n    ),\n    IF ( YEAR ( TODAY () ) % 4 = 0, 366, 365 )\n)", "insight": "<strong>Use as a benchmark line.</strong> If Year % Elapsed = 58% but YTD achievement = 45%, you are behind pace.", "tags": ["DIVIDE", "DATEDIFF", "DATE", "TODAY", "Year Progress"]}, {"id": 62, "cat": "time", "sub": "Dynamic & Advanced", "diff": "advanced", "title": "[KPI] Seasonality Index", "q": "Is this month historically above or below the annual average?", "dax": "[KPI] Seasonality Index =\nVAR _thisMth =\n    CALCULATE (\n        AVERAGEX ( VALUES ( M_Date[Year] ), [Total Sales] ),\n        ALLEXCEPT ( M_Date, M_Date[MonthNumber] )\n    )\nVAR _annAvg =\n    AVERAGEX (\n        VALUES ( M_Date[MonthNumber] ),\n        CALCULATE (\n            AVERAGEX ( VALUES ( M_Date[Year] ), [Total Sales] ),\n            ALLEXCEPT ( M_Date, M_Date[MonthNumber] )\n        )\n    )\nRETURN\n    DIVIDE ( _thisMth, _annAvg )", "insight": "<strong>Index > 1 = strong month, < 1 = weak month.</strong> Use to set realistic targets that adjust for seasonal patterns.", "tags": ["VAR", "AVERAGEX", "ALLEXCEPT", "Seasonality", "Advanced"]}, {"id": 101, "cat": "generic", "sub": "Aggregation", "diff": "basic", "title": "Total Sales", "q": "What is the total sales for any selection?", "dax": "Total Sales =\nSUM ( F_Sales[Sale] )", "insight": "<strong>Foundation measure.</strong> Build all other measures on top of this — never repeat SUM(F_Sales[Sale]) twice in complex formulas.", "tags": ["SUM", "Aggregation"]}, {"id": 102, "cat": "generic", "sub": "Aggregation", "diff": "basic", "title": "Total Quantity Sold", "q": "How many units were sold?", "dax": "Total Quantity =\nSUM ( F_Sales[Qty] )", "insight": "<strong>Volume metric.</strong> Pair with revenue to spot cases where volume grows but revenue doesn\\'t — signals price erosion.", "tags": ["SUM", "Aggregation", "Volume"]}, {"id": 103, "cat": "generic", "sub": "Counting", "diff": "basic", "title": "Total Transactions", "q": "How many unique orders were placed?", "dax": "Total Orders =\nDISTINCTCOUNT ( F_Sales[OrderID] )", "insight": "<strong>Use DISTINCTCOUNT</strong> not COUNT — multi-line orders will be counted once, not once per line item.", "tags": ["DISTINCTCOUNT", "Counting"]}, {"id": 104, "cat": "generic", "sub": "Ratios", "diff": "basic", "title": "Average Order Value", "q": "What is the average revenue per transaction?", "dax": "Avg Order Value =\nDIVIDE ( [Total Sales], [Number of Orders], 0 )", "insight": "<strong>AOV growth means better upsell.</strong> Track alongside conversion rate — AOV up, orders down could net the same revenue.", "tags": ["DIVIDE", "Ratio", "AOV"]}, {"id": 105, "cat": "generic", "sub": "% of Total", "diff": "intermediate", "title": "% of Grand Total", "q": "What percentage does each item contribute to the whole?", "dax": "% of Grand Total =\nDIVIDE (\n    [Total Sales],\n    CALCULATE ( [Total Sales], ALL ( Sales ) )\n)", "insight": "<strong>ALL() strips all filters</strong> so the denominator is always the grand total regardless of what slicers are applied.", "tags": ["DIVIDE", "ALL", "CALCULATE", "% of Total"]}, {"id": 106, "cat": "generic", "sub": "Ranking", "diff": "intermediate", "title": "Revenue Rank", "q": "What rank does each item hold by revenue — descending?", "dax": "Revenue Rank =\nRANKX (\n    ALL ( M_Products[ProductName] ),\n    [Total Sales],,\n    DESC, DENSE\n)", "insight": "<strong>DENSE rank</strong> means no gaps when items tie — two items at #3 are followed by #4, not #5.", "tags": ["RANKX", "ALL", "Ranking", "DENSE"]}, {"id": 107, "cat": "generic", "sub": "Variance", "diff": "intermediate", "title": "Variance vs Target", "q": "How much did actual revenue differ from target?", "dax": "Variance vs Target =\n[Total Sales] - SUM ( F_Targets[TargetRevenue] )", "insight": "<strong>Positive = above target, negative = below.</strong> Add a companion % variance: DIVIDE([Variance vs Target], SUM(Targets[TargetRevenue]))", "tags": ["Variance", "SUM", "Target"]}, {"id": 108, "cat": "generic", "sub": "Aggregation", "diff": "basic", "title": "Stock on Hand", "q": "What is the total quantity of stock currently held across all locations?", "dax": "Stock on Hand =\nSUM ( F_Inventory[QtyOnHand] )", "insight": "<strong>Base inventory measure.</strong> Use this as the foundation for all stock cover and days-of-stock calculations. Never repeat SUM(F_Inventory[QtyOnHand]) in complex formulas — always reference this measure.", "tags": ["SUM", "Aggregation", "Inventory"]}, {"id": 109, "cat": "generic", "sub": "Aggregation", "diff": "basic", "title": "Total Cost", "q": "What is the total direct cost (COGS) for the selected period?", "dax": "Total Cost =\nSUM ( F_Sales[COGS] )", "insight": "<strong>Direct cost base measure.</strong> Covers cost of goods sold at transaction level. Use this in gross profit and margin calculations rather than repeating SUM(F_Sales[COGS]).", "tags": ["SUM", "Aggregation", "COGS", "Cost"]}, {"id": 110, "cat": "generic", "sub": "Aggregation", "diff": "basic", "title": "Total Other Expenses", "q": "What is the total of all indirect operating expenses (non-COGS) in the period?", "dax": "Total Other Expenses =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Operating Expenses\"\n    )\n)", "insight": "<strong>Overhead expense base measure.</strong> Captures all indirect costs from the GL that sit below Gross Profit. Reference this in EBITDA, operating profit, and cost-ratio formulas rather than repeating the CALCULATE block.", "tags": ["SUM", "Aggregation", "Opex", "Expenses"]}, {"id": 111, "cat": "generic", "sub": "Counting", "diff": "basic", "title": "Number of Customers", "q": "How many distinct customers made a purchase in the selected period?", "dax": "Number of Customers =\nDISTINCTCOUNT ( F_Sales[CustomerID] )", "insight": "<strong>Customer volume base measure.</strong> Always use DISTINCTCOUNT — one customer with multiple orders counts as 1. Reference this in all per-customer ratio calculations.", "tags": ["DISTINCTCOUNT", "Counting", "Customers"]}, {"id": 112, "cat": "generic", "sub": "Counting", "diff": "basic", "title": "Number of Salesmen", "q": "How many distinct sales reps generated at least one sale in the selected period?", "dax": "Number of Salesmen =\nDISTINCTCOUNT ( F_Sales[RepID] )", "insight": "<strong>Active rep count.</strong> Counts reps with actual sales, not all reps on the roster. Use as the denominator in revenue-per-rep calculations and rep productivity ratios.", "tags": ["DISTINCTCOUNT", "Counting", "Reps", "Salesmen"]}, {"id": 113, "cat": "generic", "sub": "Counting", "diff": "basic", "title": "Number of Products", "q": "How many distinct products were sold at least once in the selected period?", "dax": "Number of Products =\nDISTINCTCOUNT ( F_Sales[ProductID] )", "insight": "<strong>Active product count.</strong> Reflects selling range breadth. Use as the denominator in avg-sales-per-product and portfolio concentration calculations.", "tags": ["DISTINCTCOUNT", "Counting", "Products"]}, {"id": 114, "cat": "generic", "sub": "Counting", "diff": "basic", "title": "Number of Orders", "q": "How many unique orders were placed in the selected period?", "dax": "Number of Orders =\nDISTINCTCOUNT ( F_Sales[OrderID] )", "insight": "<strong>Transaction volume base measure.</strong> Use DISTINCTCOUNT to avoid counting multi-line orders multiple times. This is the foundation for Average Order Value and order-frequency analysis.", "tags": ["DISTINCTCOUNT", "Counting", "Orders"]}, {"id": 115, "cat": "generic", "sub": "Ratios", "diff": "basic", "title": "Avg Sales per Customer", "q": "What is the average sales amount generated per customer in the selected period?", "dax": "Avg Sales per Customer =\nDIVIDE ( [Total Sales], [Number of Customers], 0 )", "insight": "<strong>Customer spend intensity.</strong> Rising avg sales per customer without growing customer count signals successful upsell/cross-sell. Falling signals customers buying less per visit.", "tags": ["DIVIDE", "Ratio", "Customer", "Average"]}, {"id": 116, "cat": "generic", "sub": "Ratios", "diff": "basic", "title": "Avg Sales per Product", "q": "What is the average revenue generated per distinct product sold?", "dax": "Avg Sales per Product =\nDIVIDE ( [Total Sales], [Number of Products], 0 )", "insight": "<strong>Product revenue intensity.</strong> A rising avg indicates fewer products driving more revenue (concentration). A falling avg may signal range expansion with low-contribution new SKUs.", "tags": ["DIVIDE", "Ratio", "Product", "Average"]}, {"id": 117, "cat": "generic", "sub": "Ratios", "diff": "intermediate", "title": "Avg Sales per Product per Customer", "q": "What is the average revenue per product-customer combination — a measure of basket depth?", "dax": "Avg Sales per Product per Customer =\nVAR _totalSales    = [Total Sales]\nVAR _numProducts   = [Number of Products]\nVAR _numCustomers  = [Number of Customers]\nRETURN\n    DIVIDE ( _totalSales, _numProducts * _numCustomers, 0 )", "insight": "<strong>Basket depth metric.</strong> Combines product breadth and customer count to measure average revenue per product-customer pair. Useful for cross-sell programme effectiveness.", "tags": ["VAR", "DIVIDE", "Ratio", "Product", "Customer", "Average"]}, {"id": 118, "cat": "generic", "sub": "Ratios", "diff": "intermediate", "title": "Avg Sales per Salesman", "q": "What is the average revenue generated per active sales rep?", "dax": "Avg Sales per Salesman =\nDIVIDE ( [Total Sales], [Number of Salesmen], 0 )", "insight": "<strong>Rep productivity benchmark.</strong> Use alongside individual rep rankings to identify the gap between top performers and the average. A rising avg without headcount growth = improved rep productivity.", "tags": ["DIVIDE", "Ratio", "Salesmen", "Rep", "Average"]}, {"id": 201, "cat": "customer", "sub": "Counting & Volume", "diff": "basic", "title": "Active Customers (Period)", "q": "How many distinct customers made at least one purchase in the selected period?", "dax": "Active Customers =\nDISTINCTCOUNT ( F_Sales[CustomerID] )", "insight": "<strong>Core volume KPI.</strong> Always use DISTINCTCOUNT not COUNT — one customer with 10 orders still counts as 1.", "tags": ["DISTINCTCOUNT", "Customer", "Active", "Volume"]}, {"id": 202, "cat": "customer", "sub": "Counting & Volume", "diff": "intermediate", "title": "Customers This Year (CY)", "q": "How many distinct customers purchased in the current calendar year?", "dax": "Customers This Year =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[CustomerID] ),\n    DATESYTD ( M_Date[Date] )\n)", "insight": "<strong>Annual active base.</strong> Compare against [Customers Last Year] to track whether your customer base is growing or shrinking year on year.", "tags": ["CALCULATE", "DISTINCTCOUNT", "DATESYTD", "CY", "Customers"]}, {"id": 203, "cat": "customer", "sub": "Counting & Volume", "diff": "intermediate", "title": "Customers Last Year (LY)", "q": "How many distinct customers purchased in the prior calendar year?", "dax": "Customers Last Year =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[CustomerID] ),\n    SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) )\n)", "insight": "<strong>Prior year baseline.</strong> Divide [Customers This Year] by this to get customer base growth %. A shrinking base despite rising revenue = fewer, larger customers — a concentration risk.", "tags": ["CALCULATE", "DISTINCTCOUNT", "SAMEPERIODLASTYEAR", "LY", "Customers"]}, {"id": 204, "cat": "customer", "sub": "Counting & Volume", "diff": "intermediate", "title": "Customer Base Growth % YoY", "q": "Is the total number of active customers growing or shrinking year on year?", "dax": "Customer Base Growth % =\nDIVIDE (\n    [Customers This Year] - [Customers Last Year],\n    [Customers Last Year]\n)", "insight": "<strong>Health of the funnel.</strong> Revenue can grow while customer base shrinks (higher spend per customer). Both metrics together tell the full story. Declining base needs attention regardless of revenue.", "tags": ["DIVIDE", "YoY", "Growth", "Customer", "Base"]}, {"id": 205, "cat": "customer", "sub": "YoY Customer Comparison", "diff": "advanced", "title": "Retained Customers (Bought Both Years)", "q": "Which customers purchased in both the current and prior year?", "dax": "Retained Customers =\nVAR _cyCustomers =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lyCustomers =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( INTERSECT ( _cyCustomers, _lyCustomers ) )", "insight": "<strong>Core retention measure.</strong> INTERSECT returns only IDs that appear in BOTH sets. Retained customers are your most valuable — they cost nothing to acquire and already trust you.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "INTERSECT", "DATESYTD", "Retention", "CY", "LY"]}, {"id": 206, "cat": "customer", "sub": "YoY Customer Comparison", "diff": "advanced", "title": "Lost Customers (LY not CY)", "q": "How many customers bought last year but have not purchased at all this year?", "dax": "Lost Customers =\nVAR _cyCustomers =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lyCustomers =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( EXCEPT ( _lyCustomers, _cyCustomers ) )", "insight": "<strong>Churn count.</strong> EXCEPT(LY, CY) = customers in LY that are NOT in CY = churned. Every customer here is a lost revenue stream. Build a CRM campaign targeting exactly this list.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "EXCEPT", "DATESYTD", "Churn", "Lost"]}, {"id": 207, "cat": "customer", "sub": "YoY Customer Comparison", "diff": "advanced", "title": "New Customers (CY not LY)", "q": "How many customers bought this year but had never bought in the prior year?", "dax": "New Customers CY =\nVAR _cyCustomers =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lyCustomers =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( EXCEPT ( _cyCustomers, _lyCustomers ) )", "insight": "<strong>Acquisition count.</strong> EXCEPT(CY, LY) = customers in CY that were NOT in LY = genuinely new. Compare against [Lost Customers] — if new < lost, your base is eroding despite acquisition spend.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "EXCEPT", "DATESYTD", "New", "Acquisition"]}, {"id": 208, "cat": "customer", "sub": "YoY Customer Comparison", "diff": "intermediate", "title": "Customer Retention Rate %", "q": "What percentage of last year\\", "dax": "Customer Retention Rate % =\nDIVIDE (\n    [Retained Customers],\n    [Customers Last Year]\n)", "insight": "<strong>Most important CX metric.</strong> Benchmark: SaaS 85%+, Retail 30–40%, B2B Services 70–80%. Rising retention = product-market fit. Falling retention = churn problem that marketing spend cannot mask.", "tags": ["DIVIDE", "Retention", "Rate", "%", "YoY", "Customer"]}, {"id": 209, "cat": "customer", "sub": "YoY Customer Comparison", "diff": "intermediate", "title": "Customer Churn Rate %", "q": "What percentage of last year\\", "dax": "Customer Churn Rate % =\nDIVIDE (\n    [Lost Customers],\n    [Customers Last Year]\n)", "insight": "<strong>Inverse of retention.</strong> Churn Rate % + Retention Rate % = 100%. Even a 5% annual churn means replacing half your base every 14 years — but a 20% churn means replacing your entire base every 5 years.", "tags": ["DIVIDE", "Churn", "Rate", "%", "YoY", "Customer"]}, {"id": 210, "cat": "customer", "sub": "YoY Customer Comparison", "diff": "intermediate", "title": "Customer Acquisition Rate %", "q": "What percentage of this year\\", "dax": "Customer Acquisition Rate % =\nDIVIDE (\n    [New Customers CY],\n    [Customers This Year]\n)", "insight": "<strong>New customer dependency ratio.</strong> If >60% of this year\\'s customers are new, your business is heavily acquisition-dependent — expensive and fragile. Aim for <40% new while growing retained base.", "tags": ["DIVIDE", "Acquisition", "Rate", "%", "New", "Customer"]}, {"id": 211, "cat": "customer", "sub": "YoY Customer Comparison", "diff": "advanced", "title": "Revenue from Retained Customers", "q": "How much of this year\\", "dax": "Revenue from Retained =\nVAR _retained =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        INTERSECT (\n            CALCULATETABLE ( VALUES ( F_Sales[CustomerID] ), DATESYTD ( M_Date[Date] ) ),\n            CALCULATETABLE ( VALUES ( F_Sales[CustomerID] ), SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) ) )\n        )\n    )\nRETURN\n    CALCULATE (\n        [Total Sales],\n        F_Sales[CustomerID] IN _retained\n    )", "insight": "<strong>Revenue quality split.</strong> Use alongside [Revenue from New Customers] to build a stacked bar showing retained vs new revenue composition month by month.", "tags": ["VAR", "CALCULATETABLE", "INTERSECT", "CALCULATE", "Revenue", "Retained"]}, {"id": 212, "cat": "customer", "sub": "YoY Customer Comparison", "diff": "advanced", "title": "Revenue from New Customers (CY Only)", "q": "How much revenue came from customers acquired for the first time this year?", "dax": "Revenue from New Customers =\nVAR _newOnly =\n    CALCULATETABLE (\n        EXCEPT (\n            CALCULATETABLE ( VALUES ( F_Sales[CustomerID] ), DATESYTD ( M_Date[Date] ) ),\n            CALCULATETABLE ( VALUES ( F_Sales[CustomerID] ), SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) ) )\n        )\n    )\nRETURN\n    CALCULATE (\n        [Total Sales],\n        F_Sales[CustomerID] IN _newOnly,\n        DATESYTD ( M_Date[Date] )\n    )", "insight": "<strong>Acquisition revenue quality.</strong> If new customer revenue grows but retained customer revenue falls, you\\'re on a treadmill — spending to acquire what churn takes away.", "tags": ["VAR", "CALCULATETABLE", "EXCEPT", "CALCULATE", "Revenue", "New", "Acquisition"]}, {"id": 213, "cat": "customer", "sub": "Top Customers", "diff": "intermediate", "title": "Customer Revenue Rank", "q": "What rank does each customer hold by total revenue — descending?", "dax": "Customer Revenue Rank =\nRANKX (\n    ALL ( F_Sales[CustomerID] ),\n    [Total Sales],,\n    DESC, DENSE\n)", "insight": "<strong>Use with TOPN filter.</strong> Add a visual-level filter where [Customer Revenue Rank] <= 5 to show your Top 5. Use <= 10 for a Top 10 leaderboard that auto-updates with every slicer change.", "tags": ["RANKX", "ALL", "Rank", "Customer", "Top 5"]}, {"id": 214, "cat": "customer", "sub": "Top Customers", "diff": "intermediate", "title": "Top 5 Customers Revenue %", "q": "What percentage of total revenue comes from the top 5 customers?", "dax": "Top 5 Customer Revenue % =\nVAR _top5Revenue =\n    CALCULATE (\n        [Total Sales],\n        TOPN (\n            5,\n            ALL ( F_Sales[CustomerID] ),\n            [Total Sales]\n        )\n    )\nRETURN\n    DIVIDE ( _top5Revenue, [Total Sales] )", "insight": "<strong>Concentration risk metric.</strong> If top 5 customers = >50% of revenue, losing any one is an existential threat. Healthy businesses aim for <30% in top 5. Use in board packs as a risk indicator.", "tags": ["VAR", "CALCULATE", "TOPN", "ALL", "DIVIDE", "Top 5", "Concentration", "Risk"]}, {"id": 215, "cat": "customer", "sub": "Top Customers", "diff": "intermediate", "title": "Top 5 Customers by YoY Growth", "q": "Which customers grew their spend the most year over year?", "dax": "Customer [KPI] YoY Growth % =\nVAR _curr = [Total Sales]\nVAR _ly =\n    CALCULATE (\n        [Total Sales],\n        SAMEPERIODLASTYEAR ( M_Date[Date] )\n    )\nRETURN\n    DIVIDE ( _curr - _ly, _ly )", "insight": "<strong>Use with RANKX on growth %</strong> to find fastest-growing customers. These are your expansion revenue candidates — prioritise them for upsell conversations and account management attention.", "tags": ["VAR", "CALCULATE", "SAMEPERIODLASTYEAR", "DIVIDE", "YoY", "Growth", "Customer"]}, {"id": 216, "cat": "customer", "sub": "LTV & Spend", "diff": "intermediate", "title": "Customer Lifetime Value (All Time)", "q": "How much has each customer spent across all time — ignoring date slicers?", "dax": "Customer LTV =\nCALCULATE (\n    [Total Sales],\n    ALL ( M_Date )\n)", "insight": "<strong>Remove date filters</strong> with ALL(M_Date) to get all-time value regardless of the time slicer selected. Use in a customer detail table as a permanent column.", "tags": ["CALCULATE", "ALL", "LTV", "Customer", "All Time"]}, {"id": 217, "cat": "customer", "sub": "LTV & Spend", "diff": "intermediate", "title": "Revenue per Active Customer", "q": "What is the average spend per customer in the selected period?", "dax": "Revenue per Customer =\nDIVIDE (\n    [Total Sales],\n    [Active Customers]\n)", "insight": "<strong>Spend intensity metric.</strong> Rising revenue per customer without growing customer count = successful upsell/cross-sell strategy. Falling = customers buying less per visit.", "tags": ["DIVIDE", "Revenue", "Per Customer", "Spend"]}, {"id": 218, "cat": "customer", "sub": "LTV & Spend", "diff": "advanced", "title": "Reactivated Customers", "q": "How many customers who were inactive for 12+ months returned to buy this year?", "dax": "Reactivated Customers =\nVAR _cyCustomers =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _dormant =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESINPERIOD ( M_Date[Date], MIN ( M_Date[Date] ), -24, MONTH ),\n        NOT F_Sales[CustomerID] IN\n            CALCULATETABLE (\n                VALUES ( F_Sales[CustomerID] ),\n                DATESINPERIOD ( M_Date[Date], MIN ( M_Date[Date] ), -12, MONTH )\n            )\n    )\nRETURN\n    COUNTROWS ( INTERSECT ( _cyCustomers, _dormant ) )", "insight": "<strong>Win-back campaign KPI.</strong> Reactivated customers cost less than new acquisition and often return with higher spend. Track this alongside new customer count to measure win-back programme effectiveness.", "tags": ["VAR", "CALCULATETABLE", "INTERSECT", "DATESINPERIOD", "Reactivation", "Win-back"]}, {"id": 219, "cat": "customer", "sub": "Customer YoY Set Analysis", "diff": "intermediate", "title": "Active Customers This Year", "q": "How many distinct customers have purchased at least once this year?", "dax": "Customers This Year =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[CustomerID] ),\n    DATESYTD ( M_Date[Date] )\n)", "insight": "<strong>Current year customer base breadth.</strong> Compare month by month — a rising count through the year shows healthy acquisition momentum. Pair with [Revenue per Customer] to check if growth is quality or just volume.", "tags": ["CALCULATE", "DISTINCTCOUNT", "DATESYTD", "Customers", "This Year"]}, {"id": 220, "cat": "customer", "sub": "Customer YoY Set Analysis", "diff": "intermediate", "title": "Active Customers Last Year", "q": "How many distinct customers purchased at least once last year?", "dax": "Customers Last Year =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[CustomerID] ),\n    SAMEPERIODLASTYEAR ( M_Date[Date] )\n)", "insight": "<strong>Prior year base for YoY comparison.</strong> Always compare at the same point in time (e.g., YTD vs YTD LY) rather than current YTD vs full prior year — the latter comparison is always biased toward decline.", "tags": ["CALCULATE", "DISTINCTCOUNT", "SAMEPERIODLASTYEAR", "Customers", "Last Year"]}, {"id": 221, "cat": "customer", "sub": "Customer YoY Set Analysis", "diff": "advanced", "title": "Retained Customers (Bought Both Years)", "q": "How many customers purchased in both the current and prior year?", "dax": "Retained Customers =\nVAR _thisYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lastYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( INTERSECT ( _thisYear, _lastYear ) )", "insight": "<strong>True retention count.</strong> INTERSECT() returns only the CustomerIDs in both sets. Divide by [Customers Last Year] to get Retention Rate %. This is more precise than formula-based retention because it\\'s based on actual purchase sets.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "INTERSECT", "DATESYTD", "SAMEPERIODLASTYEAR", "Retained", "Customers"]}, {"id": 222, "cat": "customer", "sub": "Customer YoY Set Analysis", "diff": "advanced", "title": "New Customers This Year (Never Bought Before)", "q": "How many customers are buying this year who had zero purchases last year?", "dax": "New Customers This Year =\nVAR _thisYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lastYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( EXCEPT ( _thisYear, _lastYear ) )", "insight": "<strong>Acquisition engine metric.</strong> EXCEPT(TY, LY) = customers in TY that are NOT in LY. New customers are your growth engine but the most expensive to acquire — compare their revenue contribution vs retained customers to justify acquisition spend.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "EXCEPT", "DATESYTD", "SAMEPERIODLASTYEAR", "New Customers"]}, {"id": 223, "cat": "customer", "sub": "Customer YoY Set Analysis", "diff": "advanced", "title": "Lost Customers (Bought LY not TY)", "q": "How many customers purchased last year but have not bought at all this year?", "dax": "Lost Customers =\nVAR _thisYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lastYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[CustomerID] ),\n        DATESYTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( EXCEPT ( _lastYear, _thisYear ) )", "insight": "<strong>Churn without needing a churn flag.</strong> EXCEPT(LY, TY) = customers who bought LY but NOT TY. This is your revenue-at-risk population — target them with win-back campaigns before year-end. Their value = [Customers Lost] × [Average Customer Revenue LY].", "tags": ["VAR", "CALCULATETABLE", "VALUES", "EXCEPT", "DATESYTD", "SAMEPERIODLASTYEAR", "Lost Customers", "Churn"]}, {"id": 224, "cat": "customer", "sub": "Customer YoY Set Analysis", "diff": "advanced", "title": "Customer Retention Rate % (Set-Based)", "q": "What percentage of last year\\", "dax": "Customer Retention Rate % =\nDIVIDE (\n    [Retained Customers],\n    [Customers Last Year]\n)", "insight": "<strong>The most accurate retention metric.</strong> Based on actual purchase set intersection, not a flag. Industry benchmarks: SaaS 85–95%, Retail 30–50%, B2B services 70–85%. Below benchmark = acquisition is plugging a leaky bucket.", "tags": ["DIVIDE", "Retained Customers", "Last Year", "Retention Rate", "%", "Set-Based"]}, {"id": 225, "cat": "customer", "sub": "Customer YoY Set Analysis", "diff": "advanced", "title": "Customer Churn Rate % (Set-Based)", "q": "What percentage of last year\\", "dax": "Customer Churn Rate % =\nDIVIDE (\n    [Lost Customers],\n    [Customers Last Year]\n)", "insight": "<strong>Mirror of retention rate.</strong> [Churn %] = 1 − [Retention %]. If acquisition is keeping totals flat while churn is high, the business is running to stand still — a dangerous and expensive position.", "tags": ["DIVIDE", "Lost Customers", "Last Year", "Churn Rate", "%", "Set-Based"]}, {"id": 226, "cat": "customer", "sub": "Customer YoY Set Analysis", "diff": "advanced", "title": "Revenue from Lost Customers (Value at Risk)", "q": "How much revenue did the lost customers generate last year?", "dax": "Lost Customer Revenue LY =\nVAR _lostIDs =\n    EXCEPT (\n        CALCULATETABLE (\n            VALUES ( F_Sales[CustomerID] ),\n            DATESYTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n        ),\n        CALCULATETABLE (\n            VALUES ( F_Sales[CustomerID] ),\n            DATESYTD ( M_Date[Date] )\n        )\n    )\nRETURN\n    CALCULATE (\n        [Total Sales],\n        KEEPFILTERS ( F_Sales[CustomerID] IN _lostIDs ),\n        SAMEPERIODLASTYEAR ( M_Date[Date] )\n    )", "insight": "<strong>Churn value in £ terms.</strong> This converts the headcount of lost customers into a revenue impact number — the single most compelling way to present churn to a CFO or board. \"We lost 120 customers worth £480K last year\" is far more actionable than \"our churn rate is 12%\".", "tags": ["VAR", "EXCEPT", "CALCULATETABLE", "VALUES", "CALCULATE", "KEEPFILTERS", "SAMEPERIODLASTYEAR", "Lost Revenue", "Churn Value"]}, {"id": 251, "cat": "product", "sub": "Product Volume", "diff": "basic", "title": "Total Products Sold (Distinct SKUs)", "q": "How many distinct products were sold at least once in the selected period?", "dax": "Products Sold =\nDISTINCTCOUNT ( F_Sales[ProductID] )", "insight": "<strong>Range width metric.</strong> Compare against total product catalogue count to see what % of your range is actually selling. A wide gap signals dead stock or ranging problems.", "tags": ["DISTINCTCOUNT", "Products", "SKUs", "Volume"]}, {"id": 252, "cat": "product", "sub": "Product Volume", "diff": "intermediate", "title": "Products Sold This Year (CY)", "q": "How many distinct products have been sold at least once in the current year?", "dax": "Products Sold This Year =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[ProductID] ),\n    DATESYTD ( M_Date[Date] )\n)", "insight": "<strong>Active range for the year.</strong> Compare against [Products Sold Last Year] — a shrinking active range could mean rationalisation (intentional) or demand drop (a problem).", "tags": ["CALCULATE", "DISTINCTCOUNT", "DATESYTD", "CY", "Products"]}, {"id": 253, "cat": "product", "sub": "Product Volume", "diff": "intermediate", "title": "Products Sold Last Year (LY)", "q": "How many distinct products were sold in the prior calendar year?", "dax": "Products Sold Last Year =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[ProductID] ),\n    SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) )\n)", "insight": "<strong>Prior year range baseline.</strong> If CY < LY, your active range is shrinking — either by design or because products are being delisted or going out of stock.", "tags": ["CALCULATE", "DISTINCTCOUNT", "SAMEPERIODLASTYEAR", "LY", "Products"]}, {"id": 254, "cat": "product", "sub": "YoY Product Comparison", "diff": "advanced", "title": "Products Sold Both Years (Common)", "q": "Which products appear in both this year\\", "dax": "Products Sold Both Years =\nVAR _cyProducts =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lyProducts =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( INTERSECT ( _cyProducts, _lyProducts ) )", "insight": "<strong>Core range stability.</strong> INTERSECT gives you the products in BOTH sets. High overlap = stable, consistent range. Low overlap = high churn in your active SKU base — worth investigating by category.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "INTERSECT", "DATESYTD", "Both Years", "Common"]}, {"id": 255, "cat": "product", "sub": "YoY Product Comparison", "diff": "advanced", "title": "Products New This Year (CY only, not LY)", "q": "Which products are selling this year that had zero sales last year?", "dax": "Products New This Year =\nVAR _cyProducts =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lyProducts =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( EXCEPT ( _cyProducts, _lyProducts ) )", "insight": "<strong>New product adoption KPI.</strong> EXCEPT(CY, LY) = products in CY not in LY = newly selling SKUs. High count = strong NPD pipeline. Pair with revenue from these products to assess NPI contribution.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "EXCEPT", "DATESYTD", "New", "NPI", "Launch"]}, {"id": 256, "cat": "product", "sub": "YoY Product Comparison", "diff": "advanced", "title": "Products Dropped This Year (LY only, not CY)", "q": "Which products sold last year but have had zero sales this year?", "dax": "Products Dropped This Year =\nVAR _cyProducts =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lyProducts =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( EXCEPT ( _lyProducts, _cyProducts ) )", "insight": "<strong>Range attrition signal.</strong> EXCEPT(LY, CY) = products in LY NOT in CY = discontinued or stopped selling. Are these planned delistings or demand drops? Classify by investigating sales trends before they stopped.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "EXCEPT", "DATESYTD", "Dropped", "Discontinued"]}, {"id": 257, "cat": "product", "sub": "YoY Product Comparison", "diff": "intermediate", "title": "Product Range Retention Rate %", "q": "What percentage of last year\\", "dax": "Product Range Retention % =\nDIVIDE (\n    [Products Sold Both Years],\n    [Products Sold Last Year]\n)", "insight": "<strong>Range stability KPI.</strong> Low retention % means high SKU churn — lots of products being replaced. Fine if intentional; alarming if caused by demand collapse. Target >75% in a stable portfolio.", "tags": ["DIVIDE", "Range", "Retention", "%", "YoY", "Product"]}, {"id": 258, "cat": "product", "sub": "YoY Product Comparison", "diff": "intermediate", "title": "New Product Revenue Contribution %", "q": "What % of this year\\", "dax": "New Product Revenue % =\nVAR _newProducts =\n    CALCULATETABLE (\n        EXCEPT (\n            CALCULATETABLE ( VALUES ( F_Sales[ProductID] ), DATESYTD ( M_Date[Date] ) ),\n            CALCULATETABLE ( VALUES ( F_Sales[ProductID] ), SAMEPERIODLASTYEAR ( DATESYTD ( M_Date[Date] ) ) )\n        )\n    )\nVAR _newRevenue =\n    CALCULATE (\n        [Total Sales],\n        F_Sales[ProductID] IN _newProducts,\n        DATESYTD ( M_Date[Date] )\n    )\nRETURN\n    DIVIDE ( _newRevenue, [Total Sales] )", "insight": "<strong>NPI vitality metric.</strong> Industry benchmarks: FMCG 20–30% of revenue from products <3 years old. Below 10% signals a stale, innovation-starved range. Above 50% = risky dependency on unproven products.", "tags": ["VAR", "CALCULATETABLE", "EXCEPT", "CALCULATE", "DIVIDE", "NPI", "New Product", "Revenue"]}, {"id": 259, "cat": "product", "sub": "Top Products", "diff": "intermediate", "title": "Product Revenue Rank", "q": "What revenue rank does each product hold — from highest to lowest?", "dax": "Product Revenue Rank =\nRANKX (\n    ALL ( M_Products[ProductName] ),\n    [Total Sales],,\n    DESC, DENSE\n)", "insight": "<strong>Use with visual-level filter</strong> [Product Revenue Rank] <= 5 to show Top 5. Auto-updates with every slicer — no hard-coding of product names needed. Switch to <= 10 or <= 20 easily.", "tags": ["RANKX", "ALL", "Rank", "Product", "Revenue", "Top 5"]}, {"id": 260, "cat": "product", "sub": "Top Products", "diff": "intermediate", "title": "Top 5 Products Revenue %", "q": "What share of total revenue do the top 5 products account for?", "dax": "Top 5 Products Revenue % =\nVAR _top5 =\n    CALCULATE (\n        [Total Sales],\n        TOPN (\n            5,\n            ALL ( M_Products[ProductName] ),\n            [Total Sales]\n        )\n    )\nRETURN\n    DIVIDE ( _top5, [Total Sales] )", "insight": "<strong>Portfolio concentration check.</strong> If top 5 products = >60% of revenue, a single discontinuation, competitor price cut, or supply issue could devastate the business. Aim for <40%.", "tags": ["VAR", "CALCULATE", "TOPN", "ALL", "DIVIDE", "Top 5", "Concentration", "Product"]}, {"id": 261, "cat": "product", "sub": "Top Products", "diff": "intermediate", "title": "Product Quantity Rank", "q": "Which products are top sellers by volume (units sold)?", "dax": "Product Qty Rank =\nRANKX (\n    ALL ( M_Products[ProductName] ),\n    [Total Quantity],,\n    DESC, DENSE\n)", "insight": "<strong>Volume leadership vs revenue leadership</strong> can diverge sharply. A low-price, high-volume product may rank #1 by units but #10 by revenue. Both rankings together reveal your true portfolio architecture.", "tags": ["RANKX", "ALL", "Rank", "Product", "Quantity", "Volume"]}, {"id": 262, "cat": "product", "sub": "Top Products", "diff": "intermediate", "title": "Top 5 Products by Gross Margin %", "q": "Which products are the most profitable after direct costs?", "dax": "Product Margin Rank =\nRANKX (\n    ALL ( M_Products[ProductName] ),\n    DIVIDE (\n        [Total Sales] - SUM ( F_Sales[COGS] ),\n        [Total Sales]\n    ),,\n    DESC, DENSE\n)", "insight": "<strong>Profit leadership ranking.</strong> High-revenue products can be low-margin destroyers. Combine revenue rank and margin rank — products with Top 5 in both are your star performers to protect and grow.", "tags": ["RANKX", "ALL", "DIVIDE", "SUM", "Margin", "Rank", "Top 5", "Product"]}, {"id": 263, "cat": "product", "sub": "Top Products", "diff": "advanced", "title": "Bottom 5 Products (Lowest Revenue)", "q": "Which products generate the least revenue and may be candidates for delisting?", "dax": "Product Bottom Rank =\nRANKX (\n    ALL ( M_Products[ProductName] ),\n    [Total Sales],,\n    ASC, DENSE\n)", "insight": "<strong>Rationalisation tool.</strong> Use [Product Bottom Rank] <= 5 filter. Before delisting, check if these are strategic or complementary products — sometimes a low-revenue item is what brings customers in to buy high-revenue ones.", "tags": ["RANKX", "ALL", "ASC", "Bottom 5", "Rationalisation", "Product"]}, {"id": 264, "cat": "product", "sub": "Product Performance", "diff": "intermediate", "title": "Product Revenue YoY Growth %", "q": "Which products are growing fastest year over year?", "dax": "Product [KPI] YoY Growth % =\nVAR _curr = [Total Sales]\nVAR _ly =\n    CALCULATE (\n        [Total Sales],\n        SAMEPERIODLASTYEAR ( M_Date[Date] )\n    )\nRETURN\n    DIVIDE ( _curr - _ly, _ly )", "insight": "<strong>Use in a matrix</strong> with Product as rows, sorted by this measure descending. Products with strong growth and high margin are your priority investment items.", "tags": ["VAR", "CALCULATE", "SAMEPERIODLASTYEAR", "DIVIDE", "YoY", "Growth", "Product"]}, {"id": 265, "cat": "product", "sub": "Product Performance", "diff": "intermediate", "title": "Average Selling Price per Unit", "q": "What is the average price at which each product is actually selling?", "dax": "Avg Selling Price =\nDIVIDE (\n    [Total Sales],\n    [Total Quantity]\n)", "insight": "<strong>Realised price vs list price.</strong> If avg selling price is significantly below list price, check discounting practices. Rising avg price without volume drop = successful premiumisation.", "tags": ["DIVIDE", "Revenue", "Quantity", "ASP", "Price", "Product"]}, {"id": 266, "cat": "product", "sub": "Product Performance", "diff": "intermediate", "title": "Average Selling Price vs Last Year %", "q": "Have product prices gone up or down compared to last year?", "dax": "ASP vs LY % =\nVAR _aspCY = [Avg Selling Price]\nVAR _aspLY =\n    CALCULATE (\n        DIVIDE ( [Total Sales], [Total Quantity] ),\n        SAMEPERIODLASTYEAR ( M_Date[Date] )\n    )\nRETURN\n    DIVIDE ( _aspCY - _aspLY, _aspLY )", "insight": "<strong>Price trend signal.</strong> Positive = prices have risen (good for margin, watch volume). Negative = price erosion (check competitive pressure or mix shift to lower-priced SKUs).", "tags": ["VAR", "CALCULATE", "SAMEPERIODLASTYEAR", "DIVIDE", "ASP", "Price", "YoY"]}, {"id": 267, "cat": "product", "sub": "Product Performance", "diff": "intermediate", "title": "Product Revenue Contribution %", "q": "What percentage of total revenue does each product contribute?", "dax": "Product Revenue % =\nDIVIDE (\n    [Total Sales],\n    CALCULATE ( [Total Sales], ALL ( Products ) )\n)", "insight": "<strong>Pareto analysis driver.</strong> Sort descending and add running total — you\\'ll typically see 20% of products driving 80% of revenue. This is your core range to protect at all costs.", "tags": ["DIVIDE", "CALCULATE", "ALL", "Contribution", "%", "Pareto", "Product"]}, {"id": 268, "cat": "product", "sub": "Product Performance", "diff": "advanced", "title": "Products with Declining Revenue (Count)", "q": "How many products are showing lower revenue than the same period last year?", "dax": "Declining Products Count =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[ProductID] ),\n    FILTER (\n        VALUES ( F_Sales[ProductID] ),\n        DIVIDE (\n            [Total Sales] - CALCULATE ( [Total Sales], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n            CALCULATE ( [Total Sales], SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n        ) < 0\n    )\n)", "insight": "<strong>Portfolio health scan.</strong> A rising count of declining products is a leading indicator of broader revenue problems — before they show up in totals. Segment by category to find where the decline is concentrated.", "tags": ["CALCULATE", "DISTINCTCOUNT", "FILTER", "VALUES", "SAMEPERIODLASTYEAR", "DIVIDE", "Declining", "Product"]}, {"id": 269, "cat": "product", "sub": "Product YoY Set Analysis", "diff": "intermediate", "title": "Total Products Sold This Year", "q": "How many distinct products have been sold so far in the current year?", "dax": "Products Sold This Year =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[ProductID] ),\n    DATESYTD ( M_Date[Date] )\n)", "insight": "<strong>Portfolio breadth metric.</strong> Compare this against your full active product catalogue count to see what % of your range is generating revenue. A falling number signals SKU rationalisation or range gaps.", "tags": ["CALCULATE", "DISTINCTCOUNT", "DATESYTD", "Products", "This Year"]}, {"id": 270, "cat": "product", "sub": "Product YoY Set Analysis", "diff": "intermediate", "title": "Total Products Sold Last Year", "q": "How many distinct products were sold during the full prior year?", "dax": "Products Sold Last Year =\nCALCULATE (\n    DISTINCTCOUNT ( F_Sales[ProductID] ),\n    SAMEPERIODLASTYEAR ( M_Date[Date] )\n)", "insight": "<strong>Year-over-year product breadth comparison.</strong> Use alongside [Products Sold This Year] to see if the range is expanding, contracting, or stable. Sudden drops often follow range reviews or delisting decisions.", "tags": ["CALCULATE", "DISTINCTCOUNT", "SAMEPERIODLASTYEAR", "Products", "Last Year"]}, {"id": 271, "cat": "product", "sub": "Product YoY Set Analysis", "diff": "advanced", "title": "Products Sold Both This Year AND Last Year (Common)", "q": "Which products appeared in sales in both the current and prior year?", "dax": "Common Products YoY =\nVAR _thisYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lastYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( INTERSECT ( _thisYear, _lastYear ) )", "insight": "<strong>Core range stability indicator.</strong> These are your evergreen products — consistent sellers year on year. Use INTERSECT() to identify them, then use their count as a denominator for \"core range growth rate\" analysis.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "INTERSECT", "DATESYTD", "SAMEPERIODLASTYEAR", "Common Products"]}, {"id": 272, "cat": "product", "sub": "Product YoY Set Analysis", "diff": "advanced", "title": "New Products This Year (Sold TY not LY)", "q": "Which products are selling this year that had zero sales last year?", "dax": "New Products This Year =\nVAR _thisYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lastYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( EXCEPT ( _thisYear, _lastYear ) )", "insight": "<strong>New range or new launches.</strong> EXCEPT(TY, LY) returns products in TY that are NOT in LY. Use in a table visual filtered to these ProductIDs to see new product performance at launch.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "EXCEPT", "DATESYTD", "SAMEPERIODLASTYEAR", "New Products"]}, {"id": 273, "cat": "product", "sub": "Product YoY Set Analysis", "diff": "advanced", "title": "Dropped Products (Sold LY not TY)", "q": "Which products were selling last year but have had zero sales this year?", "dax": "Dropped Products =\nVAR _thisYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( M_Date[Date] )\n    )\nVAR _lastYear =\n    CALCULATETABLE (\n        VALUES ( F_Sales[ProductID] ),\n        DATESYTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    COUNTROWS ( EXCEPT ( _lastYear, _thisYear ) )", "insight": "<strong>Range attrition alert.</strong> EXCEPT(LY, TY) returns products that sold last year but NOT this year. These could be delisted, out of stock, or simply not reordered. Each one warrants a decision: reactivate or formally delist.", "tags": ["VAR", "CALCULATETABLE", "VALUES", "EXCEPT", "DATESYTD", "SAMEPERIODLASTYEAR", "Dropped Products"]}, {"id": 274, "cat": "product", "sub": "Product YoY Set Analysis", "diff": "advanced", "title": "Top 5 Products This Year (Revenue)", "q": "Which are the top 5 revenue-generating products in the current year?", "dax": "Top 5 Products Label =\nVAR _top5 =\n    TOPN (\n        5,\n        CALCULATETABLE (\n            ADDCOLUMNS (\n                VALUES ( M_Products[ProductName] ),\n                \"Rev\", CALCULATE ( [Total Sales], DATESYTD ( M_Date[Date] ) )\n            )\n        ),\n        [Rev], DESC\n    )\nRETURN\n    CONCATENATEX ( _top5, [ProductName], \", \", [Rev], DESC )", "insight": "<strong>Executive summary label.</strong> Use in a card visual — shows the top 5 product names as a comma-separated string. For a ranked table, use RANKX with ALL(Products[ProductName]) filtered to the current year instead.", "tags": ["VAR", "TOPN", "ADDCOLUMNS", "CALCULATETABLE", "CONCATENATEX", "DATESYTD", "Top 5", "Products"]}, {"id": 275, "cat": "product", "sub": "Product YoY Set Analysis", "diff": "advanced", "title": "Top 5 Products Last Year (Revenue)", "q": "Which were the top 5 products by revenue last year?", "dax": "Top 5 Products LY Label =\nVAR _top5LY =\n    TOPN (\n        5,\n        CALCULATETABLE (\n            ADDCOLUMNS (\n                VALUES ( M_Products[ProductName] ),\n                \"Rev\", CALCULATE (\n                    [Total Sales],\n                    SAMEPERIODLASTYEAR ( M_Date[Date] )\n                )\n            )\n        ),\n        [Rev], DESC\n    )\nRETURN\n    CONCATENATEX ( _top5LY, [ProductName], \", \", [Rev], DESC )", "insight": "<strong>Compare against [Top 5 Products Label] (this year).</strong> If the top 5 lists are identical, your range is stable. New entries signal emerging products; disappearing entries signal declining ones that need attention.", "tags": ["VAR", "TOPN", "ADDCOLUMNS", "CALCULATETABLE", "CONCATENATEX", "SAMEPERIODLASTYEAR", "Top 5 LY", "Products"]}, {"id": 276, "cat": "product", "sub": "Product YoY Set Analysis", "diff": "intermediate", "title": "Product Range Growth %", "q": "Has the number of active products being sold grown vs last year?", "dax": "Product Range Growth % =\nDIVIDE (\n    [Products Sold This Year] - [Products Sold Last Year],\n    [Products Sold Last Year]\n)", "insight": "<strong>Portfolio expansion metric.</strong> Positive = selling more distinct products than last year. Use alongside revenue growth — if both are up, growth is broad-based. If revenue is up but product count is down, a smaller core range is working harder.", "tags": ["DIVIDE", "Product Range", "Growth", "%", "YoY"]}, {"id": 301, "cat": "sales", "sub": "Target & Achievement", "diff": "basic", "title": "Sales Achievement %", "q": "What percentage of the sales target has been achieved?", "dax": "Achievement % =\nDIVIDE (\n    [Total Sales],\n    SUM ( F_Targets[SalesTarget] )\n)", "insight": "<strong>Format as percentage.</strong> Segment by rep, region, product to find where the gap lives.", "tags": ["DIVIDE", "Target", "Achievement"]}, {"id": 302, "cat": "sales", "sub": "Target & Achievement", "diff": "intermediate", "title": "Quota Attainment % per Rep", "q": "What percentage of their individual quota has each rep achieved?", "dax": "Quota Attainment % =\nDIVIDE (\n    CALCULATE ( [Total Sales] ),\n    CALCULATE ( SUM ( F_Targets[QuotaAmount] ) )\n)", "insight": "<strong>Use in a matrix</strong> with RepID as rows. Reps below 70% need coaching; reps above 120% may have sandbagged targets.", "tags": ["DIVIDE", "CALCULATE", "Quota", "Rep", "Attainment"]}, {"id": 303, "cat": "sales", "sub": "Target & Achievement", "diff": "intermediate", "title": "Revenue vs Target Variance (Absolute)", "q": "By how much in absolute terms is revenue above or below target?", "dax": "Revenue vs Target Variance =\n[Total Sales] - SUM ( F_Targets[SalesTarget] )", "insight": "<strong>Positive = above target.</strong> Always show both £ variance and % variance — £50K gap means very different things at £500K vs £5M target.", "tags": ["Variance", "Target", "Absolute", "Revenue"]}, {"id": 304, "cat": "sales", "sub": "Pipeline", "diff": "intermediate", "title": "Total Pipeline Value", "q": "What is the total value of all open opportunities regardless of stage?", "dax": "Pipeline Value =\nCALCULATE (\n    SUM ( F_Opportunities[Value] ),\n    F_Opportunities[Stage] <> \"Won\"\n        && F_Opportunities[Stage] <> \"Lost\"\n)", "insight": "<strong>Raw pipeline — not adjusted for probability.</strong> Large raw pipeline with low weighted value signals poor quality deals.", "tags": ["CALCULATE", "SUM", "Pipeline", "Opportunities"]}, {"id": 305, "cat": "sales", "sub": "Pipeline", "diff": "intermediate", "title": "Weighted Pipeline Value", "q": "What is the probability-adjusted forecast value of the pipeline?", "dax": "Weighted Pipeline =\nSUMX (\n    FILTER (\n        Opportunities,\n        F_Opportunities[Stage] <> \"Won\"\n            && F_Opportunities[Stage] <> \"Lost\"\n    ),\n    F_Opportunities[Value] * F_Opportunities[Probability]\n)", "insight": "<strong>Most realistic revenue forecast.</strong> £5M pipeline at 20% average probability = £1M weighted forecast. Compare against remaining target for coverage.", "tags": ["SUMX", "FILTER", "Weighted", "Pipeline", "Probability"]}, {"id": 306, "cat": "sales", "sub": "Pipeline", "diff": "intermediate", "title": "Pipeline Coverage Ratio", "q": "How many times does the pipeline cover the remaining target?", "dax": "Pipeline Coverage =\nDIVIDE (\n    [Pipeline Value],\n    SUM ( F_Targets[SalesTarget] ) - [Total Sales]\n)", "insight": "<strong>3× coverage is healthy.</strong> Below 2× = high risk of missing target. Above 5× may signal poor qualification.", "tags": ["DIVIDE", "Pipeline", "Coverage", "Target"]}, {"id": 307, "cat": "sales", "sub": "Pipeline", "diff": "advanced", "title": "Average Deal Size", "q": "What is the average value of won opportunities?", "dax": "Avg Deal Size =\nDIVIDE (\n    CALCULATE (\n        SUM ( F_Opportunities[Value] ),\n        F_Opportunities[Stage] = \"Won\"\n    ),\n    CALCULATE (\n        COUNTROWS ( Opportunities ),\n        F_Opportunities[Stage] = \"Won\"\n    )\n)", "insight": "<strong>Trend over time.</strong> Falling average deal size with rising deal count signals a shift to smaller customers — affects margins and support costs.", "tags": ["DIVIDE", "CALCULATE", "Deal Size", "Opportunities"]}, {"id": 308, "cat": "sales", "sub": "Pipeline", "diff": "advanced", "title": "Average Sales Cycle Length (Days)", "q": "How many days on average from opportunity creation to close?", "dax": "Avg Sales Cycle Days =\nAVERAGEX (\n    FILTER (\n        Opportunities,\n        F_Opportunities[Stage] = \"Won\"\n            && NOT ISBLANK ( F_Opportunities[CycleStartDate] )\n    ),\n    DATEDIFF (\n        F_Opportunities[CycleStartDate],\n        F_Opportunities[CloseDate],\n        DAY\n    )\n)", "insight": "<strong>Velocity metric.</strong> Shorter cycles = faster revenue. Long cycles indicate poor qualification, complex buying, or pricing friction.", "tags": ["AVERAGEX", "FILTER", "DATEDIFF", "Sales Cycle", "Velocity"]}, {"id": 309, "cat": "sales", "sub": "Win & Loss", "diff": "intermediate", "title": "Win Rate %", "q": "What percentage of closed deals were won?", "dax": "Win Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Opportunities ),\n        F_Opportunities[Stage] = \"Won\"\n    ),\n    CALCULATE (\n        COUNTROWS ( Opportunities ),\n        F_Opportunities[Stage] = \"Won\"\n            || F_Opportunities[Stage] = \"Lost\"\n    )\n)", "insight": "<strong>Only count closed deals</strong> — open pipeline skews the metric. Benchmark: 20–30% outbound, 40–60% inbound.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Win Rate"]}, {"id": 310, "cat": "sales", "sub": "Win & Loss", "diff": "intermediate", "title": "Lost Deal Rate %", "q": "What percentage of closed deals were lost?", "dax": "Loss Rate % =\n1 - [Win Rate %]", "insight": "<strong>Track loss reason.</strong> \"Price\" losses need pricing response. \"Competition\" needs product response. \"No Decision\" needs qualification improvement.", "tags": ["Win Rate", "Loss Rate", "%"]}, {"id": 311, "cat": "sales", "sub": "Win & Loss", "diff": "advanced", "title": "Revenue Lost to Competition", "q": "What is the total value of deals lost to competitors in the period?", "dax": "Revenue Lost to Competition =\nCALCULATE (\n    SUM ( F_Opportunities[Value] ),\n    F_Opportunities[Stage] = \"Lost\",\n    F_Opportunities[LostReason] = \"Competition\",\n    F_Opportunities[CloseDate] >= MIN ( M_Date[Date] ),\n    F_Opportunities[CloseDate] <= MAX ( M_Date[Date] )\n)", "insight": "<strong>Strategic intelligence.</strong> Rising competitive losses signal a product or positioning gap — feeds directly into roadmap and battlecard decisions.", "tags": ["CALCULATE", "SUM", "Lost", "Competition", "Revenue"]}, {"id": 312, "cat": "sales", "sub": "Rep Performance", "diff": "intermediate", "title": "Revenue per Sales Rep", "q": "How much revenue is each rep generating in the period?", "dax": "Revenue per Rep =\nDIVIDE (\n    [Total Sales],\n    DISTINCTCOUNT ( F_Sales[RepID] )\n)", "insight": "<strong>Productivity baseline.</strong> Use in a matrix with RepID as rows alongside [Quota Attainment %] for the full performance picture.", "tags": ["DIVIDE", "DISTINCTCOUNT", "Rep", "Revenue", "Performance"]}, {"id": 313, "cat": "sales", "sub": "Rep Performance", "diff": "advanced", "title": "Rep Revenue Ranking", "q": "Which rep ranks highest by revenue generated?", "dax": "Rep Revenue Rank =\nRANKX (\n    ALL ( F_Sales[RepID] ),\n    [Total Sales],,\n    DESC, DENSE\n)", "insight": "<strong>Leaderboard measure.</strong> Filter to TOPN 5 or 10 reps. Investigate what bottom-quartile reps do differently from top performers.", "tags": ["RANKX", "ALL", "Rep", "Rank", "Leaderboard"]}, {"id": 314, "cat": "sales", "sub": "Revenue Quality", "diff": "intermediate", "title": "New Business Revenue", "q": "How much revenue came from brand-new customers?", "dax": "New Business Revenue =\nCALCULATE (\n    [Total Sales],\n    F_Sales[RevenueType] = \"New\"\n)", "insight": "<strong>Growth engine metric.</strong> Healthy mix: 60–70% renewal (stable base) + 30–40% new (growth). Pair with [Renewal Revenue].", "tags": ["CALCULATE", "Revenue", "New Business", "Type"]}, {"id": 315, "cat": "sales", "sub": "Revenue Quality", "diff": "intermediate", "title": "Renewal Revenue", "q": "How much revenue came from renewing existing customers?", "dax": "Renewal Revenue =\nCALCULATE (\n    [Total Sales],\n    F_Sales[RevenueType] = \"Renewal\"\n)", "insight": "<strong>Retention quality signal.</strong> Falling renewal revenue is an early warning of churn before it hits NPS scores.", "tags": ["CALCULATE", "Revenue", "Renewal", "Retention"]}, {"id": 316, "cat": "sales", "sub": "Revenue Quality", "diff": "intermediate", "title": "Upsell & Cross-sell Revenue %", "q": "What percentage of revenue came from expanding existing accounts?", "dax": "Upsell Revenue % =\nDIVIDE (\n    CALCULATE (\n        [Total Sales],\n        F_Sales[RevenueType] = \"Upsell\"\n    ),\n    [Total Sales]\n)", "insight": "<strong>Expansion revenue is 5–7× cheaper</strong> than new business. Rising upsell % means customer success is working.", "tags": ["DIVIDE", "CALCULATE", "Upsell", "Cross-sell", "Revenue Quality"]}, {"id": 317, "cat": "sales", "sub": "Revenue Quality", "diff": "intermediate", "title": "Average Discount Rate %", "q": "What is the average discount being applied across all deals?", "dax": "Avg Discount % =\nAVERAGEX (\n    Sales,\n    F_Sales[Discount]\n)", "insight": "<strong>Margin protection metric.</strong> 5% average discount across £10M revenue = £500K of margin given away silently. Track by rep to find discount outliers.", "tags": ["AVERAGEX", "Discount", "Rate", "Margin"]}, {"id": 318, "cat": "sales", "sub": "Revenue Quality", "diff": "advanced", "title": "Revenue Concentration — Top 10 Customers %", "q": "What percentage of revenue comes from the top 10 customers?", "dax": "Top 10 Customer Revenue % =\nVAR _top10 =\n    TOPN (\n        10,\n        VALUES ( F_Sales[CustomerID] ),\n        CALCULATE ( [Total Sales] )\n    )\nRETURN\n    DIVIDE (\n        CALCULATE ( [Total Sales], KEEPFILTERS ( _top10 ) ),\n        CALCULATE ( [Total Sales], ALL ( F_Sales[CustomerID] ) )\n    )", "insight": "<strong>Concentration risk.</strong> Above 50% in top 10 = dangerous dependency. Loss of 1–2 key accounts could be existential.", "tags": ["VAR", "TOPN", "VALUES", "KEEPFILTERS", "Concentration", "Risk"]}, {"id": 319, "cat": "sales", "sub": "Revenue Quality", "diff": "advanced", "title": "Annual Sales Run Rate", "q": "At current YTD pace, what will full-year revenue be?", "dax": "[KPI] Annual Run Rate =\nVAR _elapsed =\n    DATEDIFF ( DATE ( YEAR ( TODAY () ), 1, 1 ), TODAY (), DAY )\nRETURN\n    DIVIDE ( [Revenue YTD] * 365, _elapsed )", "insight": "<strong>Forecast signal.</strong> Compare against annual target — if run rate is 15% below target in Q1, course correction is still possible.", "tags": ["VAR", "DATEDIFF", "Forecast", "Run Rate"]}, {"id": 401, "cat": "finance", "sub": "Revenue", "diff": "basic", "title": "Total Revenue (from GL)", "q": "What is the total income posted to all revenue accounts?", "dax": "Total Revenue =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Revenue\"\n    )\n)", "insight": "<strong>Foundation P&L measure.</strong> M_COA[Category] = \"Revenue\" captures all sales account lines. Add more category values with || if your COA splits Product vs Service revenue.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Revenue", "P&L"]}, {"id": 402, "cat": "finance", "sub": "Revenue", "diff": "intermediate", "title": "Product Revenue", "q": "How much revenue came from product sales only?", "dax": "Product Revenue =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Revenue\"\n            && M_COA[Subcategory] = \"Product Sales\"\n    )\n)", "insight": "<strong>Subcategory filter</strong> lets you slice revenue by type. Adjust \"Product Sales\" to match your COA subcategory labels exactly.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Subcategory", "Revenue"]}, {"id": 403, "cat": "finance", "sub": "Revenue", "diff": "intermediate", "title": "Service Revenue", "q": "How much revenue came from services?", "dax": "Service Revenue =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Revenue\"\n            && M_COA[Subcategory] = \"Service Revenue\"\n    )\n)", "insight": "<strong>Useful for mixed-model businesses.</strong> Comparing product vs service revenue trends reveals which growth engine is firing.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Service", "Revenue"]}, {"id": 404, "cat": "finance", "sub": "Revenue", "diff": "intermediate", "title": "Other Income", "q": "What income was earned outside of core trading (e.g. grants, rental income)?", "dax": "Other Income =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Other Income\"\n    )\n)", "insight": "<strong>Keep Other Income separate</strong> from trading revenue. Inflating core revenue with one-off items misleads investors and analysts.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Other Income"]}, {"id": 405, "cat": "finance", "sub": "Revenue", "diff": "intermediate", "title": "Interest Income", "q": "How much interest was earned on cash and investments?", "dax": "Interest Income =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Interest Income\"\n    )\n)", "insight": "<strong>Below-the-line item.</strong> Interest income sits below EBIT in a standard P&L and is excluded from EBITDA and Gross Profit calculations.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Interest Income"]}, {"id": 406, "cat": "finance", "sub": "COGS", "diff": "basic", "title": "Total COGS", "q": "What is the total direct cost of producing goods or services sold?", "dax": "Total COGS =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"COGS\"\n    )\n)", "insight": "<strong>COGS includes only direct costs</strong> — materials, direct labour, manufacturing overhead. Indirect costs belong in Opex. Getting this split right is critical for Gross Margin accuracy.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "COGS", "P&L"]}, {"id": 407, "cat": "finance", "sub": "COGS", "diff": "intermediate", "title": "Direct Materials Cost", "q": "How much was spent on raw materials directly used in production?", "dax": "Direct Materials =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"COGS\"\n            && M_COA[Subcategory] = \"Direct Materials\"\n    )\n)", "insight": "<strong>Track as % of revenue</strong> over time. Rising materials cost % signals commodity price pressure or production inefficiency.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Materials", "COGS"]}, {"id": 408, "cat": "finance", "sub": "COGS", "diff": "intermediate", "title": "Direct Labour Cost", "q": "How much was paid in wages directly attributable to production?", "dax": "Direct Labour =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"COGS\"\n            && M_COA[Subcategory] = \"Direct Labour\"\n    )\n)", "insight": "<strong>Separate from indirect/admin salaries</strong> in Opex. Direct Labour ÷ Units Produced = Labour cost per unit — a key production efficiency metric.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Labour", "COGS"]}, {"id": 409, "cat": "finance", "sub": "Gross Profit", "diff": "basic", "title": "Gross Profit", "q": "What profit remains after deducting all direct costs from revenue?", "dax": "Gross Profit =\n[Total Sales] - [Total COGS]", "insight": "<strong>The P&L\\'s first critical checkpoint.</strong> Negative gross profit means you lose money on every unit sold — no amount of cost-cutting below the line can fix that.", "tags": ["Gross Profit", "P&L", "Subtotal"]}, {"id": 410, "cat": "finance", "sub": "Gross Profit", "diff": "basic", "title": "Gross Margin %", "q": "What percentage of revenue remains after direct costs?", "dax": "Gross Margin % =\nDIVIDE (\n    [Gross Profit],\n    [Total Sales]\n)", "insight": "<strong>Industry benchmarks vary widely:</strong> SaaS 70–80%, Manufacturing 25–35%, Retail 20–30%, Consulting 50–70%. Track trend above all else.", "tags": ["DIVIDE", "Gross Margin", "%", "P&L"]}, {"id": 411, "cat": "finance", "sub": "Operating Expenses", "diff": "basic", "title": "Total Operating Expenses (Opex)", "q": "What is the total of all indirect/overhead operating costs?", "dax": "Total Opex =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Operating Expenses\"\n    )\n)", "insight": "<strong>Opex excludes COGS and D&A.</strong> It is the controllable overhead layer — where most management attention should focus.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Opex", "P&L"]}, {"id": 412, "cat": "finance", "sub": "Operating Expenses", "diff": "intermediate", "title": "Sales & Distribution Costs", "q": "How much was spent on selling, shipping, and distribution?", "dax": "Sales & Distribution =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Operating Expenses\"\n            && M_COA[Subcategory] = \"Sales & Distribution\"\n    )\n)", "insight": "<strong>Track as % of revenue.</strong> If Sales & Distribution cost grows faster than revenue, your go-to-market model may be losing efficiency.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Selling Costs", "Opex"]}, {"id": 413, "cat": "finance", "sub": "Operating Expenses", "diff": "intermediate", "title": "Marketing & Advertising", "q": "What was the total spend on marketing and advertising?", "dax": "Marketing & Advertising =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Operating Expenses\"\n            && M_COA[Subcategory] = \"Marketing & Advertising\"\n    )\n)", "insight": "<strong>Marketing Efficiency:</strong> DIVIDE([Total Sales],[Marketing & Advertising]) gives revenue per £ of marketing spend — a proxy for ROI.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Marketing", "Opex"]}, {"id": 414, "cat": "finance", "sub": "Operating Expenses", "diff": "intermediate", "title": "Admin & General Expenses", "q": "What are the total general and administrative overhead costs?", "dax": "Admin & General =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Operating Expenses\"\n            && M_COA[Subcategory] = \"Admin & General\"\n    )\n)", "insight": "<strong>G&A should shrink as a % of revenue</strong> as a company scales. Flat or rising G&A % signals lack of operational leverage.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Admin", "G&A", "Opex"]}, {"id": 415, "cat": "finance", "sub": "Operating Expenses", "diff": "intermediate", "title": "Staff Costs (Indirect)", "q": "How much was spent on salaries and wages in support functions?", "dax": "Staff Costs Indirect =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Operating Expenses\"\n            && M_COA[Subcategory] = \"Staff Costs\"\n    )\n)", "insight": "<strong>Largest Opex line for most businesses.</strong> Split by department using GL[CostCentre] for headcount cost attribution.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Staff", "Salaries", "Opex"]}, {"id": 416, "cat": "finance", "sub": "Operating Expenses", "diff": "intermediate", "title": "Opex as % of Revenue", "q": "What share of revenue is consumed by operating overhead?", "dax": "Opex % of Revenue =\nDIVIDE (\n    [Total Opex],\n    [Total Sales]\n)", "insight": "<strong>Operating leverage indicator.</strong> If Opex % is falling as revenue grows, the business is scaling efficiently. Rising Opex % is a red flag in mature businesses.", "tags": ["DIVIDE", "Opex", "% of Revenue", "Efficiency"]}, {"id": 417, "cat": "finance", "sub": "EBITDA", "diff": "intermediate", "title": "EBITDA", "q": "What is Earnings Before Interest, Tax, Depreciation and Amortisation?", "dax": "EBITDA =\n[Gross Profit] - [Total Opex]", "insight": "<strong>EBITDA = operating cash generation proxy.</strong> It excludes non-cash (D&A) and financing (interest/tax) items, making it useful for comparing companies regardless of capital structure.", "tags": ["EBITDA", "P&L", "Subtotal", "Profitability"]}, {"id": 418, "cat": "finance", "sub": "EBITDA", "diff": "intermediate", "title": "EBITDA Margin %", "q": "What percentage of revenue converts to EBITDA?", "dax": "EBITDA Margin % =\nDIVIDE (\n    [EBITDA],\n    [Total Sales]\n)", "insight": "<strong>Valuation anchor metric.</strong> Most business valuations are expressed as a multiple of EBITDA (e.g. 8× EBITDA). A rising margin signals operating leverage.", "tags": ["DIVIDE", "EBITDA", "Margin", "%"]}, {"id": 419, "cat": "finance", "sub": "D&A", "diff": "intermediate", "title": "Depreciation & Amortisation", "q": "What is the total non-cash D&A charge in the period?", "dax": "Depreciation & Amortisation =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Depreciation & Amortisation\"\n    )\n)", "insight": "<strong>Non-cash charge.</strong> D&A reduces profit but not cash flow — which is why EBITDA (before D&A) is the go-to operating cash proxy. Separate Depreciation and Amortisation using M_COA[Subcategory] if needed.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "D&A", "Depreciation"]}, {"id": 420, "cat": "finance", "sub": "EBIT", "diff": "intermediate", "title": "EBIT (Operating Profit)", "q": "What is the operating profit after D&A but before interest and tax?", "dax": "EBIT =\n[EBITDA] - [Depreciation & Amortisation]", "insight": "<strong>EBIT = true operating profitability.</strong> Unlike EBITDA, it reflects the real cost of using long-term assets. EBIT ÷ Revenue = EBIT Margin, the cleanest cross-company profitability comparator.", "tags": ["EBIT", "Operating Profit", "P&L", "Subtotal"]}, {"id": 421, "cat": "finance", "sub": "EBIT", "diff": "intermediate", "title": "EBIT Margin %", "q": "What percentage of revenue is operating profit?", "dax": "EBIT Margin % =\nDIVIDE (\n    [EBIT],\n    [Total Sales]\n)", "insight": "<strong>Cross-industry benchmark.</strong> Retail: 3–8%. SaaS: 15–25%. Professional services: 10–20%. A falling EBIT margin alongside rising revenue signals cost problems.", "tags": ["DIVIDE", "EBIT", "Margin", "%", "Operating Profit"]}, {"id": 422, "cat": "finance", "sub": "EBT & Finance Costs", "diff": "intermediate", "title": "Interest Expense", "q": "What is the total interest cost on debt in the period?", "dax": "Interest Expense =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Interest Expense\"\n    )\n)", "insight": "<strong>Finance cost, not operating cost.</strong> Sits below EBIT in the P&L. Rising interest expense relative to EBIT signals increasing financial risk.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Interest", "Finance Costs"]}, {"id": 423, "cat": "finance", "sub": "EBT & Finance Costs", "diff": "intermediate", "title": "EBT (Profit Before Tax)", "q": "What is the profit after all costs except tax?", "dax": "EBT =\n[EBIT]\n    + [Interest Income]\n    - [Interest Expense]", "insight": "<strong>EBT is the taxable profit base.</strong> The difference between EBIT and EBT is entirely driven by the net financing position — a highly leverage company will show a large gap here.", "tags": ["EBT", "Profit Before Tax", "P&L", "Subtotal"]}, {"id": 424, "cat": "finance", "sub": "Net Profit", "diff": "intermediate", "title": "Tax Charge", "q": "What is the income tax expense recognised in the period?", "dax": "Tax Charge =\nCALCULATE (\n    SUM ( F_GL[Amount] ),\n    FILTER (\n        M_COA,\n        M_COA[Category] = \"Tax\"\n    )\n)", "insight": "<strong>Effective tax rate = Tax Charge ÷ EBT.</strong> Useful for spotting deferred tax movements or jurisdictional tax changes in multi-entity GL data.", "tags": ["CALCULATE", "SUM", "FILTER", "M_COA", "Tax"]}, {"id": 425, "cat": "finance", "sub": "Net Profit", "diff": "basic", "title": "Net Profit", "q": "What is the bottom-line profit after all costs including tax?", "dax": "Net Profit =\n[EBT] - [Tax Charge]", "insight": "<strong>The final P&L line.</strong> Net Profit flows into Retained Earnings on the Balance Sheet. A company can be EBITDA-positive and Net Profit negative — high D&A, interest or tax can erase operating gains.", "tags": ["Net Profit", "P&L", "Subtotal", "Bottom Line"]}, {"id": 426, "cat": "finance", "sub": "Net Profit", "diff": "basic", "title": "Net Profit Margin %", "q": "What percentage of every £1 of revenue becomes net profit?", "dax": "Net Profit Margin % =\nDIVIDE (\n    [Net Profit],\n    [Total Sales]\n)", "insight": "<strong>The headline profitability number.</strong> Sustained improvement in Net Profit Margin % is the clearest sign a business is scaling profitably.", "tags": ["DIVIDE", "Net Profit", "Margin", "%", "P&L"]}, {"id": 427, "cat": "finance", "sub": "Contribution Margin", "diff": "intermediate", "title": "Contribution Margin", "q": "What remains after deducting all variable costs from revenue?", "dax": "Contribution Margin =\nVAR _revenue  = [Total Sales]\nVAR _varCosts =\n    CALCULATE (\n        SUM ( F_GL[Amount] ),\n        FILTER (\n            M_COA,\n            M_COA[CostBehaviour] = \"Variable\"\n        )\n    )\nRETURN\n    _revenue - _varCosts", "insight": "<strong>Requires M_COA[CostBehaviour] column</strong> tagged \"Variable\" or \"Fixed\". Contribution Margin drives break-even analysis and pricing decisions.", "tags": ["VAR", "CALCULATE", "FILTER", "M_COA", "Contribution", "Variable Cost"]}, {"id": 428, "cat": "finance", "sub": "Contribution Margin", "diff": "intermediate", "title": "Contribution Margin %", "q": "What percentage of revenue covers fixed costs and profit?", "dax": "Contribution Margin % =\nDIVIDE (\n    [Contribution Margin],\n    [Total Sales]\n)", "insight": "<strong>Higher CM% = more pricing power.</strong> A CM% below your fixed cost ratio means you are loss-making regardless of volume. This is the break-even signal.", "tags": ["DIVIDE", "Contribution", "%", "Margin"]}, {"id": 429, "cat": "finance", "sub": "Financial Ratios", "diff": "intermediate", "title": "Interest Cover Ratio", "q": "How many times can operating profit cover the interest bill?", "dax": "Interest Cover Ratio =\nDIVIDE (\n    [EBIT],\n    [Interest Expense]\n)", "insight": "<strong>Solvency signal.</strong> Below 2× is concerning — lenders often covenant at 3×. Below 1× means operating profit cannot even cover interest, let alone repay principal.", "tags": ["DIVIDE", "EBIT", "Interest", "Ratio", "Solvency"]}, {"id": 430, "cat": "finance", "sub": "Financial Ratios", "diff": "intermediate", "title": "Break-Even Revenue", "q": "How much revenue is needed to cover all fixed costs?", "dax": "Break-Even Revenue =\nVAR _fixedCosts =\n    CALCULATE (\n        SUM ( F_GL[Amount] ),\n        FILTER (\n            M_COA,\n            M_COA[CostBehaviour] = \"Fixed\"\n        )\n    )\nRETURN\n    DIVIDE (\n        _fixedCosts,\n        [Contribution Margin %]\n    )", "insight": "<strong>Pricing and volume planning tool.</strong> If actual revenue is below break-even, every unit sold loses money. Compare against current revenue to see safety margin.", "tags": ["VAR", "DIVIDE", "Break-Even", "Fixed Costs", "Contribution"]}, {"id": 431, "cat": "finance", "sub": "Financial Ratios", "diff": "intermediate", "title": "Operating Leverage", "q": "How sensitive is operating profit to a change in revenue?", "dax": "Operating Leverage =\nDIVIDE (\n    [Contribution Margin],\n    [EBIT]\n)", "insight": "<strong>High leverage (>5×) = high risk and high reward.</strong> A 10% revenue increase with 6× leverage means ~60% EBIT increase. But the same works in reverse on the downside.", "tags": ["DIVIDE", "Operating Leverage", "EBIT", "Contribution"]}, {"id": 432, "cat": "finance", "sub": "Financial Ratios", "diff": "intermediate", "title": "COGS as % of Revenue", "q": "What share of revenue is consumed by direct production costs?", "dax": "COGS % of Revenue =\nDIVIDE (\n    [Total COGS],\n    [Total Sales]\n)", "insight": "<strong>Rising COGS%</strong> signals raw material inflation, supply chain issues, or production inefficiency. Falling COGS% = margin expansion — the best kind.", "tags": ["DIVIDE", "COGS", "%", "Revenue", "Ratio"]}, {"id": 433, "cat": "finance", "sub": "Financial Ratios", "diff": "intermediate", "title": "YoY Revenue Growth %", "q": "How much has revenue grown versus the same period last year?", "dax": "Revenue [KPI] YoY Growth % =\nVAR _curr = [Total Sales]\nVAR _ly =\n    CALCULATE (\n        [Total Sales],\n        SAMEPERIODLASTYEAR ( M_Date[Date] )\n    )\nRETURN\n    DIVIDE ( _curr - _ly, _ly )", "insight": "<strong>The headline growth number</strong> for any investor or board presentation. Combine with Net Profit Margin % to show whether growth is profitable or just volume.", "tags": ["VAR", "CALCULATE", "SAMEPERIODLASTYEAR", "YoY", "Revenue", "Growth"]}, {"id": 434, "cat": "finance", "sub": "Financial Ratios", "diff": "advanced", "title": "YoY Net Profit Growth %", "q": "Is bottom-line profit growing faster or slower than revenue?", "dax": "Net Profit [KPI] YoY Growth % =\nVAR _curr = [Net Profit]\nVAR _ly =\n    CALCULATE (\n        [Net Profit],\n        SAMEPERIODLASTYEAR ( M_Date[Date] )\n    )\nRETURN\n    DIVIDE ( _curr - _ly, _ly )", "insight": "<strong>Profit quality signal.</strong> Net Profit growing faster than revenue = margin expansion = quality growth. Net Profit growing slower = cost creep eroding profitability.", "tags": ["VAR", "CALCULATE", "SAMEPERIODLASTYEAR", "YoY", "Net Profit", "Growth"]}, {"id": 435, "cat": "finance", "sub": "Financial Ratios", "diff": "advanced", "title": "Revenue per Employee", "q": "How much revenue is each employee generating on average?", "dax": "Revenue per Employee =\nDIVIDE (\n    [Total Sales],\n    DISTINCTCOUNT ( M_Employees[EmployeeID] )\n)", "insight": "<strong>Productivity benchmark.</strong> SaaS companies target $200K–500K+ per employee. Services firms: $100K–200K. Rising metric signals efficiency; falling metric signals headcount outpacing growth.", "tags": ["DIVIDE", "DISTINCTCOUNT", "Revenue per Employee", "Productivity"]}, {"id": 436, "cat": "finance", "sub": "Financial Ratios", "diff": "advanced", "title": "Budget Variance %", "q": "How far is actual revenue above or below budget?", "dax": "Budget Variance % =\nVAR _actual = [Total Sales]\nVAR _budget =\n    CALCULATE (\n        SUM ( F_GL[Amount] ),\n        FILTER (\n            M_COA,\n            M_COA[Category] = \"Revenue\"\n                && M_COA[DataType] = \"Budget\"\n        )\n    )\nRETURN\n    DIVIDE ( _actual - _budget, _budget )", "insight": "<strong>Positive = over budget, Negative = under.</strong> For a GL-based budget model, store budget entries in GL with a separate DataType or Entity flag to separate actuals from budgets.", "tags": ["VAR", "DIVIDE", "Budget", "Variance", "FILTER", "M_COA"]}, {"id": 451, "cat": "finance", "sub": "Accounts Receivable", "diff": "basic", "title": "Total AR Outstanding", "q": "What is the total value of all unpaid customer invoices?", "dax": "Total AR Outstanding =\nCALCULATE (\n    SUM ( F_AR[InvoiceAmount] )\n        - SUM ( F_AR[PaidAmount] ),\n    F_AR[Status] = \"Open\"\n        || F_AR[Status] = \"Overdue\"\n)", "insight": "<strong>Working capital core metric.</strong> Outstanding AR is money already earned but not yet collected. Reducing AR days directly improves cash flow without changing a single sale.", "tags": ["CALCULATE", "SUM", "AR", "Outstanding", "Receivables"]}, {"id": 452, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "Current AR (Not Yet Due)", "q": "How much AR is outstanding but still within payment terms?", "dax": "Current AR =\nCALCULATE (\n    SUM ( F_AR[InvoiceAmount] )\n        - SUM ( F_AR[PaidAmount] ),\n    F_AR[Status] = \"Open\",\n    F_AR[DueDate] >= TODAY ()\n)", "insight": "<strong>Healthy AR.</strong> Current AR is normal business — within terms. Monitor that it does not age into overdue buckets. Rising current AR alongside rising revenue is fine.", "tags": ["CALCULATE", "SUM", "TODAY", "AR", "Current"]}, {"id": 453, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "Overdue AR", "q": "How much AR has passed its payment due date?", "dax": "Overdue AR =\nCALCULATE (\n    SUM ( F_AR[InvoiceAmount] )\n        - SUM ( F_AR[PaidAmount] ),\n    F_AR[Status] = \"Overdue\"\n        || (\n            F_AR[Status] = \"Open\"\n                && F_AR[DueDate] < TODAY ()\n        )\n)", "insight": "<strong>Collections priority metric.</strong> Overdue AR means cash already earned is not in your bank. Age analysis (0–30, 31–60, 61–90, 90+ days) shows urgency and write-off risk.", "tags": ["CALCULATE", "SUM", "TODAY", "AR", "Overdue", "Collections"]}, {"id": 454, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "AR — 0 to 30 Days Overdue", "q": "How much AR is 1–30 days past its due date?", "dax": "AR 0-30 Days =\nCALCULATE (\n    SUM ( F_AR[InvoiceAmount] )\n        - SUM ( F_AR[PaidAmount] ),\n    F_AR[AgeBucket] = \"0-30\",\n    F_AR[Status] <> \"Paid\"\n)", "insight": "<strong>Early-stage overdue.</strong> 0–30 days is typically recoverable with a polite reminder. Escalation is not yet needed — automated reminders should handle this bucket.", "tags": ["CALCULATE", "SUM", "AR", "Ageing", "0-30"]}, {"id": 455, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "AR — 31 to 60 Days Overdue", "q": "How much AR is 31–60 days past its due date?", "dax": "AR 31-60 Days =\nCALCULATE (\n    SUM ( F_AR[InvoiceAmount] )\n        - SUM ( F_AR[PaidAmount] ),\n    F_AR[AgeBucket] = \"31-60\",\n    F_AR[Status] <> \"Paid\"\n)", "insight": "<strong>Active chase required.</strong> 31–60 days needs direct contact from the AR team. Check for invoice disputes, PO mismatches, or customer cash flow problems.", "tags": ["CALCULATE", "SUM", "AR", "Ageing", "31-60"]}, {"id": 456, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "AR — 90+ Days Overdue", "q": "How much AR is more than 90 days past due — the highest risk bucket?", "dax": "AR 90+ Days =\nCALCULATE (\n    SUM ( F_AR[InvoiceAmount] )\n        - SUM ( F_AR[PaidAmount] ),\n    F_AR[AgeBucket] = \"90+\",\n    F_AR[Status] <> \"Paid\"\n)", "insight": "<strong>Write-off risk bucket.</strong> 90+ days is the point where bad debt provisions are typically required under accounting standards. Escalate to legal or debt collection agency.", "tags": ["CALCULATE", "SUM", "AR", "Ageing", "90+", "Bad Debt"]}, {"id": 457, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "% AR Overdue", "q": "What percentage of total outstanding AR is past its due date?", "dax": "% AR Overdue =\nDIVIDE (\n    [Overdue AR],\n    [Total AR Outstanding]\n)", "insight": "<strong>Collections health indicator.</strong> Above 20% overdue signals a systemic collections problem — could be invoicing errors, customer disputes, or credit extended to poor-risk customers.", "tags": ["DIVIDE", "AR", "Overdue", "%", "Collections"]}, {"id": 458, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "Days Sales Outstanding (DSO)", "q": "On average, how many days does it take to collect payment after invoicing?", "dax": "DSO =\nDIVIDE (\n    [Total AR Outstanding],\n    DIVIDE (\n        CALCULATE (\n            SUM ( F_AR[InvoiceAmount] ),\n            DATESINPERIOD (\n                M_Date[Date],\n                LASTDATE ( M_Date[Date] ),\n                -90, DAY\n            )\n        ),\n        90\n    )\n)", "insight": "<strong>The single most important AR metric.</strong> DSO = how many days revenue is sitting in AR instead of your bank. Reducing DSO by 5 days on £10M revenue unlocks ~£137K in cash.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "DSO", "Days", "Collections"]}, {"id": 459, "cat": "finance", "sub": "Accounts Receivable", "diff": "advanced", "title": "DSO Rolling 12-Month", "q": "What is the average DSO trend over the last 12 months?", "dax": "DSO Rolling 12M =\nDIVIDE (\n    [Total AR Outstanding],\n    DIVIDE (\n        CALCULATE (\n            SUM ( F_AR[InvoiceAmount] ),\n            DATESINPERIOD (\n                M_Date[Date],\n                LASTDATE ( M_Date[Date] ),\n                -12, MONTH\n            )\n        ),\n        365\n    )\n)", "insight": "<strong>Smoothed DSO removes month-end billing spikes.</strong> Rising 12M DSO trend is an early warning of deteriorating collections — act before it becomes a cash flow crisis.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "DSO", "Rolling", "12M"]}, {"id": 460, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "Collection Rate %", "q": "What percentage of invoiced revenue has been collected as cash in the period?", "dax": "Collection Rate % =\nDIVIDE (\n    SUM ( F_AR[PaidAmount] ),\n    SUM ( F_AR[InvoiceAmount] )\n)", "insight": "<strong>Cash efficiency metric.</strong> Target 95%+ within the period. Below 85% means your invoicing-to-cash process has significant friction — disputes, payment term mismatches, or customer payment delays.", "tags": ["DIVIDE", "SUM", "Collection Rate", "Cash", "AR"]}, {"id": 461, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "Bad Debt Write-Off Amount", "q": "How much AR has been written off as uncollectable in the period?", "dax": "Bad Debt Write-Off =\nCALCULATE (\n    SUM ( F_AR[InvoiceAmount] ),\n    F_AR[Status] = \"Written Off\",\n    F_AR[PaidDate] >= MIN ( M_Date[Date] ),\n    F_AR[PaidDate] <= MAX ( M_Date[Date] )\n)", "insight": "<strong>Credit risk realised.</strong> Write-offs hit the P&L as bad debt expense. Track by customer segment — if write-offs cluster in one sector or region, tighten credit terms for that cohort.", "tags": ["CALCULATE", "SUM", "Bad Debt", "Write-Off", "Credit Risk"]}, {"id": 462, "cat": "finance", "sub": "Accounts Receivable", "diff": "intermediate", "title": "Bad Debt % of Revenue", "q": "What percentage of revenue is being lost to bad debt write-offs?", "dax": "Bad Debt % =\nDIVIDE (\n    [Bad Debt Write-Off],\n    [Total Sales]\n)", "insight": "<strong>Acceptable range: below 0.5% of revenue.</strong> Above 1% signals poor credit vetting, aggressive growth into high-risk customers, or deteriorating economic conditions in your market.", "tags": ["DIVIDE", "Bad Debt", "%", "Revenue", "Credit"]}, {"id": 463, "cat": "finance", "sub": "Accounts Payable", "diff": "basic", "title": "Total AP Outstanding", "q": "What is the total value of all unpaid supplier invoices?", "dax": "Total AP Outstanding =\nCALCULATE (\n    SUM ( F_AP[InvoiceAmount] )\n        - SUM ( F_AP[PaidAmount] ),\n    F_AP[Status] = \"Open\"\n        || F_AP[Status] = \"Overdue\"\n)", "insight": "<strong>Working capital liability.</strong> AP is money owed to suppliers. Optimising payment timing (not too early, not too late) is a free source of working capital management.", "tags": ["CALCULATE", "SUM", "AP", "Outstanding", "Payables"]}, {"id": 464, "cat": "finance", "sub": "Accounts Payable", "diff": "intermediate", "title": "AP Overdue", "q": "How much AP has already passed its payment due date?", "dax": "AP Overdue =\nCALCULATE (\n    SUM ( F_AP[InvoiceAmount] )\n        - SUM ( F_AP[PaidAmount] ),\n    F_AP[Status] = \"Open\",\n    F_AP[DueDate] < TODAY ()\n)", "insight": "<strong>Supplier relationship risk.</strong> Overdue AP damages supplier trust, can trigger supply suspension, and attracts late payment charges. In the UK, the Prompt Payment Code requires payment within 30 days.", "tags": ["CALCULATE", "SUM", "TODAY", "AP", "Overdue", "Supplier"]}, {"id": 465, "cat": "finance", "sub": "Accounts Payable", "diff": "intermediate", "title": "Days Payable Outstanding (DPO)", "q": "On average, how many days does it take to pay suppliers?", "dax": "DPO =\nDIVIDE (\n    [Total AP Outstanding],\n    DIVIDE (\n        CALCULATE (\n            SUM ( F_AP[InvoiceAmount] ),\n            DATESINPERIOD (\n                M_Date[Date],\n                LASTDATE ( M_Date[Date] ),\n                -90, DAY\n            )\n        ),\n        90\n    )\n)", "insight": "<strong>Higher DPO = more working capital retained.</strong> But too high (>90 days) damages supplier relationships. Target 30–60 days — match your payment terms. Balance with [DSO]: DPO > DSO = positive cash cycle.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "DPO", "Days", "Payables"]}, {"id": 466, "cat": "finance", "sub": "Accounts Payable", "diff": "intermediate", "title": "On-Time Payment Rate %", "q": "What percentage of supplier invoices are paid on or before the due date?", "dax": "On-Time Payment % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( F_AP ),\n        F_AP[Status] = \"Paid\",\n        F_AP[PaidDate] <= F_AP[DueDate]\n    ),\n    CALCULATE (\n        COUNTROWS ( F_AP ),\n        F_AP[Status] = \"Paid\"\n    )\n)", "insight": "<strong>Supplier trust metric.</strong> Prompt Payment Code signatories target 95%+. Large retailers often face mandatory reporting on payment practices — this is the core KPI.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "On-Time", "Payment", "Supplier"]}, {"id": 467, "cat": "finance", "sub": "Accounts Payable", "diff": "intermediate", "title": "Early Payment Discount Captured %", "q": "What percentage of available early-payment discounts were taken?", "dax": "Early Payment Discount % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( F_AP ),\n        F_AP[DiscountCaptured] = TRUE ()\n    ),\n    CALCULATE (\n        COUNTROWS ( F_AP ),\n        F_AP[EarlyPaymentDiscount] > 0\n    )\n)", "insight": "<strong>Free money on the table.</strong> A 2% early payment discount on 30 days = 24% annualised return — better than most investments. Capturing 80%+ of available discounts should be a finance KPI.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Early Payment", "Discount", "AP"]}, {"id": 468, "cat": "finance", "sub": "Accounts Payable", "diff": "intermediate", "title": "AP Turnover Ratio", "q": "How many times per year is the AP balance fully paid and refreshed?", "dax": "AP Turnover =\nDIVIDE (\n    CALCULATE (\n        SUM ( F_AP[InvoiceAmount] ),\n        DATESINPERIOD (\n            M_Date[Date],\n            LASTDATE ( M_Date[Date] ),\n            -12, MONTH\n        )\n    ),\n    [Total AP Outstanding]\n)", "insight": "<strong>Payment velocity metric.</strong> Higher turnover = faster payment cycle. Lower turnover = slower payment. Compare against [Inventory Turnover] and [DSO] for cash conversion cycle analysis.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "AP Turnover", "Ratio"]}, {"id": 469, "cat": "finance", "sub": "Working Capital", "diff": "advanced", "title": "Cash Conversion Cycle (CCC)", "q": "How many days does it take to convert inventory investment into cash receipts?", "dax": "Cash Conversion Cycle =\n[DIO] + [DSO] - [DPO]", "insight": "<strong>The master working capital metric.</strong> CCC = how long your cash is tied up in operations. Negative CCC (like Amazon or Zara) means you collect cash before paying suppliers — a massive competitive advantage.", "tags": ["DIO", "DSO", "DPO", "CCC", "Working Capital", "Cash"]}, {"id": 470, "cat": "finance", "sub": "Working Capital", "diff": "intermediate", "title": "Net Working Capital", "q": "What is the net of current assets (AR + Inventory) minus current liabilities (AP)?", "dax": "Net Working Capital =\n[Total AR Outstanding]\n    + [Stock Value]\n    - [Total AP Outstanding]", "insight": "<strong>Liquidity health check.</strong> Positive NWC = more assets than short-term obligations. Rapidly rising NWC without rising revenue signals inefficiency — cash is being trapped in the business cycle.", "tags": ["AR", "AP", "Inventory", "Working Capital", "Liquidity"]}, {"id": 471, "cat": "finance", "sub": "Working Capital", "diff": "intermediate", "title": "AR to Revenue Ratio", "q": "How many months of revenue is sitting in AR at any given time?", "dax": "AR to Revenue Ratio =\nDIVIDE (\n    [Total AR Outstanding],\n    DIVIDE (\n        CALCULATE (\n            [Total Sales],\n            DATESINPERIOD (\n                M_Date[Date],\n                LASTDATE ( M_Date[Date] ),\n                -12, MONTH\n            )\n        ),\n        12\n    )\n)", "insight": "<strong>Months of revenue in AR.</strong> A ratio of 1.5 means 1.5 months of revenue is outstanding. For net-30 terms this should be ~1.0. Above 2.0 signals a collections problem.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "AR", "Revenue", "Ratio"]}, {"id": 501, "cat": "hr", "sub": "Headcount", "diff": "basic", "title": "Active Headcount", "q": "How many employees are currently in active employment?", "dax": "Active Headcount =\nCOUNTROWS (\n    FILTER (\n        M_Employees,\n        M_Employees[Status] = \"Active\"\n    )\n)", "insight": "<strong>Your single most important HR KPI.</strong> Always filter by Status = \"Active\" — terminated records must stay in the table for attrition analysis but must never count in live headcount.", "tags": ["COUNTROWS", "FILTER", "M_Employees", "Headcount", "Active"]}, {"id": 502, "cat": "hr", "sub": "Headcount", "diff": "basic", "title": "Inactive Headcount", "q": "How many employees are recorded as inactive (e.g. on long-term leave or suspended)?", "dax": "Inactive Headcount =\nCOUNTROWS (\n    FILTER (\n        M_Employees,\n        M_Employees[Status] = \"Inactive\"\n    )\n)", "insight": "<strong>Inactive ≠ Left.</strong> Inactive covers long-term sick, unpaid leave, garden leave, maternity/paternity. Track separately so Active HC is not overstated.", "tags": ["COUNTROWS", "FILTER", "M_Employees", "Inactive", "Headcount"]}, {"id": 503, "cat": "hr", "sub": "Headcount", "diff": "basic", "title": "Total Leavers (People Who Left)", "q": "How many employees have left the organisation in the selected period?", "dax": "Total Leavers =\nCALCULATE (\n    COUNTROWS ( M_Employees ),\n    FILTER (\n        M_Employees,\n        M_Employees[Status] = \"Left\"\n            && M_Employees[LeaveDate] >= MIN ( M_Date[Date] )\n            && M_Employees[LeaveDate] <= MAX ( M_Date[Date] )\n    )\n)", "insight": "<strong>Period-sensitive leavers.</strong> The date filter ensures the count responds to your date slicer — showing leavers in the selected month, quarter or year.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "M_Employees", "Leavers"]}, {"id": 504, "cat": "hr", "sub": "Headcount", "diff": "intermediate", "title": "Headcount — End of Last Month", "q": "What was the active headcount on the last day of the previous month?", "dax": "HC End of Last Month =\nCALCULATE (\n    COUNTROWS (\n        FILTER (\n            M_Employees,\n            M_Employees[JoinDate]\n                <= EOMONTH ( TODAY (), -1 )\n                && (\n                    ISBLANK ( M_Employees[LeaveDate] )\n                        || M_Employees[LeaveDate]\n                            > EOMONTH ( TODAY (), -1 )\n                )\n        )\n    )\n)", "insight": "<strong>Point-in-time HC snapshot.</strong> Checks that JoinDate ≤ last month-end AND (no leave date OR leave date after last month-end). This is the gold-standard headcount method.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "EOMONTH", "TODAY", "Point-in-Time"]}, {"id": 505, "cat": "hr", "sub": "Headcount", "diff": "intermediate", "title": "Headcount — End of Last Quarter", "q": "What was the headcount at the close of the previous quarter?", "dax": "HC End of Last Quarter =\nVAR _qEnd =\n    EOMONTH (\n        DATEADD ( STARTOFQUARTER ( TODAY () ), -1, DAY ),\n        0\n    )\nRETURN\nCALCULATE (\n    COUNTROWS (\n        FILTER (\n            M_Employees,\n            M_Employees[JoinDate] <= _qEnd\n                && (\n                    ISBLANK ( M_Employees[LeaveDate] )\n                        || M_Employees[LeaveDate] > _qEnd\n                )\n        )\n    )\n)", "insight": "<strong>Quarterly snapshot for board reporting.</strong> Pairs with [HC End of Last Month] and [HC End of Last Year] to show a headcount movement waterfall.", "tags": ["VAR", "EOMONTH", "DATEADD", "STARTOFQUARTER", "Point-in-Time", "Headcount"]}, {"id": 506, "cat": "hr", "sub": "Headcount", "diff": "intermediate", "title": "Headcount — End of Last Year", "q": "What was the headcount on 31 December of the previous year?", "dax": "HC End of Last Year =\nVAR _yearEnd = DATE ( YEAR ( TODAY () ) - 1, 12, 31 )\nRETURN\nCALCULATE (\n    COUNTROWS (\n        FILTER (\n            M_Employees,\n            M_Employees[JoinDate] <= _yearEnd\n                && (\n                    ISBLANK ( M_Employees[LeaveDate] )\n                        || M_Employees[LeaveDate] > _yearEnd\n                )\n        )\n    )\n)", "insight": "<strong>Annual opening position.</strong> Use as the denominator in full-year attrition rate and as the baseline for year-on-year headcount growth %.", "tags": ["VAR", "DATE", "YEAR", "TODAY", "FILTER", "Point-in-Time", "Headcount"]}, {"id": 507, "cat": "hr", "sub": "Headcount", "diff": "intermediate", "title": "Net Headcount Change", "q": "What is the net change in headcount — new joiners minus leavers?", "dax": "Net HC Change =\nVAR _joiners =\n    CALCULATE (\n        COUNTROWS ( M_Employees ),\n        FILTER (\n            M_Employees,\n            M_Employees[JoinDate] >= MIN ( M_Date[Date] )\n                && M_Employees[JoinDate] <= MAX ( M_Date[Date] )\n        )\n    )\nVAR _leavers = [Total Leavers]\nRETURN\n    _joiners - _leavers", "insight": "<strong>Workforce flow measure.</strong> Positive = net growth, negative = net shrinkage. A flat total HC can mask high churn — this reveals the movement underneath.", "tags": ["VAR", "CALCULATE", "COUNTROWS", "FILTER", "Net Change", "Headcount"]}, {"id": 508, "cat": "hr", "sub": "Headcount", "diff": "intermediate", "title": "Full-Time vs Part-Time Headcount", "q": "How many employees are full-time and how many are part-time?", "dax": "Full-Time HC =\nCALCULATE (\n    [Active Headcount],\n    M_Employees[EmploymentType] = \"Full-Time\"\n)\n\n-- Part-Time companion:\nPart-Time HC =\nCALCULATE (\n    [Active Headcount],\n    M_Employees[EmploymentType] = \"Part-Time\"\n)", "insight": "<strong>Workforce composition metric.</strong> Use both measures in a clustered bar by department to spot teams over-reliant on part-time staff or vice versa.", "tags": ["CALCULATE", "EmploymentType", "Full-Time", "Part-Time", "Headcount"]}, {"id": 509, "cat": "hr", "sub": "Headcount", "diff": "basic", "title": "Headcount by Gender Split %", "q": "What percentage of the workforce is each gender?", "dax": "Female HC % =\nDIVIDE (\n    CALCULATE (\n        [Active Headcount],\n        M_Employees[Gender] = \"Female\"\n    ),\n    [Active Headcount]\n)", "insight": "<strong>DEI baseline metric.</strong> Track at department and grade level — overall balance can look fine while senior leadership remains heavily skewed.", "tags": ["DIVIDE", "CALCULATE", "Gender", "DEI", "Headcount"]}, {"id": 510, "cat": "hr", "sub": "Headcount", "diff": "intermediate", "title": "Average Tenure (Years of Service)", "q": "How long have active employees been with the organisation on average?", "dax": "Avg Tenure Years =\nAVERAGEX (\n    FILTER (\n        M_Employees,\n        M_Employees[Status] = \"Active\"\n    ),\n    DIVIDE (\n        DATEDIFF (\n            M_Employees[JoinDate],\n            TODAY (),\n            DAY\n        ),\n        365.25\n    )\n)", "insight": "<strong>Stability and culture indicator.</strong> Very low avg tenure (<1.5 yrs) signals a revolving door. Very high (>15 yrs) may signal talent stagnation. 3–7 years is typically healthy.", "tags": ["AVERAGEX", "FILTER", "DATEDIFF", "TODAY", "Tenure", "Headcount"]}, {"id": 511, "cat": "hr", "sub": "Headcount", "diff": "intermediate", "title": "New Joiners in Period", "q": "How many employees joined the organisation in the selected period?", "dax": "New Joiners =\nCALCULATE (\n    COUNTROWS ( M_Employees ),\n    FILTER (\n        M_Employees,\n        M_Employees[JoinDate] >= MIN ( M_Date[Date] )\n            && M_Employees[JoinDate] <= MAX ( M_Date[Date] )\n    )\n)", "insight": "<strong>Recruitment output metric.</strong> Compare against [Open Vacancies] — if joiners consistently lag open vacancies, your pipeline or time-to-fill is the bottleneck.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "JoinDate", "New Joiners"]}, {"id": 512, "cat": "hr", "sub": "Headcount", "diff": "intermediate", "title": "Headcount YoY Growth %", "q": "Is the organisation growing or shrinking its workforce year over year?", "dax": "HC [KPI] YoY Growth % =\nVAR _curr = [Active Headcount]\nVAR _ly =\n    CALCULATE (\n        [Active Headcount],\n        SAMEPERIODLASTYEAR ( M_Date[Date] )\n    )\nRETURN\n    DIVIDE ( _curr - _ly, _ly )", "insight": "<strong>Workforce growth signal.</strong> Compare against revenue growth — if HC grows faster than revenue, productivity per head is declining.", "tags": ["VAR", "CALCULATE", "SAMEPERIODLASTYEAR", "YoY", "Headcount", "Growth"]}, {"id": 513, "cat": "hr", "sub": "Attrition & Retention", "diff": "intermediate", "title": "Average Headcount for Period", "q": "What is the average of opening and closing headcount for the period?", "dax": "Avg HC for Period =\nVAR _opening =\n    CALCULATE (\n        COUNTROWS (\n            FILTER (\n                M_Employees,\n                M_Employees[JoinDate] < MIN ( M_Date[Date] )\n                    && (\n                        ISBLANK ( M_Employees[LeaveDate] )\n                            || M_Employees[LeaveDate]\n                                >= MIN ( M_Date[Date] )\n                    )\n            )\n        )\n    )\nVAR _closing = [Active Headcount]\nRETURN\n    DIVIDE ( _opening + _closing, 2 )", "insight": "<strong>The correct attrition denominator.</strong> Using average headcount (not closing) removes distortion from rapid growth or contraction mid-period.", "tags": ["VAR", "CALCULATE", "FILTER", "DIVIDE", "Average HC", "Attrition"]}, {"id": 514, "cat": "hr", "sub": "Attrition & Retention", "diff": "intermediate", "title": "Attrition Rate % (Standard)", "q": "What percentage of the workforce left in the period?", "dax": "Attrition Rate % =\nDIVIDE (\n    [Total Leavers],\n    [Avg HC for Period]\n)", "insight": "<strong>Industry benchmarks:</strong> Tech 13–20%, Professional Services 10–15%, Retail 25–35%, Healthcare 15–20%. Segment by voluntary vs involuntary for meaningful action.", "tags": ["DIVIDE", "Total Leavers", "Avg HC", "Attrition", "Rate"]}, {"id": 515, "cat": "hr", "sub": "Attrition & Retention", "diff": "advanced", "title": "Annualised Attrition Rate %", "q": "What is the attrition rate projected to a full year if current pace continues?", "dax": "Annualised Attrition % =\nVAR _months =\n    DATEDIFF (\n        MIN ( M_Date[Date] ),\n        MAX ( M_Date[Date] ),\n        MONTH\n    ) + 1\nRETURN\n    DIVIDE (\n        [Total Leavers] * 12,\n        [Avg HC for Period] * _months\n    )", "insight": "<strong>Extrapolates partial-period data</strong> to a full-year rate. Essential when reporting mid-year — \"We\\'re at 6% attrition through June = 12% annualised pace.\"", "tags": ["VAR", "DATEDIFF", "DIVIDE", "Annualised", "Attrition"]}, {"id": 516, "cat": "hr", "sub": "Attrition & Retention", "diff": "intermediate", "title": "Rolling 12-Month Attrition Rate", "q": "What is the attrition rate over the last 12 months from any point in time?", "dax": "Rolling 12M Attrition % =\nVAR _leavers12M =\n    CALCULATE (\n        [Total Leavers],\n        DATESINPERIOD (\n            M_Date[Date],\n            LASTDATE ( M_Date[Date] ),\n            -12, MONTH\n        )\n    )\nVAR _avgHC12M =\n    CALCULATE (\n        [Avg HC for Period],\n        DATESINPERIOD (\n            M_Date[Date],\n            LASTDATE ( M_Date[Date] ),\n            -12, MONTH\n        )\n    )\nRETURN\n    DIVIDE ( _leavers12M, _avgHC12M )", "insight": "<strong>The most reliable attrition KPI.</strong> Unlike point-in-time annual rates, the rolling 12M responds to the latest data and smooths seasonal hiring/leaving patterns.", "tags": ["VAR", "CALCULATE", "DATESINPERIOD", "Rolling", "12M", "Attrition"]}, {"id": 517, "cat": "hr", "sub": "Attrition & Retention", "diff": "intermediate", "title": "Voluntary Attrition Rate %", "q": "What percentage of leavers chose to resign?", "dax": "Voluntary Attrition % =\nDIVIDE (\n    CALCULATE (\n        [Total Leavers],\n        M_Employees[LeaveReason] = \"Voluntary\"\n    ),\n    [Avg HC for Period]\n)", "insight": "<strong>The most actionable attrition metric.</strong> Voluntary exits are within your control — they signal dissatisfaction with pay, culture, manager, or growth. Involuntary exits are business decisions.", "tags": ["DIVIDE", "CALCULATE", "Voluntary", "Attrition", "LeaveReason"]}, {"id": 518, "cat": "hr", "sub": "Attrition & Retention", "diff": "intermediate", "title": "Involuntary Attrition Rate %", "q": "What percentage of leavers were made redundant or dismissed?", "dax": "Involuntary Attrition % =\nDIVIDE (\n    CALCULATE (\n        [Total Leavers],\n        M_Employees[LeaveReason] = \"Involuntary\"\n    ),\n    [Avg HC for Period]\n)", "insight": "<strong>Workforce restructuring signal.</strong> A spike in involuntary attrition may indicate a redundancy programme, performance management push, or disciplinary issues — each requiring different responses.", "tags": ["DIVIDE", "CALCULATE", "Involuntary", "Attrition", "LeaveReason"]}, {"id": 519, "cat": "hr", "sub": "Attrition & Retention", "diff": "advanced", "title": "Regrettable Attrition Rate %", "q": "What percentage of leavers were flagged as regrettable losses?", "dax": "Regrettable Attrition % =\nDIVIDE (\n    CALCULATE (\n        [Total Leavers],\n        M_Employees[IsRegrettable] = TRUE ()\n    ),\n    [Avg HC for Period]\n)", "insight": "<strong>Quality-of-attrition metric.</strong> Requires HR to tag leavers as regrettable/non-regrettable at exit. 5%+ regrettable attrition should trigger immediate retention intervention.", "tags": ["DIVIDE", "CALCULATE", "Regrettable", "Attrition", "IsRegrettable"]}, {"id": 520, "cat": "hr", "sub": "Attrition & Retention", "diff": "advanced", "title": "Early Attrition — Leavers Within 12 Months", "q": "How many employees left within 12 months of joining?", "dax": "Early Leavers (<12M) =\nCALCULATE (\n    COUNTROWS ( M_Employees ),\n    FILTER (\n        M_Employees,\n        M_Employees[Status] = \"Left\"\n            && DATEDIFF (\n                M_Employees[JoinDate],\n                M_Employees[LeaveDate],\n                MONTH\n            ) <= 12\n    )\n)", "insight": "<strong>Onboarding effectiveness signal.</strong> High early attrition (>20% of joiners leaving within 12M) means the problem is in your hiring, induction, or immediate manager experience.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "DATEDIFF", "Early Attrition", "Onboarding"]}, {"id": 521, "cat": "hr", "sub": "Attrition & Retention", "diff": "intermediate", "title": "Retention Rate %", "q": "What percentage of employees are still with the organisation?", "dax": "Retention Rate % =\n1 - [Attrition Rate %]", "insight": "<strong>The positive framing of attrition.</strong> Some boards and HR leaders prefer to report retention rather than attrition — same data, different psychology. A 90% retention rate is an 10% attrition rate.", "tags": ["Retention", "Attrition", "Rate", "%"]}, {"id": 522, "cat": "hr", "sub": "Attrition & Retention", "diff": "intermediate", "title": "Attrition Rate % — By Department", "q": "Which department has the highest attrition rate?", "dax": "Dept Attrition % =\nDIVIDE (\n    CALCULATE (\n        [Total Leavers],\n        ALLEXCEPT ( M_Employees, M_Employees[Department] )\n    ),\n    CALCULATE (\n        [Avg HC for Period],\n        ALLEXCEPT ( M_Employees, M_Employees[Department] )\n    )\n)", "insight": "<strong>Use in a matrix visual</strong> with Department as rows. An attrition rate 2× the company average in one department is a management or culture red flag requiring investigation.", "tags": ["DIVIDE", "CALCULATE", "ALLEXCEPT", "Department", "Attrition"]}, {"id": 523, "cat": "hr", "sub": "Recruitment", "diff": "basic", "title": "Open Vacancies", "q": "How many positions are currently unfilled?", "dax": "Open Vacancies =\nCALCULATE (\n    COUNTROWS ( Recruitment ),\n    F_Recruitment[Status] = \"Open\"\n)", "insight": "<strong>Workforce gap indicator.</strong> Track open vacancies by department and grade. Vacancies open >60 days signal a broken recruitment process or unrealistic hiring criteria.", "tags": ["CALCULATE", "COUNTROWS", "Recruitment", "Vacancies", "Open"]}, {"id": 524, "cat": "hr", "sub": "Recruitment", "diff": "basic", "title": "Vacancies Filled in Period", "q": "How many positions were successfully filled in the selected period?", "dax": "Vacancies Filled =\nCALCULATE (\n    COUNTROWS ( Recruitment ),\n    F_Recruitment[Status] = \"Filled\",\n    F_Recruitment[FilledDate] >= MIN ( M_Date[Date] ),\n    F_Recruitment[FilledDate] <= MAX ( M_Date[Date] )\n)", "insight": "<strong>Recruitment output metric.</strong> Compare against [Open Vacancies] — if you\\'re filling fewer positions than are opening each month, your backlog is growing.", "tags": ["CALCULATE", "COUNTROWS", "Recruitment", "Filled", "Vacancies"]}, {"id": 525, "cat": "hr", "sub": "Recruitment", "diff": "intermediate", "title": "Average Time to Fill (Days)", "q": "How many days on average from vacancy opening to position filled?", "dax": "Avg Time to Fill =\nAVERAGEX (\n    FILTER (\n        Recruitment,\n        F_Recruitment[Status] = \"Filled\"\n            && NOT ISBLANK ( F_Recruitment[FilledDate] )\n    ),\n    DATEDIFF (\n        F_Recruitment[OpenDate],\n        F_Recruitment[FilledDate],\n        DAY\n    )\n)", "insight": "<strong>Benchmark: 30–45 days</strong> for most roles; 60–90 days for senior/specialist. Above 60 days creates productivity gaps and adds pressure to existing team members.", "tags": ["AVERAGEX", "FILTER", "DATEDIFF", "Time to Fill", "Recruitment"]}, {"id": 526, "cat": "hr", "sub": "Recruitment", "diff": "intermediate", "title": "Average Time to Hire (Days)", "q": "How many days on average from application received to offer accepted?", "dax": "Avg Time to Hire =\nAVERAGEX (\n    FILTER (\n        Recruitment,\n        F_Recruitment[OfferAccepted] = TRUE ()\n    ),\n    DATEDIFF (\n        F_Recruitment[ApplicationDate],\n        F_Recruitment[HireDate],\n        DAY\n    )\n)", "insight": "<strong>Time to Hire vs Time to Fill:</strong> Time to Fill measures process speed; Time to Hire measures candidate experience speed. Both matter — slow hiring loses top candidates to competitors.", "tags": ["AVERAGEX", "FILTER", "DATEDIFF", "Time to Hire", "Recruitment"]}, {"id": 527, "cat": "hr", "sub": "Recruitment", "diff": "intermediate", "title": "Offer Acceptance Rate %", "q": "What percentage of job offers made were accepted by candidates?", "dax": "Offer Acceptance Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Recruitment ),\n        F_Recruitment[OfferAccepted] = TRUE ()\n    ),\n    CALCULATE (\n        COUNTROWS ( Recruitment ),\n        F_Recruitment[OfferMade] = TRUE ()\n    )\n)", "insight": "<strong>Benchmark: 85%+.</strong> Below 70% signals your offers are uncompetitive on salary, benefits, or flexibility. Exit interviews at offer rejection stage are invaluable here.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Offer Acceptance", "Recruitment"]}, {"id": 528, "cat": "hr", "sub": "Recruitment", "diff": "intermediate", "title": "Cost per Hire", "q": "What is the average total cost to recruit one new employee?", "dax": "Cost per Hire =\nDIVIDE (\n    SUM ( F_Recruitment[CostPerHire] ),\n    [Vacancies Filled]\n)", "insight": "<strong>Industry average £3,000–£5,000</strong> for operational roles; £10,000–£30,000+ for senior hires. Include agency fees, advertising, interview time, assessment centre, and onboarding costs.", "tags": ["DIVIDE", "SUM", "Cost per Hire", "Recruitment"]}, {"id": 529, "cat": "hr", "sub": "Recruitment", "diff": "intermediate", "title": "Internal Hire Rate %", "q": "What percentage of vacancies were filled by internal candidates?", "dax": "Internal Hire Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Recruitment ),\n        F_Recruitment[Source] = \"Internal\"\n            && F_Recruitment[Status] = \"Filled\"\n    ),\n    [Vacancies Filled]\n)", "insight": "<strong>Internal mobility metric.</strong> 30–40% internal hire rate is considered healthy — it signals career development opportunity and reduces cost and time to productivity.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Internal", "Recruitment", "Source"]}, {"id": 530, "cat": "hr", "sub": "Recruitment", "diff": "advanced", "title": "Recruiter Efficiency (Hires per Recruiter)", "q": "How many successful hires does each recruiter make in the period?", "dax": "Hires per Recruiter =\nDIVIDE (\n    [Vacancies Filled],\n    DISTINCTCOUNT ( F_Recruitment[RecruiterID] )\n)", "insight": "<strong>Team capacity benchmark.</strong> An experienced in-house recruiter should close 3–5 hires/month for operational roles, 1–2/month for senior or specialist roles.", "tags": ["DIVIDE", "DISTINCTCOUNT", "Recruiter", "Efficiency", "Recruitment"]}, {"id": 531, "cat": "hr", "sub": "Payroll & Salaries", "diff": "basic", "title": "Total Payroll Cost", "q": "What is the total all-in cost of the workforce in the period?", "dax": "Total Payroll Cost =\nSUM ( F_Payroll[TotalCost] )", "insight": "<strong>All-in cost includes:</strong> base salary + employer NI + pension contributions + benefits + bonuses. This is the true workforce cost, not just gross salaries.", "tags": ["SUM", "Payroll", "Total Cost", "HR"]}, {"id": 532, "cat": "hr", "sub": "Payroll & Salaries", "diff": "basic", "title": "Average Salary", "q": "What is the mean base salary across active employees?", "dax": "Average Salary =\nAVERAGEX (\n    FILTER (\n        M_Employees,\n        M_Employees[Status] = \"Active\"\n    ),\n    CALCULATE ( MAX ( F_Payroll[BaseSalary] ) )\n)", "insight": "<strong>Mean can be distorted by outliers.</strong> Always report alongside Median Salary — if Mean >> Median, a few very high earners are skewing the picture.", "tags": ["AVERAGEX", "FILTER", "CALCULATE", "MAX", "Average Salary", "Payroll"]}, {"id": 533, "cat": "hr", "sub": "Payroll & Salaries", "diff": "intermediate", "title": "Median Salary", "q": "What is the middle salary — the point where 50% earn more and 50% earn less?", "dax": "Median Salary =\nMEDIANX (\n    FILTER (\n        M_Employees,\n        M_Employees[Status] = \"Active\"\n    ),\n    CALCULATE ( MAX ( F_Payroll[BaseSalary] ) )\n)", "insight": "<strong>The fairer central tendency measure.</strong> The UK gender pay gap reporting requires median, not mean. Use MEDIANX not MEDIAN for flexibility across filtered contexts.", "tags": ["MEDIANX", "FILTER", "CALCULATE", "Median Salary", "Payroll", "Gender Pay"]}, {"id": 534, "cat": "hr", "sub": "Payroll & Salaries", "diff": "basic", "title": "Highest Salary", "q": "What is the highest base salary in the active workforce?", "dax": "Highest Salary =\nCALCULATE (\n    MAX ( F_Payroll[BaseSalary] ),\n    M_Employees[Status] = \"Active\"\n)", "insight": "<strong>Compensation ceiling check.</strong> Track against market benchmarks. If your highest salary is below market median for that role, you face flight risk in your top talent.", "tags": ["CALCULATE", "MAX", "Highest Salary", "Payroll"]}, {"id": 535, "cat": "hr", "sub": "Payroll & Salaries", "diff": "basic", "title": "Lowest Salary", "q": "What is the lowest base salary in the active workforce?", "dax": "Lowest Salary =\nCALCULATE (\n    MIN ( F_Payroll[BaseSalary] ),\n    M_Employees[Status] = \"Active\"\n)", "insight": "<strong>Compliance and equity check.</strong> Must never fall below the National Living Wage. Use alongside Median to show the salary distribution range to leadership.", "tags": ["CALCULATE", "MIN", "Lowest Salary", "Payroll", "Compliance"]}, {"id": 536, "cat": "hr", "sub": "Payroll & Salaries", "diff": "intermediate", "title": "Salary Range (Spread)", "q": "What is the difference between the highest and lowest salary?", "dax": "Salary Range =\n[Highest Salary] - [Lowest Salary]", "insight": "<strong>Pay dispersion metric.</strong> A very wide range without clear grade structure signals pay inequity. Use alongside Band Level analysis to ensure range is justified by role, not by favouritism.", "tags": ["Salary Range", "Spread", "Payroll", "Equity"]}, {"id": 537, "cat": "hr", "sub": "Payroll & Salaries", "diff": "intermediate", "title": "Average Salary by Grade / Band", "q": "What is the average salary at each grade or band level?", "dax": "Avg Salary by Grade =\nAVERAGEX (\n    FILTER (\n        M_Employees,\n        M_Employees[Status] = \"Active\"\n            && M_Employees[BandLevel]\n                = MAX ( M_Employees[BandLevel] )\n    ),\n    CALCULATE ( MAX ( F_Payroll[BaseSalary] ) )\n)", "insight": "<strong>Compensation structure audit.</strong> Use in a matrix with BandLevel as rows. Overlapping salary ranges between adjacent bands signals a broken grading structure.", "tags": ["AVERAGEX", "FILTER", "CALCULATE", "Grade", "Band", "Salary", "Payroll"]}, {"id": 538, "cat": "hr", "sub": "Payroll & Salaries", "diff": "intermediate", "title": "Payroll as % of Revenue", "q": "What percentage of revenue is spent on total workforce cost?", "dax": "Payroll % of Revenue =\nDIVIDE (\n    [Total Payroll Cost],\n    [Total Sales]\n)", "insight": "<strong>Benchmarks by sector:</strong> Professional services 50–65%, Manufacturing 15–30%, Retail 8–15%, Tech 35–50%. Rising % = cost pressure; falling % = productivity improvement or wage suppression.", "tags": ["DIVIDE", "Payroll", "% of Revenue", "Efficiency"]}, {"id": 539, "cat": "hr", "sub": "Payroll & Salaries", "diff": "intermediate", "title": "Payroll Cost per Employee", "q": "What is the average all-in workforce cost per person?", "dax": "Payroll Cost per Employee =\nDIVIDE (\n    [Total Payroll Cost],\n    [Active Headcount]\n)", "insight": "<strong>True cost of a headcount.</strong> Always higher than base salary — typically 1.2–1.4× salary when NI, pension, and benefits are included. Use in headcount business cases.", "tags": ["DIVIDE", "Payroll", "Cost per Employee", "Headcount"]}, {"id": 540, "cat": "hr", "sub": "Payroll & Salaries", "diff": "advanced", "title": "Payroll YoY Growth %", "q": "Is the total payroll cost growing faster or slower than last year?", "dax": "Payroll [KPI] YoY Growth % =\nVAR _curr =\n    CALCULATE (\n        [Total Payroll Cost],\n        DATESMTD ( M_Date[Date] )\n    )\nVAR _ly =\n    CALCULATE (\n        [Total Payroll Cost],\n        DATESMTD ( SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    DIVIDE ( _curr - _ly, _ly )", "insight": "<strong>Workforce cost inflation tracker.</strong> Payroll growing faster than revenue means headcount is outpacing productivity. Payroll growing slower than headcount means average pay is declining in real terms.", "tags": ["VAR", "CALCULATE", "DATESMTD", "SAMEPERIODLASTYEAR", "Payroll", "YoY", "Growth"]}, {"id": 541, "cat": "hr", "sub": "Leave & Absence", "diff": "basic", "title": "Total Leave Days Taken", "q": "How many leave days have been taken in the selected period?", "dax": "Total Leave Days Taken =\nCALCULATE (\n    SUM ( F_Leave[DaysTaken] ),\n    F_Leave[Status] = \"Taken\"\n)", "insight": "<strong>Baseline leave consumption metric.</strong> Split by LeaveType (Annual, Sick, Maternity, etc.) using filter pills to understand leave composition.", "tags": ["CALCULATE", "SUM", "Leave", "DaysTaken"]}, {"id": 542, "cat": "hr", "sub": "Leave & Absence", "diff": "intermediate", "title": "Average Leave Days per Employee", "q": "How many leave days does each employee take on average?", "dax": "Avg Leave Days per Employee =\nDIVIDE (\n    [Total Leave Days Taken],\n    [Active Headcount]\n)", "insight": "<strong>Wellbeing and culture indicator.</strong> Very low average (<10 days in a 25-day entitlement) suggests presenteeism — employees not taking leave due to workload or culture pressure.", "tags": ["DIVIDE", "Leave", "Average", "Per Employee"]}, {"id": 543, "cat": "hr", "sub": "Leave & Absence", "diff": "intermediate", "title": "Leave Utilisation %", "q": "What percentage of the total leave entitlement has been taken?", "dax": "Leave Utilisation % =\nDIVIDE (\n    SUM ( F_Leave[DaysTaken] ),\n    SUM ( F_Leave[Entitlement] )\n)", "insight": "<strong>Target 80–90% by year-end.</strong> Very high utilisation (>95%) may mean people can\\'t take leave when they want it. Very low (<50%) signals untaken leave liability building on the balance sheet.", "tags": ["DIVIDE", "SUM", "Leave", "Utilisation", "Entitlement"]}, {"id": 544, "cat": "hr", "sub": "Leave & Absence", "diff": "intermediate", "title": "Leave Days Outstanding (Untaken Entitlement)", "q": "How many leave days remain untaken across the workforce?", "dax": "Leave Days Outstanding =\nSUM ( F_Leave[Entitlement] ) - SUM ( F_Leave[DaysTaken] )", "insight": "<strong>Balance sheet liability.</strong> Untaken leave is an accrued liability — it must be paid out or carried over. Large outstanding balances at year-end signal operational pressure or reluctance to take leave.", "tags": ["SUM", "Leave", "Outstanding", "Entitlement", "Liability"]}, {"id": 545, "cat": "hr", "sub": "Leave & Absence", "diff": "intermediate", "title": "Absenteeism Rate %", "q": "What percentage of scheduled working days are lost to unplanned absence?", "dax": "Absenteeism Rate % =\nDIVIDE (\n    SUM ( F_Absence[Days] ),\n    CALCULATE (\n        SUM ( F_Leave[Entitlement] ),\n        F_Leave[LeaveType] = \"Working Days\"\n    )\n)", "insight": "<strong>UK average is ~4.5 days per employee per year</strong> (CIPD benchmark). Above 6 days/year signals systemic wellbeing issues. Track by team — high absence in one team is almost always a management or culture problem.", "tags": ["DIVIDE", "SUM", "CALCULATE", "Absenteeism", "Absence", "Rate"]}, {"id": 546, "cat": "hr", "sub": "Leave & Absence", "diff": "intermediate", "title": "Absenteeism Days Lost", "q": "How many working days were lost to unplanned absence in the period?", "dax": "Absence Days Lost =\nSUM ( F_Absence[Days] )", "insight": "<strong>Operational and cost impact metric.</strong> Convert to cost: [Absence Days Lost] × [Average Daily Salary] = estimated productivity loss from absence.", "tags": ["SUM", "Absence", "Days Lost", "Operational Impact"]}, {"id": 547, "cat": "hr", "sub": "Leave & Absence", "diff": "advanced", "title": "Bradford Factor Score", "q": "What is the Bradford Factor score per employee (measures absence frequency impact)?", "dax": "Bradford Factor =\nVAR _spells =\n    CALCULATE (\n        DISTINCTCOUNT ( F_Absence[SpellNumber] ),\n        ALLEXCEPT ( Absence, F_Absence[EmployeeID] )\n    )\nVAR _days =\n    CALCULATE (\n        SUM ( F_Absence[Days] ),\n        ALLEXCEPT ( Absence, F_Absence[EmployeeID] )\n    )\nRETURN\n    _spells * _spells * _days", "insight": "<strong>Formula: S² × D</strong> (Spells squared × Total Days). 450+ = formal review trigger. 900+ = final written warning territory. Frequent short absences score higher than one long absence — which is the intent.", "tags": ["VAR", "CALCULATE", "DISTINCTCOUNT", "Bradford Factor", "Absence", "Spells"]}, {"id": 548, "cat": "hr", "sub": "Leave & Absence", "diff": "intermediate", "title": "Sick Leave vs Annual Leave Split", "q": "What proportion of leave taken is sick leave vs annual leave?", "dax": "Sick Leave % of Total Leave =\nDIVIDE (\n    CALCULATE (\n        SUM ( F_Leave[DaysTaken] ),\n        F_Leave[LeaveType] = \"Sick\"\n    ),\n    [Total Leave Days Taken]\n)", "insight": "<strong>Wellbeing composition metric.</strong> Rising sick leave % is a leading indicator of workforce stress, burnout, or underlying health issues before they become resignations.", "tags": ["DIVIDE", "CALCULATE", "SUM", "Sick Leave", "Annual Leave", "Wellbeing"]}, {"id": 549, "cat": "hr", "sub": "HR Efficiency", "diff": "intermediate", "title": "Revenue per Employee", "q": "How much revenue does the organisation generate per employee?", "dax": "Revenue per Employee =\nDIVIDE (\n    [Total Sales],\n    [Active Headcount]\n)", "insight": "<strong>Workforce productivity KPI.</strong> Track YoY — rising revenue per employee = scaling efficiently. Falling = headcount growing faster than revenue. SaaS benchmark: £150K–£500K+.", "tags": ["DIVIDE", "Revenue", "Per Employee", "Productivity", "HR Efficiency"]}, {"id": 550, "cat": "hr", "sub": "HR Efficiency", "diff": "intermediate", "title": "HR to Employee Ratio", "q": "How many employees are supported by each HR professional?", "dax": "HR to Employee Ratio =\nDIVIDE (\n    [Active Headcount],\n    CALCULATE (\n        [Active Headcount],\n        M_Employees[Department] = \"Human Resources\"\n    )\n)", "insight": "<strong>HR function sizing benchmark.</strong> Typical ratio: 1 HR per 50–100 employees in mature organisations. Fast-growing companies often run leaner at 1:150, compensating with HRIS automation.", "tags": ["DIVIDE", "CALCULATE", "HR Ratio", "Headcount", "HR Efficiency"]}, {"id": 551, "cat": "hr", "sub": "HR Efficiency", "diff": "advanced", "title": "Internal Promotion Rate %", "q": "What percentage of open roles were filled by promoting existing employees?", "dax": "Internal Promotion Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Recruitment ),\n        F_Recruitment[Source] = \"Internal\"\n            && F_Recruitment[Status] = \"Filled\"\n    ),\n    [Active Headcount]\n)", "insight": "<strong>Career development and culture metric.</strong> Companies with strong internal promotion (>30%) show lower attrition, higher engagement, and faster time-to-productivity for new role occupants.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Promotion", "Internal", "HR Efficiency"]}, {"id": 552, "cat": "hr", "sub": "HR Efficiency", "diff": "intermediate", "title": "Payroll Cost as % of Total Opex", "q": "What share of total operating expenses is people cost?", "dax": "Payroll % of Opex =\nDIVIDE (\n    [Total Payroll Cost],\n    [Total Opex]\n)", "insight": "<strong>Cost structure insight.</strong> For knowledge-based businesses (consulting, tech, finance), payroll is typically 60–80% of Opex. Use alongside [Payroll % of Revenue] for a complete labour cost picture.", "tags": ["DIVIDE", "Payroll", "Opex", "% of Total", "Cost Structure"]}, {"id": 553, "cat": "hr", "sub": "HR Efficiency", "diff": "advanced", "title": "Average Days to Onboard (Productive)", "q": "How many days from start date until a new hire reaches productivity?", "dax": "Avg Days to Productivity =\nAVERAGEX (\n    FILTER (\n        Recruitment,\n        NOT ISBLANK ( F_Recruitment[ProductivityDate] )\n    ),\n    DATEDIFF (\n        F_Recruitment[HireDate],\n        F_Recruitment[ProductivityDate],\n        DAY\n    )\n)", "insight": "<strong>Onboarding effectiveness measure.</strong> Requires HR to log the date a manager marks a new hire as fully productive. Benchmark: 30 days (simple roles) to 180+ days (complex/senior roles).", "tags": ["AVERAGEX", "FILTER", "DATEDIFF", "Onboarding", "Productivity", "Recruitment"]}, {"id": 554, "cat": "hr", "sub": "HR Efficiency", "diff": "advanced", "title": "Total Cost of Attrition", "q": "What is the estimated financial cost of all leavers in the period?", "dax": "Cost of Attrition =\nVAR _costPerHire    = [Cost per Hire]\nVAR _avgSalary      = [Average Salary]\nVAR _onboardingMths = 3  -- months to productivity\nVAR _costPerLeaver  =\n    _costPerHire\n        + DIVIDE ( _avgSalary, 12 ) * _onboardingMths\nRETURN\n    [Total Leavers] * _costPerLeaver", "insight": "<strong>The business case for retention investment.</strong> Rule of thumb: replacing an employee costs 50–200% of annual salary when recruitment, training, and lost productivity are included. This makes attrition visible in £ terms to the board.", "tags": ["VAR", "DIVIDE", "Cost", "Attrition", "Business Case", "Retention"]}, {"id": 601, "cat": "operations", "sub": "OEE & Efficiency", "diff": "intermediate", "title": "OEE (Overall Equipment Effectiveness)", "q": "What is the combined availability, performance and quality score?", "dax": "OEE =\n[Availability %] * [Performance %] * [Quality %]", "insight": "<strong>World-class OEE is 85%+.</strong> Weakness in any one factor drags the whole score — OEE 60% means 40% of capacity is being wasted.", "tags": ["OEE", "Multiply", "Manufacturing"]}, {"id": 602, "cat": "operations", "sub": "OEE & Efficiency", "diff": "intermediate", "title": "Availability %", "q": "What percentage of scheduled time was the equipment actually running?", "dax": "Availability % =\nDIVIDE (\n    SUM ( F_Production[ScheduledMinutes] ) - SUM ( F_Production[DowntimeMinutes] ),\n    SUM ( F_Production[ScheduledMinutes] )\n)", "insight": "<strong>First OEE factor.</strong> Availability losses come from breakdowns and changeovers. Target 90%+. Below 80% means unplanned downtime is the primary OEE drag.", "tags": ["DIVIDE", "Availability", "OEE", "Downtime"]}, {"id": 603, "cat": "operations", "sub": "OEE & Efficiency", "diff": "intermediate", "title": "Planned Downtime %", "q": "What percentage of time is lost to scheduled maintenance and changeovers?", "dax": "Planned Downtime % =\nDIVIDE (\n    SUM ( F_Production[PlannedDowntimeMinutes] ),\n    SUM ( F_Production[ScheduledMinutes] )\n)", "insight": "<strong>Controllable downtime.</strong> Planned maintenance is necessary but should be minimised through SMED (changeover reduction) and preventive maintenance scheduling.", "tags": ["DIVIDE", "Planned Downtime", "Operations", "Maintenance"]}, {"id": 604, "cat": "operations", "sub": "OEE & Efficiency", "diff": "intermediate", "title": "Unplanned Downtime %", "q": "What percentage of time is lost to unexpected breakdowns?", "dax": "Unplanned Downtime % =\nDIVIDE (\n    SUM ( F_Production[UnplannedDowntimeMinutes] ),\n    SUM ( F_Production[ScheduledMinutes] )\n)", "insight": "<strong>Most costly downtime type.</strong> Unplanned downtime cascades — it disrupts schedules, creates overtime, and erodes OTD. Track by machine and failure mode for root cause action.", "tags": ["DIVIDE", "Unplanned Downtime", "Operations", "Breakdown"]}, {"id": 605, "cat": "operations", "sub": "OEE & Efficiency", "diff": "intermediate", "title": "Capacity Utilisation %", "q": "What percentage of total available capacity is being used?", "dax": "Capacity Utilisation % =\nDIVIDE (\n    SUM ( F_Production[UnitsProduced] ),\n    SUM ( F_Production[TheoreticalCapacity] )\n)", "insight": "<strong>70–85% is the sweet spot.</strong> Below 70% = underutilised assets. Above 90% = no buffer for demand spikes, breakdowns, or quality issues — risk of customer delivery failures.", "tags": ["DIVIDE", "Capacity", "Utilisation", "Production"]}, {"id": 606, "cat": "operations", "sub": "OEE & Efficiency", "diff": "intermediate", "title": "Units per Labour Hour", "q": "How many units of output does each labour hour produce?", "dax": "Units per Labour Hour =\nDIVIDE (\n    SUM ( F_Production[UnitsProduced] ),\n    SUM ( F_Production[LabourHours] )\n)", "insight": "<strong>Labour productivity index.</strong> Track week-over-week — declining units per hour signals fatigue, high learning curve (new starters), or process breakdown.", "tags": ["DIVIDE", "Labour", "Productivity", "Output", "Hours"]}, {"id": 607, "cat": "operations", "sub": "Quality", "diff": "intermediate", "title": "First Pass Yield % (FPY)", "q": "What percentage of units are produced correctly the first time without rework?", "dax": "First Pass Yield % =\nDIVIDE (\n    SUM ( F_Production[UnitsProduced] ) - SUM ( F_Production[ReworkUnits] ),\n    SUM ( F_Production[UnitsProduced] )\n)", "insight": "<strong>True quality metric.</strong> FPY 95% means 5% of production requires rework — doubling the cost of those units. Six Sigma target is 99.99966% (3.4 defects per million).", "tags": ["DIVIDE", "FPY", "Quality", "Rework", "Six Sigma"]}, {"id": 608, "cat": "operations", "sub": "Quality", "diff": "intermediate", "title": "Defect Rate (PPM)", "q": "How many defective units per million produced?", "dax": "Defect Rate PPM =\nDIVIDE (\n    SUM ( F_Production[DefectiveUnits] ),\n    SUM ( F_Production[UnitsProduced] )\n) * 1000000", "insight": "<strong>Industry standard quality measure.</strong> Automotive targets <50 PPM. Electronics: <100 PPM. Consumer goods: <500 PPM. Use trend charts — a rising PPM needs immediate process investigation.", "tags": ["DIVIDE", "PPM", "Defects", "Quality", "Manufacturing"]}, {"id": 609, "cat": "operations", "sub": "Quality", "diff": "intermediate", "title": "Rework Rate %", "q": "What percentage of output required rework before passing quality checks?", "dax": "Rework Rate % =\nDIVIDE (\n    SUM ( F_Production[ReworkUnits] ),\n    SUM ( F_Production[UnitsProduced] )\n)", "insight": "<strong>Hidden cost of poor quality.</strong> 5% rework rate on 10,000 units/month = 500 units reworked. Calculate cost: 500 × [Labour Cost per Unit] × 2 = your monthly rework cost.", "tags": ["DIVIDE", "Rework", "Quality", "Cost", "Production"]}, {"id": 610, "cat": "operations", "sub": "Quality", "diff": "advanced", "title": "Cost of Poor Quality (COPQ)", "q": "What is the total financial cost of defects, rework and scrap?", "dax": "Cost of Poor Quality =\nCALCULATE (\n    SUM ( F_Quality[InternalFailureCost] )\n        + SUM ( F_Quality[ExternalFailureCost] )\n        + SUM ( F_Quality[AppraisalCost] )\n)", "insight": "<strong>Iceberg metric.</strong> Most companies see only warranty claims (above water). Internal failure, rework, and appraisal costs are typically 3–5× larger. COPQ of 5–10% of revenue is common — and largely avoidable.", "tags": ["CALCULATE", "SUM", "COPQ", "Quality", "Cost"]}, {"id": 611, "cat": "operations", "sub": "Reliability", "diff": "advanced", "title": "Mean Time Between Failures (MTBF)", "q": "On average, how many hours does equipment run between unplanned failures?", "dax": "MTBF =\nDIVIDE (\n    SUM ( F_Production[RunTimeHours] ),\n    SUM ( F_Maintenance[FailureCount] )\n)", "insight": "<strong>Reliability indicator.</strong> Rising MTBF = improving equipment reliability. Falling MTBF = increasing breakdown frequency. Use to justify preventive maintenance investment with data.", "tags": ["DIVIDE", "MTBF", "Reliability", "Maintenance", "Failure"]}, {"id": 612, "cat": "operations", "sub": "Reliability", "diff": "advanced", "title": "Mean Time to Repair (MTTR)", "q": "On average, how many hours does it take to restore equipment after a failure?", "dax": "MTTR =\nDIVIDE (\n    SUM ( F_Maintenance[RepairHours] ),\n    SUM ( F_Maintenance[FailureCount] )\n)", "insight": "<strong>Maintenance response efficiency.</strong> Low MTTR = fast repair = less downtime impact. Reduce MTTR by improving spare parts availability, maintenance procedures, and technician training.", "tags": ["DIVIDE", "MTTR", "Maintenance", "Repair", "Reliability"]}, {"id": 613, "cat": "operations", "sub": "Delivery", "diff": "intermediate", "title": "On-Time Delivery % (OTD)", "q": "What percentage of orders were delivered on or before the committed date?", "dax": "On-Time Delivery % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Orders ),\n        F_Orders[DeliveryDate] <= F_Orders[CommittedDate]\n    ),\n    COUNTROWS ( Orders )\n)", "insight": "<strong>Customer-facing reliability metric.</strong> World class: 98%+. Below 90% starts to damage customer relationships and triggers penalty clauses in contracts.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "OTD", "Delivery", "On-Time"]}, {"id": 614, "cat": "operations", "sub": "Delivery", "diff": "intermediate", "title": "On-Time In-Full % (OTIF)", "q": "What percentage of orders were delivered on time AND with the correct quantity?", "dax": "OTIF % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Orders ),\n        F_Orders[DeliveryDate] <= F_Orders[CommittedDate]\n            && F_Orders[QtyDelivered] = F_Orders[QtyOrdered]\n    ),\n    COUNTROWS ( Orders )\n)", "insight": "<strong>Stricter than OTD.</strong> OTIF fails if even one unit is short — the gold standard for FMCG retail delivery. Major retailers often impose financial penalties for OTIF below 98%.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "OTIF", "Delivery", "In-Full"]}, {"id": 615, "cat": "operations", "sub": "Delivery", "diff": "intermediate", "title": "Average Delivery Lead Time (Days)", "q": "How many days on average from order placed to delivery?", "dax": "Avg Lead Time Days =\nAVERAGEX (\n    Orders,\n    DATEDIFF (\n        F_Orders[OrderDate],\n        F_Orders[DeliveryDate],\n        DAY\n    )\n)", "insight": "<strong>Customer promise metric.</strong> Shorter lead times are a competitive differentiator. Track by product category — long lead time categories may benefit from safety stock build or supplier renegotiation.", "tags": ["AVERAGEX", "DATEDIFF", "Lead Time", "Delivery", "Days"]}, {"id": 616, "cat": "operations", "sub": "Delivery", "diff": "intermediate", "title": "Order Fill Rate %", "q": "What percentage of ordered items were shipped from available stock?", "dax": "Order Fill Rate % =\nDIVIDE (\n    SUM ( F_Orders[QtyShipped] ),\n    SUM ( F_Orders[QtyOrdered] )\n)", "insight": "<strong>Inventory adequacy measure.</strong> Fill rate below 95% signals chronic stockout issues. Decompose by product and warehouse location to find the root cause.", "tags": ["DIVIDE", "SUM", "Fill Rate", "Orders", "Inventory"]}, {"id": 617, "cat": "operations", "sub": "Delivery", "diff": "advanced", "title": "Supplier On-Time Delivery %", "q": "What percentage of supplier deliveries arrived by the promised date?", "dax": "Supplier OTD % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( PurchaseOrders ),\n        F_PurchaseOrders[ActualDelivery]\n            <= F_PurchaseOrders[PromisedDelivery]\n    ),\n    COUNTROWS ( PurchaseOrders )\n)", "insight": "<strong>Supply chain risk metric.</strong> Poor supplier OTD cascades into your own OTIF failures. Use this to negotiate SLAs, select preferred suppliers, and trigger dual-sourcing decisions.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Supplier", "OTD", "Supply Chain"]}, {"id": 618, "cat": "operations", "sub": "Production & Output", "diff": "basic", "title": "Units Produced", "q": "How many units were produced in the selected period?", "dax": "Units Produced =\nSUM ( F_Production[UnitsProduced] )", "insight": "<strong>Base production volume metric.</strong> Compare against Production Plan to get actual vs planned. Use in trend charts to spot declining output before it affects customer delivery.", "tags": ["SUM", "Units", "Production", "Output"]}, {"id": 619, "cat": "operations", "sub": "Production & Output", "diff": "intermediate", "title": "Production vs Plan %", "q": "What percentage of the production plan was actually achieved?", "dax": "Production vs Plan % =\nDIVIDE (\n    SUM ( F_Production[UnitsProduced] ),\n    SUM ( F_Production[PlannedUnits] )\n)", "insight": "<strong>Execution reliability metric.</strong> Consistently below 90% signals either over-optimistic planning or chronic execution problems. Both need different fixes.", "tags": ["DIVIDE", "SUM", "Production", "Plan", "Achievement"]}, {"id": 620, "cat": "operations", "sub": "Production & Output", "diff": "intermediate", "title": "Production Variance (Units)", "q": "How many units above or below plan were produced?", "dax": "Production Variance =\nSUM ( F_Production[UnitsProduced] )\n    - SUM ( F_Production[PlannedUnits] )", "insight": "<strong>Positive = overproduced, Negative = underproduced.</strong> Consistent underproduction creates backlog. Consistent overproduction creates excess inventory. Both are waste.", "tags": ["Variance", "Units", "Production", "Plan"]}, {"id": 701, "cat": "inventory", "sub": "Stock Positions", "diff": "basic", "title": "Current Stock on Hand (Units)", "q": "How many units are currently in stock across all locations?", "dax": "Stock on Hand =\nCALCULATE (\n    SUM ( F_Inventory[QtyOnHand] ),\n    F_Inventory[SnapshotDate] = MAX ( F_Inventory[SnapshotDate] )\n)", "insight": "<strong>Use the latest snapshot date</strong> to get the current position. If your inventory table is a running ledger (not snapshots), replace with: SUM(Receipts[Qty]) − SUM(Issues[Qty]).", "tags": ["CALCULATE", "SUM", "Stock on Hand", "Units", "Inventory"]}, {"id": 702, "cat": "inventory", "sub": "Stock Positions", "diff": "basic", "title": "Stock Value (£)", "q": "What is the total monetary value of current stock at cost?", "dax": "Stock Value =\nCALCULATE (\n    SUM ( F_Inventory[StockValue] ),\n    F_Inventory[SnapshotDate] = MAX ( F_Inventory[SnapshotDate] )\n)", "insight": "<strong>Balance sheet asset.</strong> Stock value at cost (not selling price) is what appears on the balance sheet. Rising stock value without rising sales = build-up risk.", "tags": ["CALCULATE", "SUM", "Stock Value", "Cost", "Inventory"]}, {"id": 703, "cat": "inventory", "sub": "Stock Positions", "diff": "intermediate", "title": "Stock on Order (Units)", "q": "How many units are currently on purchase order but not yet received?", "dax": "Stock on Order =\nCALCULATE (\n    SUM ( F_Inventory[QtyOnOrder] ),\n    F_Inventory[SnapshotDate] = MAX ( F_Inventory[SnapshotDate] )\n)", "insight": "<strong>Pipeline stock visibility.</strong> On-Order + On-Hand gives your total committed stock position. Essential for avoiding double-ordering when stock is in transit.", "tags": ["CALCULATE", "SUM", "On Order", "Pipeline", "Inventory"]}, {"id": 704, "cat": "inventory", "sub": "Stock Positions", "diff": "intermediate", "title": "Available Stock (Unreserved Units)", "q": "How many units are available for sale after reservations are deducted?", "dax": "Available Stock =\nCALCULATE (\n    SUM ( F_Inventory[QtyOnHand] ) - SUM ( F_Inventory[QtyReserved] ),\n    F_Inventory[SnapshotDate] = MAX ( F_Inventory[SnapshotDate] )\n)", "insight": "<strong>True available-to-promise quantity.</strong> Raw QtyOnHand overstates availability — reserved stock is already committed to open orders and must not be double-allocated.", "tags": ["CALCULATE", "SUM", "Available", "Reserved", "Inventory"]}, {"id": 705, "cat": "inventory", "sub": "Stock Positions", "diff": "intermediate", "title": "Stock Below Minimum Level (Alert)", "q": "Which products have stock on hand below the minimum safety stock level?", "dax": "Products Below Min Stock =\nCALCULATE (\n    COUNTROWS ( Inventory ),\n    FILTER (\n        Inventory,\n        F_Inventory[QtyOnHand] < F_Inventory[MinStockLevel]\n            && F_Inventory[SnapshotDate]\n                = MAX ( F_Inventory[SnapshotDate] )\n    )\n)", "insight": "<strong>Stockout risk counter.</strong> Use in a table visual filtered to these products with a red conditional format. Any non-zero value demands immediate procurement action.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "Min Stock", "Alert", "Reorder"]}, {"id": 706, "cat": "inventory", "sub": "Stock Positions", "diff": "intermediate", "title": "Overstock Alert — Above Maximum Level", "q": "How many products have stock above the defined maximum holding level?", "dax": "Products Overstocked =\nCALCULATE (\n    COUNTROWS ( Inventory ),\n    FILTER (\n        Inventory,\n        F_Inventory[QtyOnHand] > F_Inventory[MaxStockLevel]\n            && F_Inventory[SnapshotDate]\n                = MAX ( F_Inventory[SnapshotDate] )\n    )\n)", "insight": "<strong>Capital lock-up signal.</strong> Overstock ties up cash, consumes warehouse space, and increases obsolescence risk — especially critical for perishable or seasonal goods.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "Overstock", "Max Stock", "Alert"]}, {"id": 707, "cat": "inventory", "sub": "Stock Positions", "diff": "intermediate", "title": "Reorder Point Flag", "q": "Which products have reached or fallen below their reorder point?", "dax": "Products at Reorder Point =\nCALCULATE (\n    COUNTROWS ( Inventory ),\n    FILTER (\n        Inventory,\n        F_Inventory[QtyOnHand] <= F_Inventory[ReorderPoint]\n            && F_Inventory[SnapshotDate]\n                = MAX ( F_Inventory[SnapshotDate] )\n    )\n)", "insight": "<strong>Purchasing trigger metric.</strong> Reorder Point = (Avg Daily Sales × Lead Time) + Safety Stock. When stock hits this level, a purchase order should be raised immediately.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "Reorder Point", "Purchasing", "Inventory"]}, {"id": 708, "cat": "inventory", "sub": "Sales Velocity", "diff": "intermediate", "title": "Average Daily Sales (Last 30 Days)", "q": "How many units are being sold per day on average over the last 30 days?", "dax": "Avg Daily Sales 30D =\nDIVIDE (\n    CALCULATE (\n        SUM ( F_Sales[Qty] ),\n        DATESINPERIOD (\n            M_Date[Date],\n            LASTDATE ( M_Date[Date] ),\n            -30, DAY\n        )\n    ),\n    30\n)", "insight": "<strong>Short-term velocity baseline.</strong> Drives days-of-stock calculations. Use 30D for fast-moving goods, 90D for slower categories, 12M for seasonal products with stable annual demand.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "Daily Sales", "Velocity", "30D"]}, {"id": 709, "cat": "inventory", "sub": "Sales Velocity", "diff": "intermediate", "title": "Average Daily Sales (Last 90 Days)", "q": "What is the average daily sales volume over the last 3 months?", "dax": "Avg Daily Sales 90D =\nDIVIDE (\n    CALCULATE (\n        SUM ( F_Sales[Qty] ),\n        DATESINPERIOD (\n            M_Date[Date],\n            LASTDATE ( M_Date[Date] ),\n            -90, DAY\n        )\n    ),\n    90\n)", "insight": "<strong>Medium-term velocity.</strong> More stable than 30D for products with weekly demand cycles. Use for reorder point calculations where lead times are 2–6 weeks.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "Daily Sales", "Velocity", "90D"]}, {"id": 710, "cat": "inventory", "sub": "Sales Velocity", "diff": "intermediate", "title": "Average Daily Sales (Last 12 Months)", "q": "What is the average daily sales volume over the last 12 months?", "dax": "Avg Daily Sales 12M =\nDIVIDE (\n    CALCULATE (\n        SUM ( F_Sales[Qty] ),\n        DATESINPERIOD (\n            M_Date[Date],\n            LASTDATE ( M_Date[Date] ),\n            -12, MONTH\n        )\n    ),\n    365\n)", "insight": "<strong>Annual baseline — best for seasonal products.</strong> A full year captures seasonal highs and lows, giving a fair average for products like sunscreen, Christmas goods, or school stationery.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "Daily Sales", "Velocity", "12M", "Seasonal"]}, {"id": 711, "cat": "inventory", "sub": "Sales Velocity", "diff": "intermediate", "title": "Average Monthly Sales (Last 6 Months)", "q": "How many units are sold per month on average over the last 6 months?", "dax": "Avg Monthly Sales 6M =\nAVERAGEX (\n    DATESINPERIOD (\n        M_Date[Date],\n        LASTDATE ( M_Date[Date] ),\n        -6, MONTH\n    ),\n    CALCULATE ( SUM ( F_Sales[Qty] ) )\n)", "insight": "<strong>Monthly replenishment planning metric.</strong> Divide current stock on hand by this to get months of cover — the go-to metric for monthly ordering cycles.", "tags": ["AVERAGEX", "DATESINPERIOD", "CALCULATE", "Monthly Sales", "Velocity", "6M"]}, {"id": 712, "cat": "inventory", "sub": "Days & Months of Stock", "diff": "intermediate", "title": "Days of Stock — Based on 30D Sales Rate", "q": "How many days will current stock last at the recent 30-day sales pace?", "dax": "Days of Stock (30D) =\nDIVIDE (\n    [Stock on Hand],\n    [Avg Daily Sales 30D]\n)", "insight": "<strong>The most actionable inventory metric.</strong> Under 7 days = critical stockout risk. Over 180 days = severe overstock. Set traffic light thresholds: green 30–90D, amber 15–30D or 90–180D, red outside those ranges.", "tags": ["DIVIDE", "Days of Stock", "30D", "Velocity", "Inventory"]}, {"id": 713, "cat": "inventory", "sub": "Days & Months of Stock", "diff": "intermediate", "title": "Days of Stock — Based on 90D Sales Rate", "q": "How many days will stock last at the 90-day average sales rate?", "dax": "Days of Stock (90D) =\nDIVIDE (\n    [Stock on Hand],\n    [Avg Daily Sales 90D]\n)", "insight": "<strong>More stable than 30D</strong> for products with demand spikes. Use this as your primary DOS metric for medium-turnover goods where 30D can be distorted by a single promotion.", "tags": ["DIVIDE", "Days of Stock", "90D", "Velocity", "Inventory"]}, {"id": 714, "cat": "inventory", "sub": "Days & Months of Stock", "diff": "intermediate", "title": "Months of Stock — Based on 6M Sales Rate", "q": "How many months will current stock last at the 6-month average sales rate?", "dax": "Months of Stock (6M) =\nDIVIDE (\n    [Stock on Hand],\n    [Avg Monthly Sales 6M]\n)", "insight": "<strong>Strategic planning metric.</strong> Months of stock is preferred by supply chain planners for review meetings. Target range varies: FMCG 0.5–2M, pharmaceuticals 2–4M, industrial 3–6M.", "tags": ["DIVIDE", "Months of Stock", "6M", "Planning", "Inventory"]}, {"id": 715, "cat": "inventory", "sub": "Days & Months of Stock", "diff": "advanced", "title": "Inventory Cover vs Target (Over/Under)", "q": "Is current days-of-stock above or below the company target cover level?", "dax": "Stock Cover vs Target =\nVAR _targetDays = 45  -- adjust to your business target\nVAR _actualDays = [Days of Stock (90D)]\nRETURN\n    _actualDays - _targetDays", "insight": "<strong>Change 45 to your target cover days.</strong> Positive = overstocked vs policy, negative = understocked. Use in a clustered bar chart — each product shown as over or under in a single view.", "tags": ["VAR", "Days of Stock", "Target", "Cover", "Over Under", "Policy"]}, {"id": 716, "cat": "inventory", "sub": "Turnover & Efficiency", "diff": "intermediate", "title": "Inventory Turnover Ratio", "q": "How many times is the full stock holding sold and replaced in a year?", "dax": "Inventory Turnover =\nDIVIDE (\n    CALCULATE (\n        SUM ( F_Sales[COGS] ),\n        DATESINPERIOD ( M_Date[Date], LASTDATE ( M_Date[Date] ), -12, MONTH )\n    ),\n    [Stock Value]\n)", "insight": "<strong>Benchmarks by sector:</strong> Grocery/FMCG 12–25×, Apparel 4–6×, Electronics 6–10×, Industrial 3–5×. Low turnover = capital tied up in slow-moving stock.", "tags": ["DIVIDE", "CALCULATE", "DATESINPERIOD", "Inventory Turnover", "Efficiency"]}, {"id": 717, "cat": "inventory", "sub": "Turnover & Efficiency", "diff": "intermediate", "title": "Days Inventory Outstanding (DIO)", "q": "On average, how many days does a unit sit in stock before being sold?", "dax": "DIO =\nDIVIDE (\n    365,\n    [Inventory Turnover]\n)", "insight": "<strong>Working capital metric.</strong> DIO + DSO − DPO = Cash Conversion Cycle. Reducing DIO by 5 days releases significant cash — especially valuable for high-volume, low-margin businesses.", "tags": ["DIVIDE", "DIO", "Days Inventory", "Working Capital", "Cash Conversion"]}, {"id": 718, "cat": "inventory", "sub": "Turnover & Efficiency", "diff": "intermediate", "title": "Gross Margin Return on Inventory (GMROI)", "q": "How much gross profit does each £1 of average inventory investment generate?", "dax": "GMROI =\nDIVIDE (\n    CALCULATE (\n        SUM ( F_Sales[Sale] ) - SUM ( F_Sales[COGS] ),\n        DATESINPERIOD ( M_Date[Date], LASTDATE ( M_Date[Date] ), -12, MONTH )\n    ),\n    [Stock Value]\n)", "insight": "<strong>Best measure of inventory productivity.</strong> GMROI > 1.0 means you earn more than £1 gross profit per £1 of stock held. Retail benchmark: 3.0+. Below 1.0 = the inventory is destroying value.", "tags": ["DIVIDE", "CALCULATE", "GMROI", "Gross Margin", "Return", "Inventory"]}, {"id": 719, "cat": "inventory", "sub": "Turnover & Efficiency", "diff": "advanced", "title": "Slow-Moving Stock (No Sales in 90 Days)", "q": "How many products have had zero sales in the last 90 days?", "dax": "Slow Moving SKUs =\nCALCULATE (\n    DISTINCTCOUNT ( F_Inventory[ProductID] ),\n    FILTER (\n        Inventory,\n        CALCULATE (\n            SUM ( F_Sales[Qty] ),\n            DATESINPERIOD (\n                M_Date[Date],\n                LASTDATE ( M_Date[Date] ),\n                -90, DAY\n            )\n        ) = 0\n            && F_Inventory[QtyOnHand] > 0\n    )\n)", "insight": "<strong>Obsolescence risk register.</strong> Slow movers tie up cash and warehouse space. Trigger mark-down, return-to-supplier, or write-off process for items >90 days with no sales.", "tags": ["CALCULATE", "DISTINCTCOUNT", "FILTER", "DATESINPERIOD", "Slow Moving", "Obsolescence"]}, {"id": 720, "cat": "inventory", "sub": "Turnover & Efficiency", "diff": "advanced", "title": "Dead Stock Value (No Sales in 180 Days)", "q": "What is the total stock value of products with zero sales in 6 months?", "dax": "Dead Stock Value =\nCALCULATE (\n    SUM ( F_Inventory[StockValue] ),\n    FILTER (\n        Inventory,\n        CALCULATE (\n            SUM ( F_Sales[Qty] ),\n            DATESINPERIOD (\n                M_Date[Date],\n                LASTDATE ( M_Date[Date] ),\n                -180, DAY\n            )\n        ) = 0\n            && F_Inventory[QtyOnHand] > 0\n            && F_Inventory[SnapshotDate]\n                = MAX ( F_Inventory[SnapshotDate] )\n    )\n)", "insight": "<strong>Write-off provision input.</strong> Dead stock value feeds the finance team\\'s provisions for inventory write-down under accounting standards. Report monthly to CFO.", "tags": ["CALCULATE", "SUM", "FILTER", "DATESINPERIOD", "Dead Stock", "Write-Off", "Provisions"]}, {"id": 721, "cat": "inventory", "sub": "Expiry & Freshness", "diff": "intermediate", "title": "Stock Expiring Within 30 Days", "q": "How much stock (units and value) will expire in the next 30 days?", "dax": "Stock Expiring 30D =\nCALCULATE (\n    SUM ( F_Inventory[QtyOnHand] ),\n    FILTER (\n        Inventory,\n        F_Inventory[ExpiryDate] >= TODAY ()\n            && F_Inventory[ExpiryDate] <= TODAY () + 30\n            && F_Inventory[SnapshotDate]\n                = MAX ( F_Inventory[SnapshotDate] )\n    )\n)", "insight": "<strong>Critical for FMCG, food, pharma, and beauty.</strong> Stock expiring within 30 days needs urgent action: price reduction, redistribution, or disposal. Integrate with [Avg Daily Sales 30D] to see if you can sell it in time.", "tags": ["CALCULATE", "SUM", "FILTER", "TODAY", "Expiry", "Freshness", "FMCG"]}, {"id": 722, "cat": "inventory", "sub": "Expiry & Freshness", "diff": "advanced", "title": "% of Stock at Risk of Expiry", "q": "What percentage of total stock volume is at risk of expiring within 30 days?", "dax": "Expiry Risk % =\nDIVIDE (\n    [Stock Expiring 30D],\n    [Stock on Hand]\n)", "insight": "<strong>Portfolio-level freshness indicator.</strong> Above 10% signals a supply or forecasting problem — you are ordering more than you can sell before expiry. Drive root-cause: is it forecast error, lead time, or supplier minimum order quantities?", "tags": ["DIVIDE", "Expiry", "Risk %", "Freshness", "FMCG", "Inventory"]}, {"id": 723, "cat": "inventory", "sub": "Shrinkage & Accuracy", "diff": "intermediate", "title": "Inventory Shrinkage %", "q": "What percentage of stock is lost to theft, damage, or admin error?", "dax": "Shrinkage % =\nDIVIDE (\n    SUM ( F_Inventory[ShrinkageQty] ),\n    SUM ( F_Inventory[OpeningQty] )\n)", "insight": "<strong>Retail industry average: 1.4% of stock value.</strong> Above 2% warrants investigation — split by location to find whether it is concentrated in specific stores, warehouses, or categories.", "tags": ["DIVIDE", "SUM", "Shrinkage", "Loss", "Retail", "Accuracy"]}, {"id": 724, "cat": "inventory", "sub": "Shrinkage & Accuracy", "diff": "intermediate", "title": "Stock Count Accuracy %", "q": "What percentage of physical stock counts match the system record?", "dax": "Stock Count Accuracy % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Inventory ),\n        ABS (\n            F_Inventory[QtyOnHand] - F_Inventory[PhysicalCount]\n        ) = 0\n    ),\n    COUNTROWS ( Inventory )\n)", "insight": "<strong>World-class benchmark: 99.5%+ accuracy.</strong> Below 95% means your system stock levels cannot be trusted for reordering, which cascades into stockouts and overstock simultaneously.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "ABS", "Stock Accuracy", "Count"]}, {"id": 801, "cat": "customerservice", "sub": "Ticket Volumes", "diff": "basic", "title": "Total Tickets Received", "q": "How many support tickets were raised in the selected period?", "dax": "Total Tickets =\nCALCULATE (\n    COUNTROWS ( Tickets ),\n    F_Tickets[CreatedDate] >= MIN ( M_Date[Date] )\n        && F_Tickets[CreatedDate] <= MAX ( M_Date[Date] )\n)", "insight": "<strong>Volume baseline.</strong> Track daily and weekly to identify demand spikes. Sudden volume surges often signal a product defect, outage, or a confusing process change — act on root cause, not just agent capacity.", "tags": ["CALCULATE", "COUNTROWS", "Tickets", "Volume"]}, {"id": 802, "cat": "customerservice", "sub": "Ticket Volumes", "diff": "basic", "title": "Tickets Resolved", "q": "How many tickets were resolved in the selected period?", "dax": "Tickets Resolved =\nCALCULATE (\n    COUNTROWS ( Tickets ),\n    F_Tickets[Status] = \"Resolved\"\n        || F_Tickets[Status] = \"Closed\",\n    F_Tickets[ResolvedDate] >= MIN ( M_Date[Date] ),\n    F_Tickets[ResolvedDate] <= MAX ( M_Date[Date] )\n)", "insight": "<strong>Output metric.</strong> Compare against [Total Tickets] — if resolved < received, your backlog is growing. Both \"Resolved\" and \"Closed\" statuses are valid completions depending on your workflow.", "tags": ["CALCULATE", "COUNTROWS", "Resolved", "Closed", "Tickets"]}, {"id": 803, "cat": "customerservice", "sub": "Ticket Volumes", "diff": "basic", "title": "Tickets Currently Open", "q": "How many tickets are still unresolved right now?", "dax": "Open Tickets =\nCALCULATE (\n    COUNTROWS ( Tickets ),\n    F_Tickets[Status] = \"Open\"\n        || F_Tickets[Status] = \"Escalated\"\n)", "insight": "<strong>Live backlog metric.</strong> Open + Escalated = total work in progress. Display in a KPI card with a target threshold — e.g. amber above 200, red above 500 open tickets.", "tags": ["CALCULATE", "COUNTROWS", "Open", "Backlog", "Tickets"]}, {"id": 804, "cat": "customerservice", "sub": "Ticket Volumes", "diff": "intermediate", "title": "Unresolvable / Closed Without Resolution", "q": "How many tickets were closed but never actually resolved?", "dax": "Unresolvable Tickets =\nCALCULATE (\n    COUNTROWS ( Tickets ),\n    F_Tickets[Status] = \"Unresolvable\"\n)", "insight": "<strong>Quality and product signal.</strong> High unresolvable counts reveal gaps in your product, policy, or agent knowledge base. Categorise by ContactReason to find systemic root causes.", "tags": ["CALCULATE", "COUNTROWS", "Unresolvable", "Quality", "Tickets"]}, {"id": 805, "cat": "customerservice", "sub": "Ticket Volumes", "diff": "intermediate", "title": "Ticket Resolution Rate %", "q": "What percentage of all tickets raised are being resolved?", "dax": "Resolution Rate % =\nDIVIDE (\n    [Tickets Resolved],\n    [Total Tickets]\n)", "insight": "<strong>Target 95%+.</strong> A falling resolution rate is an early warning of a capacity problem, a knowledge gap, or a wave of complex new issue types entering the queue.", "tags": ["DIVIDE", "Resolution Rate", "%", "Tickets", "Quality"]}, {"id": 806, "cat": "customerservice", "sub": "Ticket Volumes", "diff": "intermediate", "title": "Escalation Rate %", "q": "What percentage of tickets required escalation to a senior team?", "dax": "Escalation Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        F_Tickets[EscalationFlag] = TRUE ()\n    ),\n    [Total Tickets]\n)", "insight": "<strong>Agent capability indicator.</strong> High escalation rates signal training gaps, under-empowered agents, or complex product issues. Benchmark: below 10%. Segment by team to find skill gaps.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Escalation", "Rate", "Tickets"]}, {"id": 807, "cat": "customerservice", "sub": "Ticket Volumes", "diff": "intermediate", "title": "Backlog Growth Rate", "q": "Is the open ticket backlog growing or shrinking day by day?", "dax": "Backlog Growth =\n[Total Tickets] - [Tickets Resolved]", "insight": "<strong>Operational sustainability check.</strong> Positive = backlog growing (you\\'re receiving more than you\\'re resolving). Negative = catching up. Zero = stable. Any sustained positive trend needs a capacity response.", "tags": ["Backlog", "Growth", "Tickets", "Capacity"]}, {"id": 808, "cat": "customerservice", "sub": "Ticket Volumes", "diff": "intermediate", "title": "Tickets by Channel Mix %", "q": "What percentage of tickets come via each channel (email, phone, chat)?", "dax": "Email Channel % =\nDIVIDE (\n    CALCULATE (\n        [Total Tickets],\n        F_Tickets[Channel] = \"Email\"\n    ),\n    [Total Tickets]\n)", "insight": "<strong>Channel strategy metric.</strong> Shift from phone/email to self-service and chat typically reduces cost per contact by 60–80%. Track this monthly to measure digital deflection progress.", "tags": ["DIVIDE", "CALCULATE", "Channel", "Mix", "Email", "Phone", "Chat"]}, {"id": 809, "cat": "customerservice", "sub": "Turnaround Time", "diff": "intermediate", "title": "Average Resolution Time (Hours)", "q": "How long does it take on average to resolve a ticket end-to-end?", "dax": "Avg Resolution Time =\nAVERAGEX (\n    FILTER (\n        Tickets,\n        NOT ISBLANK ( F_Tickets[ResolvedDate] )\n    ),\n    DATEDIFF (\n        F_Tickets[CreatedDate],\n        F_Tickets[ResolvedDate],\n        HOUR\n    )\n)", "insight": "<strong>End-to-end speed benchmark.</strong> Segment by Priority — P1 average should be measured in hours, P3 in days. A single avg across all priorities is misleading without this split.", "tags": ["AVERAGEX", "FILTER", "DATEDIFF", "Resolution Time", "Hours", "SLA"]}, {"id": 810, "cat": "customerservice", "sub": "Turnaround Time", "diff": "intermediate", "title": "Average Handle Time — AHT (Minutes)", "q": "How long does each agent interaction take during the ticket?", "dax": "Avg Handle Time =\nAVERAGEX (\n    FILTER (\n        Tickets,\n        NOT ISBLANK ( F_Tickets[HandleTimeMinutes] )\n    ),\n    F_Tickets[HandleTimeMinutes]\n)", "insight": "<strong>AHT alone is dangerous.</strong> Low AHT with low CSAT = rushing customers. Always review alongside CSAT. Target varies by complexity: chat 6–10 mins, phone 5–8 mins, complex 20–30 mins.", "tags": ["AVERAGEX", "FILTER", "AHT", "Handle Time", "Minutes"]}, {"id": 811, "cat": "customerservice", "sub": "Turnaround Time", "diff": "intermediate", "title": "SLA Compliance Rate %", "q": "What percentage of tickets were resolved within the agreed SLA window?", "dax": "SLA Compliance % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        FILTER (\n            Tickets,\n            F_Tickets[ResolutionTime] <= F_Tickets[SLATarget]\n                && NOT ISBLANK ( F_Tickets[ResolvedDate] )\n        )\n    ),\n    [Tickets Resolved]\n)", "insight": "<strong>Segment by Priority tier.</strong> P1 SLA breaches are contractual and often carry financial penalties. Aggregate SLA compliance masks the fact that P1s may be consistently breached while P3s pull the overall number up.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "FILTER", "SLA", "Compliance"]}, {"id": 812, "cat": "customerservice", "sub": "Turnaround Time", "diff": "advanced", "title": "SLA Breach Count by Priority", "q": "How many SLA breaches occurred at each priority level?", "dax": "SLA Breaches =\nCALCULATE (\n    COUNTROWS ( Tickets ),\n    FILTER (\n        Tickets,\n        F_Tickets[ResolutionTime] > F_Tickets[SLATarget]\n            && NOT ISBLANK ( F_Tickets[ResolvedDate] )\n    )\n)", "insight": "<strong>Use in a matrix</strong> with Priority as rows. P1 breaches = crisis; P2 breaches = capacity issue; P3 breaches = workflow optimisation opportunity. Each needs a different response.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "SLA", "Breach", "Priority"]}, {"id": 813, "cat": "customerservice", "sub": "Turnaround Time", "diff": "advanced", "title": "Tickets Breaching SLA Right Now (Live)", "q": "How many currently open tickets have already exceeded their SLA target?", "dax": "Live SLA Breaches =\nCALCULATE (\n    COUNTROWS ( Tickets ),\n    FILTER (\n        Tickets,\n        F_Tickets[Status] = \"Open\"\n            && DATEDIFF (\n                F_Tickets[CreatedDate],\n                NOW (),\n                HOUR\n            ) > F_Tickets[SLATarget]\n    )\n)", "insight": "<strong>Operational dashboard KPI.</strong> This measure updates in real-time (uses NOW()). Display on a team leader\\'s live screen — any non-zero value should trigger immediate escalation.", "tags": ["CALCULATE", "COUNTROWS", "FILTER", "NOW", "DATEDIFF", "Live", "SLA", "Breach"]}, {"id": 814, "cat": "customerservice", "sub": "Satisfaction & Quality", "diff": "basic", "title": "Average CSAT Score", "q": "What is the average customer satisfaction rating across all rated tickets?", "dax": "Avg CSAT Score =\nAVERAGEX (\n    FILTER (\n        Tickets,\n        NOT ISBLANK ( F_Tickets[CSATScore] )\n    ),\n    F_Tickets[CSATScore]\n)", "insight": "<strong>Always filter out blanks.</strong> Non-responses are not a score of zero — including them decimates your average. Target 4.2+ on a 5-point scale. Below 3.5 signals systemic service failure.", "tags": ["AVERAGEX", "FILTER", "ISBLANK", "CSAT", "Satisfaction"]}, {"id": 815, "cat": "customerservice", "sub": "Satisfaction & Quality", "diff": "intermediate", "title": "CSAT Response Rate %", "q": "What percentage of customers completed the satisfaction survey?", "dax": "CSAT Response Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        NOT ISBLANK ( F_Tickets[CSATScore] )\n    ),\n    [Tickets Resolved]\n)", "insight": "<strong>Survey validity check.</strong> A 10% response rate means 90% of customers are not represented — results may be skewed toward extreme (very happy or very angry) respondents. Target 20%+ for statistical reliability.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "CSAT", "Response Rate", "Survey"]}, {"id": 816, "cat": "customerservice", "sub": "Satisfaction & Quality", "diff": "intermediate", "title": "First Contact Resolution Rate % (FCR)", "q": "What percentage of issues are fully resolved in a single interaction?", "dax": "FCR Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        F_Tickets[FCR] = TRUE ()\n    ),\n    [Total Tickets]\n)", "insight": "<strong>The single most powerful CS KPI.</strong> Each 1% FCR improvement reduces total contact volume by ~1%. Benchmark: 70–75%. FCR is the best proxy for customer effort — if it\\'s resolved first time, no effort was wasted.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "FCR", "First Contact", "Resolution"]}, {"id": 817, "cat": "customerservice", "sub": "Satisfaction & Quality", "diff": "intermediate", "title": "% Tickets Scoring 5-Star CSAT", "q": "What percentage of rated tickets received the highest satisfaction score?", "dax": "Top CSAT % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        F_Tickets[CSATScore] = 5\n    ),\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        NOT ISBLANK ( F_Tickets[CSATScore] )\n    )\n)", "insight": "<strong>Promoter rate proxy.</strong> Companies with 60%+ 5-star ratings have strong customer advocacy. Track per agent to identify your service champions and replicate their approach.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "5-Star", "CSAT", "Top Score"]}, {"id": 818, "cat": "customerservice", "sub": "Satisfaction & Quality", "diff": "intermediate", "title": "% Tickets Scoring 1–2 Star CSAT (Detractors)", "q": "What percentage of rated tickets received the lowest satisfaction scores?", "dax": "Detractor CSAT % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        F_Tickets[CSATScore] <= 2\n    ),\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        NOT ISBLANK ( F_Tickets[CSATScore] )\n    )\n)", "insight": "<strong>Complaint risk indicator.</strong> 1–2 star ratings are your most likely complainants and churners. Review these tickets immediately — they carry detailed feedback about what went wrong.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Detractor", "1-2 Star", "CSAT", "Risk"]}, {"id": 819, "cat": "customerservice", "sub": "Agent Performance", "diff": "intermediate", "title": "Tickets Resolved per Agent", "q": "How many tickets does each agent resolve in the period?", "dax": "Tickets per Agent =\nDIVIDE (\n    [Tickets Resolved],\n    DISTINCTCOUNT ( F_Tickets[AgentID] )\n)", "insight": "<strong>Productivity baseline.</strong> Benchmark varies by channel and complexity: phone agents 30–50/day for simple queries, 5–15/day for complex technical issues. Use per-agent in a ranking matrix.", "tags": ["DIVIDE", "DISTINCTCOUNT", "Tickets", "Agent", "Productivity"]}, {"id": 820, "cat": "customerservice", "sub": "Agent Performance", "diff": "intermediate", "title": "Agent CSAT Score (Average)", "q": "Which agents receive the highest and lowest customer satisfaction scores?", "dax": "Agent Avg CSAT =\nAVERAGEX (\n    FILTER (\n        Tickets,\n        NOT ISBLANK ( F_Tickets[CSATScore] )\n            && F_Tickets[AgentID]\n                = MAX ( F_Tickets[AgentID] )\n    ),\n    F_Tickets[CSATScore]\n)", "insight": "<strong>Use in an agent leaderboard matrix.</strong> Agents consistently below team average need coaching. Agents consistently above are your training resource — observe and replicate their approach.", "tags": ["AVERAGEX", "FILTER", "Agent", "CSAT", "Performance", "Leaderboard"]}, {"id": 821, "cat": "customerservice", "sub": "Agent Performance", "diff": "intermediate", "title": "Agent FCR Rate %", "q": "What percentage of each agent\\", "dax": "Agent FCR % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        F_Tickets[FCR] = TRUE ()\n    ),\n    CALCULATE (\n        COUNTROWS ( Tickets )\n    )\n)", "insight": "<strong>Use in a matrix with AgentName as rows.</strong> Agents with low FCR may lack product knowledge, authority to resolve, or the right tools. Pair with AHT — high AHT + high FCR = thorough but slow; the ideal is high FCR + average AHT.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "FCR", "Agent", "Performance"]}, {"id": 822, "cat": "customerservice", "sub": "Agent Performance", "diff": "advanced", "title": "Top 5 Agents by CSAT (Ranking)", "q": "Who are the top 5 performing agents by customer satisfaction score?", "dax": "Agent CSAT Rank =\nRANKX (\n    ALL ( M_Agents[AgentName] ),\n    [Agent Avg CSAT],,\n    DESC, DENSE\n)", "insight": "<strong>Use with a TOPN filter</strong> — add a visual-level filter where [Agent CSAT Rank] <= 5 to show your top performers. Recognise them publicly to reinforce service culture.", "tags": ["RANKX", "ALL", "Agent", "CSAT", "Rank", "Top 5", "Leaderboard"]}, {"id": 823, "cat": "customerservice", "sub": "Workload & Capacity", "diff": "intermediate", "title": "Daily Ticket Volume (Avg)", "q": "How many tickets arrive per day on average in the selected period?", "dax": "Avg Daily Tickets =\nDIVIDE (\n    [Total Tickets],\n    COUNTROWS ( M_Date )\n)", "insight": "<strong>Staffing model input.</strong> Avg daily volume ÷ tickets-per-agent-per-day = minimum agent headcount needed. Account for shrinkage (breaks, training, absence) by dividing by 0.75–0.85.", "tags": ["DIVIDE", "COUNTROWS", "Daily Volume", "Tickets", "Capacity", "Staffing"]}, {"id": 824, "cat": "customerservice", "sub": "Workload & Capacity", "diff": "advanced", "title": "Reopened Ticket Rate %", "q": "What percentage of resolved tickets were reopened by the customer?", "dax": "Reopen Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Tickets ),\n        F_Tickets[ReopenFlag] = TRUE ()\n    ),\n    [Tickets Resolved]\n)", "insight": "<strong>Resolution quality metric.</strong> Reopened tickets are failed resolutions — they double the cost of the original interaction. Above 5% indicates agents are closing tickets prematurely or solutions are not lasting.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Reopen", "Quality", "Resolution"]}, {"id": 1101, "cat": "dynamic", "sub": "Period Switcher", "diff": "intermediate", "title": "Actual — Dynamic Period", "q": "Show actual revenue for whichever period (MTD/QTD/YTD/Full) the user selects?", "dax": "Actual Dynamic =\nVAR _sel = SELECTEDVALUE ( M_PeriodSel[Period], \"Full Period\" )\nRETURN\n    SWITCH (\n        _sel,\n        \"MTD\",         [Revenue MTD],\n        \"QTD\",         [Revenue QTD],\n        \"YTD\",         [Revenue YTD],\n        \"Full Period\",  [Total Sales],\n        [Total Sales]\n    )", "insight": "<strong>Foundation of the dynamic engine.</strong> Place a PeriodSel slicer (MTD/QTD/YTD/Full Period) on the page — this measure automatically recalculates for every visual on the canvas.", "tags": ["SELECTEDVALUE", "SWITCH", "VAR", "MTD", "QTD", "YTD", "Dynamic", "Period"]}, {"id": 1102, "cat": "dynamic", "sub": "Period Switcher", "diff": "intermediate", "title": "Period Label (Dynamic Title)", "q": "Show a text label that updates to describe the selected period?", "dax": "Period Label =\nVAR _sel = SELECTEDVALUE ( M_PeriodSel[Period], \"Full Period\" )\nRETURN\n    SWITCH (\n        _sel,\n        \"MTD\",         \"Month-to-Date\",\n        \"QTD\",         \"Quarter-to-Date\",\n        \"YTD\",         \"Year-to-Date\",\n        \"Full Period\",  \"Full Period\",\n        \"Full Period\"\n    )", "insight": "<strong>Use in card visual titles.</strong> With dynamic titles enabled in Power BI (Format → Title → fx), bind this measure to the title field — your chart titles update automatically with the slicer.", "tags": ["SELECTEDVALUE", "SWITCH", "VAR", "Label", "Title", "Dynamic"]}, {"id": 1103, "cat": "dynamic", "sub": "Reference Switcher", "diff": "intermediate", "title": "Reference Value (LY / Target / Forecast)", "q": "Show Last Year, Target, or Forecast value based on what the user selects?", "dax": "Reference Value =\nVAR _ref = SELECTEDVALUE ( M_Comparison[Reference], \"Last Year\" )\nVAR _per = SELECTEDVALUE ( M_PeriodSel[Period], \"Full Period\" )\nVAR _ly =\n    SWITCH (\n        _per,\n        \"MTD\", CALCULATE ( [Revenue MTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n        \"QTD\", CALCULATE ( [Revenue QTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n        \"YTD\", CALCULATE ( [Revenue YTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n        CALCULATE ( [Total Sales], SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nVAR _tgt = SUM ( F_Targets[SalesTarget] )\nVAR _fct = SUM ( F_Forecast[ForecastAmount] )\nRETURN\n    SWITCH (\n        _ref,\n        \"Last Year\", _ly,\n        \"Target\",    _tgt,\n        \"Forecast\",  _fct,\n        _ly\n    )", "insight": "<strong>The engine core.</strong> This single measure replaces 6 separate measures (LY MTD, LY QTD, LY YTD, Target MTD…). Combine both slicers and every comparison scenario is covered automatically.", "tags": ["SELECTEDVALUE", "SWITCH", "VAR", "SAMEPERIODLASTYEAR", "CALCULATE", "Reference", "Dynamic"]}, {"id": 1104, "cat": "dynamic", "sub": "Reference Switcher", "diff": "intermediate", "title": "Reference Label (Dynamic)", "q": "Show a text label describing what the reference is — \"vs Last Year\", \"vs Target\" etc?", "dax": "Reference Label =\nVAR _ref = SELECTEDVALUE ( M_Comparison[Reference], \"Last Year\" )\nVAR _per = SELECTEDVALUE ( M_PeriodSel[Period], \"Full Period\" )\nRETURN\n    \"vs \" & _ref & \" (\" & _per & \")\"", "insight": "<strong>Auto-updating chart subtitle.</strong> Displays as \"vs Last Year (YTD)\" or \"vs Target (MTD)\" — use in card subtitles or as a text visual so users always know what they are comparing.", "tags": ["SELECTEDVALUE", "VAR", "Label", "Subtitle", "Dynamic", "Reference"]}, {"id": 1105, "cat": "dynamic", "sub": "Variance", "diff": "intermediate", "title": "Variance — Absolute (£)", "q": "What is the absolute difference between actual and the selected reference?", "dax": "Variance Absolute =\n[Actual Dynamic] - [Reference Value]", "insight": "<strong>Always show absolute alongside %.</strong> A 5% variance on £100K is £5K — very different from 5% on £10M. The £ number makes the business impact tangible for non-finance audiences.", "tags": ["Variance", "Absolute", "Dynamic", "Reference"]}, {"id": 1106, "cat": "dynamic", "sub": "Variance", "diff": "intermediate", "title": "Variance % (Growth / Gap)", "q": "What is the percentage difference between actual and the selected reference?", "dax": "Variance % =\nDIVIDE (\n    [Variance Absolute],\n    [Reference Value]\n)", "insight": "<strong>The headline percentage.</strong> Positive = actual is ahead of reference, negative = behind. Format as percentage with 1 decimal. Use alongside [Variance Absolute] in a dual KPI card.", "tags": ["DIVIDE", "Variance", "%", "Growth", "Dynamic", "Reference"]}, {"id": 1107, "cat": "dynamic", "sub": "Variance", "diff": "intermediate", "title": "Variance Direction Label", "q": "Show a directional label — Ahead, Behind, or On Track?", "dax": "Variance Direction =\nVAR _pct = [Variance %]\nRETURN\n    SWITCH (\n        TRUE (),\n        _pct >=  0.05, \"▲ Ahead\",\n        _pct <= -0.05, \"▼ Behind\",\n        \"● On Track\"\n    )", "insight": "<strong>Instant visual status.</strong> Use in a table or matrix — the arrow symbols show direction without needing conditional formatting. Adjust the 5% threshold to match your business tolerance.", "tags": ["VAR", "SWITCH", "TRUE", "Label", "Direction", "Variance"]}, {"id": 1108, "cat": "dynamic", "sub": "Variance", "diff": "intermediate", "title": "RAG Status (Red Amber Green)", "q": "Classify performance as Green, Amber, or Red based on variance %?", "dax": "RAG Status =\nVAR _pct = [Variance %]\nRETURN\n    SWITCH (\n        TRUE (),\n        _pct >= 0,     \"🟢 Green\",\n        _pct >= -0.05, \"🟡 Amber\",\n        \"🔴 Red\"\n    )", "insight": "<strong>Board-ready status indicator.</strong> Adjust thresholds: >= 0% = Green, -5% to 0% = Amber, below -5% = Red. Use conditional formatting on a matrix for colour-coded scorecards.", "tags": ["VAR", "SWITCH", "TRUE", "RAG", "Status", "Green", "Amber", "Red"]}, {"id": 1109, "cat": "dynamic", "sub": "Variance", "diff": "advanced", "title": "Remaining Gap to Reference", "q": "How much more actual revenue is needed to reach the reference value?", "dax": "Remaining Gap =\nVAR _gap = [Reference Value] - [Actual Dynamic]\nRETURN\n    MAX ( _gap, 0 )", "insight": "<strong>Actionable target measure.</strong> \"£42,000 still needed to hit target\" is more motivating than \"-8% vs target\". MAX(gap, 0) prevents showing negative gaps (already exceeded) as a remaining requirement.", "tags": ["VAR", "MAX", "Gap", "Remaining", "Target", "Dynamic"]}, {"id": 1110, "cat": "dynamic", "sub": "Always-On Comparisons", "diff": "intermediate", "title": "Growth % vs Last Year (Always On)", "q": "What is the YoY growth rate — always shown regardless of reference slicer?", "dax": "Growth % vs LY =\nVAR _actual = [Actual Dynamic]\nVAR _ly =\n    SWITCH (\n        SELECTEDVALUE ( M_PeriodSel[Period], \"Full Period\" ),\n        \"MTD\", CALCULATE ( [Revenue MTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n        \"QTD\", CALCULATE ( [Revenue QTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n        \"YTD\", CALCULATE ( [Revenue YTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n        CALCULATE ( [Total Sales], SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n    )\nRETURN\n    DIVIDE ( _actual - _ly, _ly )", "insight": "<strong>Always visible regardless of reference slicer.</strong> Use alongside [Growth % vs Target] in a comparison table — both always show so users can see all perspectives simultaneously.", "tags": ["VAR", "SWITCH", "SELECTEDVALUE", "SAMEPERIODLASTYEAR", "CALCULATE", "YoY", "Growth"]}, {"id": 1111, "cat": "dynamic", "sub": "Always-On Comparisons", "diff": "intermediate", "title": "Growth % vs Target (Always On)", "q": "What is the achievement % vs target — always shown regardless of reference slicer?", "dax": "Achievement % vs Target =\nVAR _actual = [Actual Dynamic]\nVAR _target = SUM ( F_Targets[SalesTarget] )\nRETURN\n    DIVIDE ( _actual - _target, _target )", "insight": "<strong>Permanent target comparison.</strong> Positive = above target, negative = below. Always displayed so users see both YoY growth and target achievement simultaneously in the same visual.", "tags": ["VAR", "DIVIDE", "SUM", "Target", "Achievement", "Always-On"]}, {"id": 1112, "cat": "dynamic", "sub": "Always-On Comparisons", "diff": "intermediate", "title": "Growth % vs Forecast (Always On)", "q": "How is actual tracking vs the forecast — always shown regardless of reference slicer?", "dax": "Variance % vs Forecast =\nVAR _actual = [Actual Dynamic]\nVAR _forecast = SUM ( F_Forecast[ForecastAmount] )\nRETURN\n    DIVIDE ( _actual - _forecast, _forecast )", "insight": "<strong>Forecast accuracy metric.</strong> Positive = actual ahead of forecast. Negative = underperforming forecast. Track consistently — an always-optimistic forecast that is never hit loses credibility.", "tags": ["VAR", "DIVIDE", "SUM", "Forecast", "Variance", "Always-On"]}, {"id": 1113, "cat": "dynamic", "sub": "Multi-KPI Comparison", "diff": "advanced", "title": "Prior Year Value — Period Matched", "q": "What was the exact same period value last year — always, for any period selection?", "dax": "Prior Year Value =\nSWITCH (\n    SELECTEDVALUE ( M_PeriodSel[Period], \"Full Period\" ),\n    \"MTD\", CALCULATE ( [Revenue MTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n    \"QTD\", CALCULATE ( [Revenue QTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n    \"YTD\", CALCULATE ( [Revenue YTD], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n    CALCULATE ( [Total Sales], SAMEPERIODLASTYEAR ( M_Date[Date] ) )\n)", "insight": "<strong>Use as a constant reference line in charts.</strong> Plot [Actual Dynamic] as bars and [Prior Year Value] as a line — this is the classic \"actual vs prior year\" waterfall/combo chart.", "tags": ["SWITCH", "SELECTEDVALUE", "CALCULATE", "SAMEPERIODLASTYEAR", "Prior Year", "Period"]}, {"id": 1114, "cat": "dynamic", "sub": "Multi-KPI Comparison", "diff": "advanced", "title": "Forecast Value — Period Matched", "q": "What is the forecast amount for the selected period?", "dax": "Forecast Value =\nSWITCH (\n    SELECTEDVALUE ( M_PeriodSel[Period], \"Full Period\" ),\n    \"MTD\", CALCULATE ( SUM ( F_Forecast[ForecastAmount] ), DATESMTD ( M_Date[Date] ) ),\n    \"QTD\", CALCULATE ( SUM ( F_Forecast[ForecastAmount] ), DATESQTD ( M_Date[Date] ) ),\n    \"YTD\", CALCULATE ( SUM ( F_Forecast[ForecastAmount] ), DATESYTD ( M_Date[Date] ) ),\n    SUM ( F_Forecast[ForecastAmount] )\n)", "insight": "<strong>Period-matched forecast.</strong> Ensures the forecast is sliced to the same window as actuals — comparing YTD actuals against full-year forecast would be misleading.", "tags": ["SWITCH", "SELECTEDVALUE", "CALCULATE", "DATESMTD", "DATESQTD", "DATESYTD", "Forecast", "Period"]}, {"id": 1115, "cat": "dynamic", "sub": "Multi-KPI Comparison", "diff": "advanced", "title": "Three-Way Comparison Summary", "q": "Show actual vs target vs last year all in one measure set for a matrix visual?", "dax": "-- Use these three measures as Values in a Matrix visual:\n-- Rows: Time period (Month/Quarter)\n-- Values: [Actual Dynamic], [Prior Year Value], [Forecast Value]\n-- Then add these as additional columns:\n-- [Growth % vs LY], [Achievement % vs Target], [Variance % vs Forecast]\n\n-- Shorthand helper — picks the right label for column headers:\nComparison Summary Label =\nVAR _act = [Actual Dynamic]\nVAR _ly  = [Prior Year Value]\nVAR _tgt = SUM ( F_Targets[SalesTarget] )\nVAR _fct = [Forecast Value]\nRETURN\n    \"Actual: \" & FORMAT ( _act, \"#,##0\" )\n        & \" | LY: \" & FORMAT ( _ly, \"#,##0\" )\n        & \" | Target: \" & FORMAT ( _tgt, \"#,##0\" )", "insight": "<strong>Board summary card formula.</strong> Use FORMAT() to build a text KPI card showing all three reference points in one line. Combine with [RAG Status] for a single-glance executive summary.", "tags": ["VAR", "FORMAT", "SWITCH", "Three-Way", "Comparison", "Summary", "Matrix"]}, {"id": 1116, "cat": "dynamic", "sub": "Multi-KPI Comparison", "diff": "advanced", "title": "Best Reference Selector — Auto Pick", "q": "Automatically highlight which reference (LY or Target) is closer to actual?", "dax": "Closer Reference =\nVAR _ly  = ABS ( [Actual Dynamic] - [Prior Year Value] )\nVAR _tgt = ABS ( [Actual Dynamic] - SUM ( F_Targets[SalesTarget] ) )\nRETURN\n    IF (\n        _ly < _tgt,\n        \"Closer to Last Year\",\n        \"Closer to Target\"\n    )", "insight": "<strong>Diagnostic insight measure.</strong> Shows whether performance is more influenced by historical momentum (LY) or target-setting. Use in a tooltip or info panel on the dashboard.", "tags": ["VAR", "ABS", "IF", "Auto", "Reference", "Selector"]}, {"id": 1117, "cat": "dynamic", "sub": "Multi-KPI Comparison", "diff": "advanced", "title": "Waterfall Contribution — Actual vs LY Bridge", "q": "How much of the YoY variance is from volume change vs price/mix?", "dax": "Volume Effect =\nVAR _lyQty   = CALCULATE ( SUM ( F_Sales[Qty] ), SAMEPERIODLASTYEAR ( M_Date[Date] ) )\nVAR _currQty = SUM ( F_Sales[Qty] )\nVAR _lyPrice = DIVIDE (\n    CALCULATE ( [Total Sales], SAMEPERIODLASTYEAR ( M_Date[Date] ) ),\n    _lyQty\n)\nRETURN\n    ( _currQty - _lyQty ) * _lyPrice", "insight": "<strong>Bridge chart input.</strong> Volume Effect + Price/Mix Effect = Total YoY Variance. Use three measures ([Volume Effect], [Price Effect], [Total YoY Variance]) as a waterfall chart to decompose the revenue change.", "tags": ["VAR", "CALCULATE", "SAMEPERIODLASTYEAR", "Waterfall", "Bridge", "Volume", "Price"]}, {"id": 1118, "cat": "dynamic", "sub": "Multi-KPI Comparison", "diff": "advanced", "title": "[KPI] Indexed Performance (Base=100)", "q": "Show all KPIs indexed to 100 at a base period for trend comparison?", "dax": "[KPI] Indexed Performance =\nVAR _baseValue =\n    CALCULATE (\n        [Total Sales],\n        FILTER (\n            ALL ( M_Date ),\n            M_Date[Year] = MIN ( M_Date[Year] )\n                && M_Date[Month] = 1\n        )\n    )\nRETURN\n    DIVIDE ( [Total Sales], _baseValue ) * 100", "insight": "<strong>Trend normalisation.</strong> Indexing to 100 lets you compare revenue, headcount, costs, and any other KPI on the same chart regardless of their actual scale — the most powerful executive trend visual.", "tags": ["VAR", "CALCULATE", "FILTER", "ALL", "Index", "100", "Trend", "Normalise"]}, {"id": 2001, "cat": "marketing", "sub": "Campaign Performance", "diff": "basic", "title": "Total Marketing Spend", "q": "What is the total spend across all marketing campaigns in the period?", "dax": "Total Marketing Spend =\nSUM ( F_Campaigns[Spend] )", "insight": "<strong>Always your baseline.</strong> Every marketing efficiency ratio divides by this — Total Spend, CPA, ROAS, ROI all depend on an accurate spend figure. Include agency fees, ad spend, and production costs.", "tags": ["SUM", "Marketing", "Spend", "Campaign"]}, {"id": 2002, "cat": "marketing", "sub": "Campaign Performance", "diff": "intermediate", "title": "Return on Ad Spend (ROAS)", "q": "How much revenue is generated for every £1 of ad spend?", "dax": "ROAS =\nDIVIDE (\n    [Total Sales],\n    [Total Marketing Spend]\n)", "insight": "<strong>ROAS > 4× is generally strong</strong> for e-commerce; B2B SaaS targets 3–5×. Below 1× means you are spending more than you earn — every pound of ad spend loses money.", "tags": ["DIVIDE", "ROAS", "Revenue", "Marketing", "Efficiency"]}, {"id": 2003, "cat": "marketing", "sub": "Campaign Performance", "diff": "intermediate", "title": "Marketing ROI %", "q": "What is the percentage return on marketing investment after deducting spend?", "dax": "Marketing ROI % =\nDIVIDE (\n    [Total Sales] - [Total Marketing Spend],\n    [Total Marketing Spend]\n)", "insight": "<strong>ROI vs ROAS:</strong> ROAS is revenue ÷ spend; ROI subtracts the spend first. A ROAS of 4× is a 300% ROI. ROI is the fairer metric when comparing marketing to other investment options.", "tags": ["DIVIDE", "ROI", "Marketing", "Revenue", "Profitability"]}, {"id": 2004, "cat": "marketing", "sub": "Campaign Performance", "diff": "intermediate", "title": "Cost Per Acquisition (CPA)", "q": "How much does it cost to acquire one paying customer through marketing?", "dax": "CPA =\nDIVIDE (\n    [Total Marketing Spend],\n    [Active Customers]\n)", "insight": "<strong>Compare CPA against Customer LTV.</strong> If CPA > LTV, the business loses money on every customer acquired. A healthy ratio is LTV:CPA of at least 3:1.", "tags": ["DIVIDE", "CPA", "Acquisition", "Cost", "Marketing"]}, {"id": 2005, "cat": "marketing", "sub": "Campaign Performance", "diff": "advanced", "title": "Campaign ROI by Campaign", "q": "Which individual campaigns are generating a positive return?", "dax": "Campaign ROI % =\nDIVIDE (\n    CALCULATE ( SUM ( F_Campaigns[Sale] ) )\n        - CALCULATE ( SUM ( F_Campaigns[Spend] ) ),\n    CALCULATE ( SUM ( F_Campaigns[Spend] ) )\n)", "insight": "<strong>Use in a matrix with Campaign as rows.</strong> Sort descending by ROI to instantly identify your best and worst performing campaigns. Kill the negative ROI campaigns first.", "tags": ["DIVIDE", "CALCULATE", "Campaign", "ROI", "Performance"]}, {"id": 2006, "cat": "marketing", "sub": "Lead Generation", "diff": "basic", "title": "Total Leads Generated", "q": "How many marketing leads were generated in the selected period?", "dax": "Total Leads =\nCOUNTROWS (\n    FILTER (\n        Leads,\n        F_Leads[LeadDate] >= MIN ( M_Date[Date] )\n            && F_Leads[LeadDate] <= MAX ( M_Date[Date] )\n    )\n)", "insight": "<strong>Volume baseline for the funnel.</strong> Always segment by source (paid, organic, referral, direct) — overall lead volume is meaningless without understanding where leads come from.", "tags": ["COUNTROWS", "FILTER", "Leads", "Volume", "Marketing"]}, {"id": 2007, "cat": "marketing", "sub": "Lead Generation", "diff": "intermediate", "title": "Lead Conversion Rate %", "q": "What percentage of marketing leads convert to customers?", "dax": "Lead Conversion Rate % =\nDIVIDE (\n    CALCULATE (\n        COUNTROWS ( Leads ),\n        F_Leads[Status] = \"Converted\"\n    ),\n    [Total Leads]\n)", "insight": "<strong>Benchmark: 2–5% for B2B, 1–3% for e-commerce.</strong> Low conversion with high lead volume = top-of-funnel is working but qualification or sales handoff is broken. High conversion with low volume = bottom-of-funnel is strong, top needs work.", "tags": ["DIVIDE", "CALCULATE", "COUNTROWS", "Lead", "Conversion", "Funnel"]}, {"id": 2008, "cat": "marketing", "sub": "Lead Generation", "diff": "intermediate", "title": "Cost Per Lead (CPL)", "q": "How much does each marketing lead cost to generate?", "dax": "Cost Per Lead =\nDIVIDE (\n    [Total Marketing Spend],\n    [Total Leads]\n)", "insight": "<strong>Track CPL by channel.</strong> Paid search CPL is often 3–5× higher than organic or referral. Knowing CPL by channel lets you reallocate budget toward the most efficient sources.", "tags": ["DIVIDE", "CPL", "Cost", "Lead", "Marketing"]}, {"id": 2009, "cat": "marketing", "sub": "Lead Generation", "diff": "intermediate", "title": "Marketing Qualified Leads (MQLs)", "q": "How many leads met the criteria to be passed to the sales team?", "dax": "MQLs =\nCALCULATE (\n    COUNTROWS ( Leads ),\n    F_Leads[Stage] = \"MQL\"\n)", "insight": "<strong>MQL is the marketing-to-sales handoff point.</strong> Track MQL volume alongside CPA. If MQLs are high but conversion is low, the MQL definition is too loose — quality not quantity.", "tags": ["CALCULATE", "COUNTROWS", "MQL", "Lead", "Funnel"]}, {"id": 2010, "cat": "marketing", "sub": "Lead Generation", "diff": "intermediate", "title": "Pipeline Created by Marketing (£)", "q": "What is the total value of sales opportunities generated by marketing campaigns?", "dax": "Marketing Pipeline Created =\nCALCULATE (\n    SUM ( F_Opportunities[PipelineValue] ),\n    F_Opportunities[Source] = \"Marketing\"\n)", "insight": "<strong>The ultimate marketing accountability metric.</strong> Links marketing spend directly to revenue pipeline. Divide by [Total Marketing Spend] to get Pipeline ROI — every £1 of spend creates £X of pipeline.", "tags": ["CALCULATE", "SUM", "Pipeline", "Marketing", "Revenue"]}, {"id": 2011, "cat": "marketing", "sub": "Digital Performance", "diff": "basic", "title": "Click-Through Rate % (CTR)", "q": "What percentage of people who saw the ad clicked on it?", "dax": "CTR % =\nDIVIDE (\n    SUM ( F_DigitalAds[Clicks] ),\n    SUM ( F_DigitalAds[Impressions] )\n)", "insight": "<strong>Benchmarks: Google Search 3–5%, Display 0.1%, Social 1–3%.</strong> Low CTR = your ad creative or targeting is off. High CTR with low conversion = landing page is the problem.", "tags": ["DIVIDE", "SUM", "CTR", "Digital", "Clicks", "Impressions"]}, {"id": 2012, "cat": "marketing", "sub": "Digital Performance", "diff": "basic", "title": "Cost Per Click (CPC)", "q": "How much does each click on a paid ad cost?", "dax": "CPC =\nDIVIDE (\n    SUM ( F_DigitalAds[Spend] ),\n    SUM ( F_DigitalAds[Clicks] )\n)", "insight": "<strong>CPC varies wildly by channel and keyword.</strong> Google branded keywords: £0.50–£2. Competitive B2B keywords: £5–£50+. Track CPC trends over time — rising CPC may signal increased competition in your space.", "tags": ["DIVIDE", "SUM", "CPC", "Digital", "Paid", "Cost"]}, {"id": 2013, "cat": "marketing", "sub": "Digital Performance", "diff": "intermediate", "title": "Cost Per Thousand Impressions (CPM)", "q": "What is the cost to reach 1,000 people with an ad impression?", "dax": "CPM =\nDIVIDE (\n    SUM ( F_DigitalAds[Spend] ),\n    SUM ( F_DigitalAds[Impressions] )\n) * 1000", "insight": "<strong>CPM is used to compare brand awareness campaigns.</strong> Social CPM: £5–£15. Programmatic display: £1–£5. Rising CPM signals increasing competition for ad inventory in your target audience.", "tags": ["DIVIDE", "SUM", "CPM", "Impressions", "Digital", "Brand"]}, {"id": 2014, "cat": "marketing", "sub": "Digital Performance", "diff": "intermediate", "title": "Bounce Rate %", "q": "What percentage of website sessions leave without any further interaction?", "dax": "Bounce Rate % =\nDIVIDE (\n    SUM ( F_WebAnalytics[Bounces] ),\n    SUM ( F_WebAnalytics[Sessions] )\n)", "insight": "<strong>Benchmark: 40–60% is typical; below 40% is excellent.</strong> High bounce rate on landing pages from paid campaigns means the ad promise and landing page content are misaligned. Segment by traffic source to diagnose.", "tags": ["DIVIDE", "SUM", "Bounce Rate", "Website", "Digital", "Sessions"]}, {"id": 2015, "cat": "marketing", "sub": "Customer Acquisition", "diff": "advanced", "title": "Customer Acquisition Cost (CAC)", "q": "What is the total cost to acquire one new customer including all marketing and sales costs?", "dax": "CAC =\nVAR _totalCost =\n    [Total Marketing Spend]\n        + SUM ( F_Sales[SalesCost] )\nVAR _newCustomers =\n    [New Customers This Year]\nRETURN\n    DIVIDE ( _totalCost, _newCustomers )", "insight": "<strong>CAC includes both marketing AND sales costs.</strong> Many companies understate CAC by excluding sales salaries and commissions. True CAC is the only fair basis for LTV:CAC ratio calculation.", "tags": ["VAR", "DIVIDE", "CAC", "Acquisition", "Cost", "Marketing", "Sales"]}, {"id": 2016, "cat": "marketing", "sub": "Customer Acquisition", "diff": "advanced", "title": "LTV:CAC Ratio", "q": "How many times does customer lifetime value exceed the cost to acquire them?", "dax": "LTV to CAC Ratio =\nDIVIDE (\n    [Customer LTV],\n    [CAC]\n)", "insight": "<strong>The single most important marketing efficiency metric.</strong> Target 3:1 minimum — you earn £3 for every £1 spent on acquisition. Below 1:1 = loss-making. Above 5:1 = underinvesting in growth (spend more).", "tags": ["DIVIDE", "LTV", "CAC", "Ratio", "Marketing", "Efficiency"]}, {"id": 2017, "cat": "marketing", "sub": "Customer Acquisition", "diff": "intermediate", "title": "CAC Payback Period (Months)", "q": "How many months does it take to recoup the cost of acquiring a customer?", "dax": "CAC Payback Months =\nDIVIDE (\n    [CAC],\n    DIVIDE ( [Customer LTV], 12 )\n)", "insight": "<strong>Target under 12 months for healthy SaaS; under 6 months is excellent.</strong> Above 18 months means you are funding customer growth with significant upfront capital — raises cash flow risk.", "tags": ["DIVIDE", "CAC", "Payback", "Months", "LTV", "Marketing"]}, {"id": 2018, "cat": "marketing", "sub": "Brand & Retention", "diff": "intermediate", "title": "Email Open Rate %", "q": "What percentage of marketing emails sent were opened by recipients?", "dax": "Email Open Rate % =\nDIVIDE (\n    SUM ( F_EmailCampaigns[Opens] ),\n    SUM ( F_EmailCampaigns[Sent] )\n)", "insight": "<strong>Industry average: 20–25% across B2C; 25–35% for B2B.</strong> Below 15% signals poor list quality, bad subject lines, or deliverability issues. Above 35% indicates strong audience engagement.", "tags": ["DIVIDE", "SUM", "Email", "Open Rate", "Marketing", "Brand"]}, {"id": 2019, "cat": "marketing", "sub": "Brand & Retention", "diff": "intermediate", "title": "Email Click-to-Open Rate % (CTOR)", "q": "Of the people who opened the email, what percentage clicked a link?", "dax": "Email CTOR % =\nDIVIDE (\n    SUM ( F_EmailCampaigns[Clicks] ),\n    SUM ( F_EmailCampaigns[Opens] )\n)", "insight": "<strong>CTOR is more meaningful than raw click rate.</strong> It measures content relevance — did the email body engage those who were interested enough to open? Benchmark: 10–15%. Below 8% = body content or CTA needs work.", "tags": ["DIVIDE", "SUM", "CTOR", "Email", "Click", "Marketing"]}, {"id": 2020, "cat": "marketing", "sub": "Brand & Retention", "diff": "intermediate", "title": "Repeat Purchase Rate %", "q": "What percentage of customers have made more than one purchase?", "dax": "Repeat Purchase Rate % =\nDIVIDE (\n    CALCULATE (\n        DISTINCTCOUNT ( F_Sales[CustomerID] ),\n        FILTER (\n            Sales,\n            CALCULATE ( COUNTROWS ( Sales ) ) > 1\n        )\n    ),\n    [Active Customers]\n)", "insight": "<strong>Critical loyalty and retention metric.</strong> E-commerce benchmark: 25–40%. Below 20% = most customers buy once and leave — focus on post-purchase email, loyalty programmes, and product quality.", "tags": ["DIVIDE", "CALCULATE", "DISTINCTCOUNT", "FILTER", "Repeat Purchase", "Retention", "Loyalty"]}, {"id": 3001, "cat": "topbottom", "sub": "Top Performers — Name", "diff": "intermediate", "title": "Best Salesman Name", "q": "Who is the top-performing sales rep by total sales — name only?", "dax": "Best Salesman Name =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( F_Sales[RepID] ),\n        [Total Sales],\n        DESC\n    )\nRETURN\n    CONCATENATEX ( _topEntity, F_Sales[RepID], \", \" )", "insight": "<strong>Uses RepID as the identifier</strong> — if you have a separate Reps dimension with names, replace F_Sales[RepID] with M_Reps[RepName]. TOPN(1,...) always returns the single best performer. Responds to all slicers.", "tags": ["TOPN", "CONCATENATEX", "ALL", "VAR", "Rep", "Top"]}, {"id": 3002, "cat": "topbottom", "sub": "Top Performers — Name", "diff": "intermediate", "title": "Best Customer Name", "q": "Who is the highest-spending customer — name only?", "dax": "Best Customer Name =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( F_Sales[CustomerID] ),\n        [Total Sales],\n        DESC\n    )\nRETURN\n    CONCATENATEX ( _topEntity, F_Sales[CustomerID], \", \" )", "insight": "<strong>Returns CustomerID by default.</strong> If you have a Customers dimension, replace F_Sales[CustomerID] with M_Customers[CustomerName] for a readable display. Fully slicer-responsive.", "tags": ["TOPN", "CONCATENATEX", "ALL", "VAR", "Customer", "Top"]}, {"id": 3003, "cat": "topbottom", "sub": "Top Performers — Name", "diff": "intermediate", "title": "Best Selling Product Name", "q": "Which product generates the highest total sales — name only?", "dax": "Best Selling Product Name =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( M_Products[ProductName] ),\n        [Total Sales],\n        DESC\n    )\nRETURN\n    CONCATENATEX ( _topEntity, M_Products[ProductName], \", \" )", "insight": "<strong>Uses M_Products[ProductName]</strong> — ensure M_Products is related to F_Sales via ProductID. Change ALL(M_Products[ProductName]) to ALL(F_Sales[ProductID]) if you don't have a Products dimension.", "tags": ["TOPN", "CONCATENATEX", "ALL", "VAR", "Product", "Top"]}, {"id": 3004, "cat": "topbottom", "sub": "Bottom Performers — Name", "diff": "intermediate", "title": "Worst Salesman Name", "q": "Who is the lowest-performing sales rep by total sales — name only?", "dax": "Worst Salesman Name =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( F_Sales[RepID] ),\n        [Total Sales],\n        ASC\n    )\nRETURN\n    CONCATENATEX ( _topEntity, F_Sales[RepID], \", \" )", "insight": "<strong>ASC sort returns the lowest performer.</strong> Same structure as Best Salesman Name — only the sort direction changes. Use in performance reviews to identify coaching needs.", "tags": ["TOPN", "CONCATENATEX", "ALL", "VAR", "Rep", "Bottom"]}, {"id": 3005, "cat": "topbottom", "sub": "Bottom Performers — Name", "diff": "intermediate", "title": "Worst Customer Name", "q": "Which customer has the lowest total spend — name only?", "dax": "Worst Customer Name =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( F_Sales[CustomerID] ),\n        [Total Sales],\n        ASC\n    )\nRETURN\n    CONCATENATEX ( _topEntity, F_Sales[CustomerID], \", \" )", "insight": "<strong>Lowest-spending active customer.</strong> Useful for identifying at-risk or disengaged accounts. Combine with [Days Since Last Sale] per customer for a full churn-risk picture.", "tags": ["TOPN", "CONCATENATEX", "ALL", "VAR", "Customer", "Bottom"]}, {"id": 3006, "cat": "topbottom", "sub": "Bottom Performers — Name", "diff": "intermediate", "title": "Worst Selling Product Name", "q": "Which product generates the lowest total sales — name only?", "dax": "Worst Selling Product Name =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( M_Products[ProductName] ),\n        [Total Sales],\n        ASC\n    )\nRETURN\n    CONCATENATEX ( _topEntity, M_Products[ProductName], \", \" )", "insight": "<strong>Lowest-revenue product.</strong> Candidate for range rationalisation — but check margin and strategic role before delisting. A low-revenue product can be a footfall driver for higher-margin items.", "tags": ["TOPN", "CONCATENATEX", "ALL", "VAR", "Product", "Bottom"]}, {"id": 3007, "cat": "topbottom", "sub": "Top Performers — Name & Sales", "diff": "intermediate", "title": "Best Salesman (Name | Sales)", "q": "Who is the top sales rep — show their name and total sales with a pipe delimiter?", "dax": "Best Salesman (Name | Sales) =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( F_Sales[RepID] ),\n        [Total Sales],\n        DESC\n    )\nVAR _topName  = CONCATENATEX ( _topEntity, F_Sales[RepID], \", \" )\nVAR _topValue =\n    CALCULATE (\n        [Total Sales],\n        KEEPFILTERS ( _topEntity )\n    )\nRETURN\n    _topName & \" | \" & FORMAT ( _topValue, \"#,##0\" )", "insight": "<strong>Copy-paste template.</strong> To adapt: change F_Sales[RepID] to your name column, and [Total Sales] to any KPI measure. The FORMAT(#,##0) applies thousand-separator formatting.", "tags": ["TOPN", "CONCATENATEX", "CALCULATE", "FORMAT", "VAR", "Rep", "Top"]}, {"id": 3008, "cat": "topbottom", "sub": "Top Performers — Name & Sales", "diff": "intermediate", "title": "Best Customer (Name | Sales)", "q": "Who is the highest-spending customer — show their name and total sales with a pipe delimiter?", "dax": "Best Customer (Name | Sales) =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( F_Sales[CustomerID] ),\n        [Total Sales],\n        DESC\n    )\nVAR _topName  = CONCATENATEX ( _topEntity, F_Sales[CustomerID], \", \" )\nVAR _topValue =\n    CALCULATE (\n        [Total Sales],\n        KEEPFILTERS ( _topEntity )\n    )\nRETURN\n    _topName & \" | \" & FORMAT ( _topValue, \"#,##0\" )", "insight": "<strong>Card visual ready.</strong> Displays as e.g. 'CUST-0042 | 142,500'. Replace F_Sales[CustomerID] with M_Customers[CustomerName] if you have a customer dimension with names.", "tags": ["TOPN", "CONCATENATEX", "CALCULATE", "FORMAT", "VAR", "Customer", "Top"]}, {"id": 3009, "cat": "topbottom", "sub": "Top Performers — Name & Sales", "diff": "intermediate", "title": "Best Product (Name | Sales)", "q": "Which product is the top seller — show its name and total sales with a pipe delimiter?", "dax": "Best Product (Name | Sales) =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( M_Products[ProductName] ),\n        [Total Sales],\n        DESC\n    )\nVAR _topName  = CONCATENATEX ( _topEntity, M_Products[ProductName], \", \" )\nVAR _topValue =\n    CALCULATE (\n        [Total Sales],\n        KEEPFILTERS ( _topEntity )\n    )\nRETURN\n    _topName & \" | \" & FORMAT ( _topValue, \"#,##0\" )", "insight": "<strong>Executive summary KPI card.</strong> Displays as e.g. 'Widget Pro | 89,200'. Responds to all slicers — date, region, category. Change M_Products[ProductName] to any dimension column.", "tags": ["TOPN", "CONCATENATEX", "CALCULATE", "FORMAT", "VAR", "Product", "Top"]}, {"id": 3010, "cat": "topbottom", "sub": "Bottom Performers — Name & Sales", "diff": "intermediate", "title": "Worst Salesman (Name | Sales)", "q": "Who is the lowest-performing sales rep — show their name and total sales with a pipe delimiter?", "dax": "Worst Salesman (Name | Sales) =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( F_Sales[RepID] ),\n        [Total Sales],\n        ASC\n    )\nVAR _topName  = CONCATENATEX ( _topEntity, F_Sales[RepID], \", \" )\nVAR _topValue =\n    CALCULATE (\n        [Total Sales],\n        KEEPFILTERS ( _topEntity )\n    )\nRETURN\n    _topName & \" | \" & FORMAT ( _topValue, \"#,##0\" )", "insight": "<strong>Coaching target identifier.</strong> Only the TOPN sort direction (ASC) differs from the Best Salesman version. All other logic is identical — making it easy to copy and adapt.", "tags": ["TOPN", "CONCATENATEX", "CALCULATE", "FORMAT", "VAR", "Rep", "Bottom"]}, {"id": 3011, "cat": "topbottom", "sub": "Bottom Performers — Name & Sales", "diff": "intermediate", "title": "Worst Customer (Name | Sales)", "q": "Which customer has the lowest spend — show their name and total sales with a pipe delimiter?", "dax": "Worst Customer (Name | Sales) =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( F_Sales[CustomerID] ),\n        [Total Sales],\n        ASC\n    )\nVAR _topName  = CONCATENATEX ( _topEntity, F_Sales[CustomerID], \", \" )\nVAR _topValue =\n    CALCULATE (\n        [Total Sales],\n        KEEPFILTERS ( _topEntity )\n    )\nRETURN\n    _topName & \" | \" & FORMAT ( _topValue, \"#,##0\" )", "insight": "<strong>At-risk account signal.</strong> Lowest spend customer with their actual sales amount. Use to prioritise win-back or upsell outreach for the most disengaged active customer.", "tags": ["TOPN", "CONCATENATEX", "CALCULATE", "FORMAT", "VAR", "Customer", "Bottom"]}, {"id": 3012, "cat": "topbottom", "sub": "Bottom Performers — Name & Sales", "diff": "intermediate", "title": "Worst Product (Name | Sales)", "q": "Which product generates the least sales — show its name and total sales with a pipe delimiter?", "dax": "Worst Product (Name | Sales) =\nVAR _topEntity =\n    TOPN (\n        1,\n        ALL ( M_Products[ProductName] ),\n        [Total Sales],\n        ASC\n    )\nVAR _topName  = CONCATENATEX ( _topEntity, M_Products[ProductName], \", \" )\nVAR _topValue =\n    CALCULATE (\n        [Total Sales],\n        KEEPFILTERS ( _topEntity )\n    )\nRETURN\n    _topName & \" | \" & FORMAT ( _topValue, \"#,##0\" )", "insight": "<strong>Rationalisation candidate.</strong> Displays the product name alongside its actual sales figure for context. Before delisting, check if this product serves a strategic role (bundle anchor, entry-level product etc.).", "tags": ["TOPN", "CONCATENATEX", "CALCULATE", "FORMAT", "VAR", "Product", "Bottom"]}] as const;
